// frontend/src/user/components/NotificationCenter.jsx
// ============================================================
//  🔔 NotificationCenter — زنگوله اعلان‌های کاربر
//  ✅ v2:
//   - حذف http://localhost:8000 → مسیرهای نسبی با userAxios
//   - حذف toFa محلی → استفاده از utils/numbers
// ============================================================

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import userAxios from '../userAxios';
import { SiteImage } from '../../utils/SiteImage';
import { toFa } from '../../utils/numbers';

const POLL_INTERVAL_MS = 10000;
const MAX_DROPDOWN_ITEMS = 8;
const NOTIFICATIONS_LIMIT = 50;

// ===== آیکون و رنگ بر اساس type =====
const NOTIF_CONFIG = {
  order_status: {
    icon: '📦',
    iconKey: 'icon_orders',
    label: 'سفارش',
    color: 'brand',
  },
  payment_verified: {
    icon: '✅',
    iconKey: 'icon_check',
    label: 'پرداخت',
    color: 'accent',
  },
  payment_rejected: {
    icon: '❌',
    iconKey: 'icon_error',
    label: 'پرداخت',
    color: 'rose',
  },
  payment_unverified: {
    icon: '⚠️',
    iconKey: 'icon_warning',
    label: 'پرداخت',
    color: 'brand',
  },
  ticket_reply: {
    icon: '💬',
    iconKey: 'icon_chat',
    label: 'پشتیبانی',
    color: 'ink',
  },
  general: {
    icon: '🔔',
    iconKey: 'icon_bell',
    label: 'عمومی',
    color: 'ink',
  },
};

const COLOR_CLASSES = {
  brand: {
    iconBg: 'bg-brand-100 dark:bg-brand-500/20 text-brand-700 dark:text-brand-300',
    border: 'border-brand-200 dark:border-brand-500/30',
    dot: 'bg-brand-500',
    highlight: 'bg-brand-50/50 dark:bg-brand-500/5',
  },
  accent: {
    iconBg: 'bg-accent-100 dark:bg-accent-500/20 text-accent-700 dark:text-accent-300',
    border: 'border-accent-200 dark:border-accent-500/30',
    dot: 'bg-accent-500',
    highlight: 'bg-accent-50/50 dark:bg-accent-500/5',
  },
  rose: {
    iconBg: 'bg-rose-100 dark:bg-rose-500/20 text-rose-700 dark:text-rose-300',
    border: 'border-rose-200 dark:border-rose-500/30',
    dot: 'bg-rose-500',
    highlight: 'bg-rose-50/50 dark:bg-rose-500/5',
  },
  ink: {
    iconBg: 'bg-ink-100 dark:bg-ink-700 text-ink-700 dark:text-cream-200',
    border: 'border-ink-200 dark:border-dark-600',
    dot: 'bg-ink-500',
    highlight: 'bg-ink-100/50 dark:bg-ink-700/30',
  },
};

// ===== متن نسبی زمان فارسی =====
function safeDate(iso) {
  if (!iso) return null;
  let s = String(iso);
  if (!s.includes('Z') && !/[+-]\d{2}:?\d{2}$/.test(s)) {
    s = s + 'Z';
  }
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}

function toFaTimeAgo(iso) {
  const d = safeDate(iso);
  if (!d) return '—';
  const diff = Date.now() - d.getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return 'همین الان';
  if (mins < 60) return `${toFa(mins)} دقیقه پیش`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${toFa(hours)} ساعت پیش`;
  const days = Math.floor(hours / 24);
  if (days < 7) return `${toFa(days)} روز پیش`;
  return new Intl.DateTimeFormat('fa-IR', { month: 'short', day: 'numeric' }).format(d);
}

// ============================================================
//  کامپوننت اصلی
// ============================================================
export default function NotificationCenter({ onUnreadChange }) {
  const navigate = useNavigate();

  const [open, setOpen] = useState(false);
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [loading, setLoading] = useState(true);
  const [isMobile, setIsMobile] = useState(
    () => typeof window !== 'undefined' && window.innerWidth < 640
  );

  const containerRef = useRef(null);
  const panelRef = useRef(null);
  const isMountedRef = useRef(true);
  const lastSeenIdRef = useRef(null);

  // ===== Resize detection =====
  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < 640);
    window.addEventListener('resize', check);
    return () => window.removeEventListener('resize', check);
  }, []);

  // ===== Fetch notifications =====
  const fetchNotifications = useCallback(async (silent = false) => {
    if (!silent) setLoading(true);
    try {
      const res = await userAxios.get('/api/notifications', {
        params: { limit: NOTIFICATIONS_LIMIT },
      });
      if (!isMountedRef.current) return;

      const list = res.data?.notifications || [];
      const count = res.data?.unread_count || 0;

      setNotifications(list);
      setUnreadCount(count);
      if (onUnreadChange) onUnreadChange(count);

      if (list.length > 0) {
        lastSeenIdRef.current = list[0].id;
      }
    } catch (err) {
      // silent
    } finally {
      if (isMountedRef.current) setLoading(false);
    }
  }, [onUnreadChange]);

  // ===== Initial + polling =====
  useEffect(() => {
    isMountedRef.current = true;
    fetchNotifications(true);

    const id = setInterval(() => {
      if (isMountedRef.current && document.visibilityState === 'visible') {
        fetchNotifications(true);
      }
    }, POLL_INTERVAL_MS);

    const onVisible = () => {
      if (document.visibilityState === 'visible') fetchNotifications(true);
    };
    document.addEventListener('visibilitychange', onVisible);

    return () => {
      isMountedRef.current = false;
      clearInterval(id);
      document.removeEventListener('visibilitychange', onVisible);
    };
  }, [fetchNotifications]);

  // ===== Click outside =====
  useEffect(() => {
    if (!open) return;
    const handler = (e) => {
      if (isMobile) return;
      if (
        containerRef.current && !containerRef.current.contains(e.target) &&
        panelRef.current && !panelRef.current.contains(e.target)
      ) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    document.addEventListener('touchstart', handler);
    return () => {
      document.removeEventListener('mousedown', handler);
      document.removeEventListener('touchstart', handler);
    };
  }, [open, isMobile]);

  // ===== Escape =====
  useEffect(() => {
    if (!open) return;
    const handler = (e) => {
      if (e.key === 'Escape') setOpen(false);
    };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [open]);

  // ===== Body scroll lock (mobile) =====
  useEffect(() => {
    if (!open || !isMobile) return;
    const prev = document.body.style.overflow;
    const paddingRight = document.body.style.paddingRight;
    const scrollbarWidth = window.innerWidth - document.documentElement.clientWidth;
    document.body.style.overflow = 'hidden';
    if (scrollbarWidth > 0) {
      document.body.style.paddingRight = `${scrollbarWidth}px`;
    }
    return () => {
      document.body.style.overflow = prev || '';
      document.body.style.paddingRight = paddingRight || '';
    };
  }, [open, isMobile]);

  // ===== Click notification =====
  const handleClick = async (notif) => {
    setOpen(false);

    if (!notif.is_read) {
      try {
        await userAxios.put(`/api/notifications/${notif.id}/read`);
        setNotifications((prev) =>
          prev.map((n) => (n.id === notif.id ? { ...n, is_read: true } : n))
        );
        const newCount = Math.max(0, unreadCount - 1);
        setUnreadCount(newCount);
        if (onUnreadChange) onUnreadChange(newCount);
      } catch {
        /* silent */
      }
    }

    if (notif.link) {
      navigate(notif.link);
    }
  };

  // ===== Mark all read =====
  const handleMarkAllRead = async () => {
    try {
      await userAxios.put('/api/notifications/read-all');
      setNotifications((prev) => prev.map((n) => ({ ...n, is_read: true })));
      setUnreadCount(0);
      if (onUnreadChange) onUnreadChange(0);
    } catch {
      /* silent */
    }
  };

  const displayList = notifications.slice(0, MAX_DROPDOWN_ITEMS);
  const badgeText = unreadCount > 99 ? '99+' : toFa(unreadCount);

  return (
    <div className="relative" ref={containerRef}>
      {/* ===== Bell Button ===== */}
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className={`relative w-10 h-10 sm:w-11 sm:h-11 flex items-center justify-center rounded-xl transition touch-target ${
          open
            ? 'text-brand-600 dark:text-brand-400 bg-brand-50 dark:bg-brand-500/15'
            : 'text-ink-600 dark:text-cream-300 hover:text-brand-600 dark:hover:text-brand-400 hover:bg-brand-50 dark:hover:bg-brand-500/15'
        }`}
        aria-label={`اعلان‌ها${unreadCount > 0 ? `، ${unreadCount} مورد خوانده‌نشده` : ''}`}
        aria-expanded={open}
        aria-haspopup="menu"
        title="اعلان‌ها"
      >
        <svg
          className="w-5 h-5 sm:w-6 sm:h-6"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          aria-hidden="true"
        >
          <path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9" />
          <path d="M13.73 21a2 2 0 0 1-3.46 0" />
        </svg>
        {unreadCount > 0 && (
          <span className="absolute top-0.5 right-0.5 min-w-[18px] h-[18px] px-1 rounded-full bg-rose-500 text-white text-[10px] font-black flex items-center justify-center shadow-sm animate-pulse">
            {badgeText}
          </span>
        )}
      </button>

      {/* ===== Dropdown / Sheet ===== */}
      {open && (
        <>
          {isMobile && (
            <div
              className="fixed inset-0 bg-ink-900/50 backdrop-blur-sm z-[60]"
              onClick={() => setOpen(false)}
              aria-hidden="true"
            />
          )}

          <div
            ref={panelRef}
            role="menu"
            aria-label="لیست اعلان‌ها"
            className={
              isMobile
                ? 'fixed top-0 left-0 right-0 z-[61] max-h-[85vh] bg-paper-50 dark:bg-ink-800 rounded-b-3xl shadow-editorial overflow-hidden flex flex-col animate-slide-down'
                : 'absolute left-0 mt-2 w-[360px] max-w-[calc(100vw-2rem)] bg-paper-50 dark:bg-ink-800 rounded-2xl shadow-editorial overflow-hidden flex flex-col z-50 border border-ink-200 dark:border-dark-700 animate-slide-down'
            }
            style={isMobile ? { paddingTop: 'env(safe-area-inset-top, 0px)' } : undefined}
          >
            {isMobile && (
              <div className="w-12 h-1.5 bg-ink-300 dark:bg-dark-600 rounded-full mx-auto mt-2" />
            )}

            {/* Header */}
            <div className="flex items-center justify-between gap-2 px-4 py-3 border-b border-ink-200 dark:border-dark-700 flex-shrink-0">
              <div className="flex items-center gap-2 min-w-0">
                <h3 className="text-sm font-black text-ink-900 dark:text-cream-100">
                  اعلان‌ها
                </h3>
                {unreadCount > 0 && (
                  <span className="inline-flex items-center justify-center min-w-[20px] h-5 px-1.5 rounded-full bg-rose-500 text-white text-[10px] font-black">
                    {badgeText}
                  </span>
                )}
              </div>
              <div className="flex items-center gap-1">
                {unreadCount > 0 && (
                  <button
                    type="button"
                    onClick={handleMarkAllRead}
                    className="inline-flex items-center gap-1 text-[11px] font-black text-brand-600 dark:text-brand-400 hover:text-brand-800 dark:hover:text-brand-300 px-2.5 py-1.5 rounded-lg hover:bg-brand-50 dark:hover:bg-brand-500/15 active:bg-brand-100 transition touch-target"
                    title="همه را خوانده‌شده کن"
                  >
                    <SiteImage
                      imageKey="icon_check"
                      fallback="✓"
                      alt=""
                      className="w-3.5 h-3.5 object-contain"
                    />
                    <span>همه</span>
                  </button>
                )}
                {isMobile && (
                  <button
                    type="button"
                    onClick={() => setOpen(false)}
                    className="w-9 h-9 flex items-center justify-center rounded-lg text-ink-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-500/15 transition touch-target"
                    aria-label="بستن"
                  >
                    ✕
                  </button>
                )}
              </div>
            </div>

            {/* List */}
            <div className="flex-1 overflow-y-auto overscroll-contain">
              {loading && notifications.length === 0 ? (
                <div className="p-5 sm:p-6 text-center text-xs text-ink-500 dark:text-cream-400 font-bold">
                  <div className="inline-block w-6 h-6 border-2 border-brand-500 border-t-transparent rounded-full animate-spin mb-2" />
                  <div>در حال بارگذاری...</div>
                </div>
              ) : displayList.length === 0 ? (
                <div className="p-5 sm:p-6 text-center">
                  <div
                    className="w-12 h-12 mx-auto mb-3 opacity-50"
                    aria-hidden="true"
                  >
                    <SiteImage
                      imageKey="icon_bell"
                      fallback="🔔"
                      alt=""
                      className="w-full h-full object-contain"
                    />
                  </div>
                  <div className="text-sm text-ink-600 dark:text-cream-300 font-black mb-1">
                    هیچ اعلانی نداری
                  </div>
                  <div className="text-xs text-ink-400 dark:text-cream-500">
                    وقتی اتفاق جدیدی بیفته، اینجا نمایش داده می‌شه
                  </div>
                </div>
              ) : (
                <ul className="divide-y divide-ink-100 dark:divide-dark-700">
                  {displayList.map((n) => {
                    const cfg = NOTIF_CONFIG[n.type] || NOTIF_CONFIG.general;
                    const cls = COLOR_CLASSES[cfg.color] || COLOR_CLASSES.ink;

                    return (
                      <li key={n.id}>
                        <button
                          type="button"
                          onClick={() => handleClick(n)}
                          className={`w-full text-right flex items-start gap-3 p-3 hover:bg-paper-100 dark:hover:bg-ink-700/50 active:bg-paper-200 dark:active:bg-ink-700 transition ${
                            !n.is_read ? cls.highlight : ''
                          }`}
                        >
                          <div
                            className={`w-9 h-9 rounded-xl flex items-center justify-center text-base flex-shrink-0 border ${cls.border} ${cls.iconBg}`}
                            aria-hidden="true"
                          >
                            <SiteImage
                              imageKey={cfg.iconKey}
                              fallback={cfg.icon}
                              alt=""
                              className="w-5 h-5 object-contain"
                            />
                          </div>

                          <div className="flex-1 min-w-0">
                            <div className="flex items-start gap-1.5 mb-0.5">
                              <span className="text-xs font-black text-ink-900 dark:text-cream-100 leading-tight flex-1 min-w-0 break-safe">
                                {n.title}
                              </span>
                              {!n.is_read && (
                                <span
                                  className={`w-1.5 h-1.5 rounded-full flex-shrink-0 mt-1.5 ${cls.dot}`}
                                  aria-label="خوانده‌نشده"
                                />
                              )}
                            </div>
                            {n.message && (
                              <div className="text-[11px] text-ink-600 dark:text-cream-300 leading-relaxed line-clamp-2 mt-0.5">
                                {n.message}
                              </div>
                            )}
                            <div className="text-[10px] text-ink-400 dark:text-cream-500 mt-1">
                              {toFaTimeAgo(n.created_at)}
                            </div>
                          </div>
                        </button>
                      </li>
                    );
                  })}
                </ul>
              )}
            </div>

            {/* Footer */}
            <div className="border-t border-ink-200 dark:border-dark-700 p-2 flex-shrink-0">
              <button
                type="button"
                onClick={() => {
                  setOpen(false);
                  navigate('/panel/notifications');
                }}
                className="w-full min-h-[44px] flex items-center justify-center gap-1.5 text-xs font-black text-brand-600 dark:text-brand-400 hover:bg-brand-50 dark:hover:bg-brand-500/15 active:bg-brand-100 rounded-xl transition touch-target"
              >
                <span>مشاهدهٔ همهٔ اعلان‌ها</span>
                <span aria-hidden="true">←</span>
              </button>
            </div>
          </div>
        </>
      )}
    </div>
  );
}
