// frontend/src/user/components/Skeleton.jsx
import React from 'react';

// ============================================================
//  🎨 کلاس پایه — Editorial palette
//  - کاغذی روشن در light mode
//  - ink-700 تیره در dark mode
// ============================================================
const baseClass =
  'animate-pulse bg-paper-200 dark:bg-ink-700/60 rounded';

// ============================================================
//  🃏 کلاس پایه کارت — توکن‌های editorial مشترک
// ============================================================
const cardClass =
  'bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 shadow-soft';

// ============================================================
//  ♿ Wrapper — برای اعلام وضعیت لود به screen reader
// ============================================================
function LoadingRegion({ children, className = '', label = 'در حال بارگذاری' }) {
  return (
    <div
      role="status"
      aria-live="polite"
      aria-label={label}
      className={className}
    >
      <span className="sr-only">{label}</span>
      {children}
    </div>
  );
}

// ============================================================
//  🧱 Skeleton پایه — هر اندازه‌ای
//  استفاده:
//    <Skeleton className="h-4 w-32" />
//    <Skeleton className="h-10 w-10 rounded-full" />
// ============================================================
export function Skeleton({ className = '', style }) {
  return (
    <div
      className={`${baseClass} ${className}`}
      style={style}
      aria-hidden="true"
    />
  );
}

// ============================================================
//  ➖ Skeleton خطی
// ============================================================
export function SkeletonLine({
  width = 'w-full',
  height = 'h-4',
  className = '',
}) {
  return (
    <div
      className={`${baseClass} ${width} ${height} ${className}`}
      aria-hidden="true"
    />
  );
}

// ============================================================
//  👤 Skeleton آواتار — قابل استفاده در DogCard, Profile, Ticket
// ============================================================
export function SkeletonAvatar({ size = 'md', className = '' }) {
  const sizeCls = {
    sm: 'w-8 h-8',
    md: 'w-11 h-11',
    lg: 'w-16 h-16',
    xl: 'w-20 h-20',
  }[size] || 'w-11 h-11';

  return (
    <div
      className={`${baseClass} ${sizeCls} rounded-2xl flex-shrink-0 ${className}`}
      aria-hidden="true"
    />
  );
}

// ============================================================
//  📊 Skeleton کارت آماری (Dashboard)
// ============================================================
export function SkeletonStatCard({ className = '' }) {
  return (
    <div className={`${cardClass} rounded-2xl sm:rounded-3xl p-4 sm:p-5 ${className}`}>
      <div className="flex items-center justify-between mb-3 sm:mb-4">
        <Skeleton className="w-8 h-8 sm:w-9 sm:h-9 rounded-xl" />
        <Skeleton className="w-12 sm:w-16 h-3" />
      </div>
      <Skeleton className="w-20 sm:w-28 h-6 sm:h-7 mb-2 sm:mb-2.5" />
      <Skeleton className="w-14 sm:w-20 h-3" />
    </div>
  );
}

// ============================================================
//  📈 Skeleton نمودار (Dashboard chart)
// ============================================================
export function SkeletonChart({
  height = 'h-40 sm:h-48',
  className = '',
}) {
  return (
    <div className={`${cardClass} rounded-3xl p-4 sm:p-5 ${className}`}>
      <div className="flex items-center justify-between mb-3 sm:mb-4">
        <Skeleton className="h-5 w-1/3" />
        <Skeleton className="h-4 w-16 sm:w-20" />
      </div>
      <div className={`${height} flex items-end gap-1.5 sm:gap-2`}>
        {Array.from({ length: 7 }).map((_, i) => {
          const heights = [
            'h-1/3',
            'h-2/3',
            'h-1/2',
            'h-3/4',
            'h-2/5',
            'h-5/6',
            'h-1/2',
          ];
          return (
            <Skeleton
              key={i}
              className={`flex-1 ${heights[i % heights.length]} rounded-t-2xl`}
            />
          );
        })}
      </div>
    </div>
  );
}

// ============================================================
//  📋 Skeleton جدول — responsive (mobile: cards, desktop: table)
//  ✅ FIX: پس‌زمینهٔ اضافی mobile cards حذف شد
// ============================================================
export function SkeletonTable({
  rows = 5,
  cols = 6,
  showHeader = true,
  className = '',
}) {
  return (
    <LoadingRegion
      className={`${cardClass} rounded-3xl overflow-hidden ${className}`}
      label="در حال بارگذاری جدول"
    >
      {/* ===== دسکتاپ: جدول ===== */}
      <div className="hidden lg:block">
        {showHeader && (
          <div className="bg-paper-100 dark:bg-ink-900/50 border-b border-ink-200 dark:border-dark-700 px-5 py-3.5 flex items-center gap-4">
            {Array.from({ length: cols }).map((_, i) => (
              <Skeleton
                key={i}
                className="h-4 flex-1"
                style={{ minWidth: '60px' }}
              />
            ))}
          </div>
        )}
        <div className="divide-y divide-ink-200 dark:divide-dark-700">
          {Array.from({ length: rows }).map((_, r) => (
            <div key={r} className="px-5 py-4 flex items-center gap-4">
              {Array.from({ length: cols }).map((_, c) => (
                <Skeleton
                  key={c}
                  className={`h-4 flex-1 ${c === 0 ? 'max-w-[40px]' : ''}`}
                />
              ))}
            </div>
          ))}
        </div>
      </div>

      {/* ===== موبایل: کارت‌ها ===== */}
      <div className="lg:hidden p-4 space-y-3">
        {Array.from({ length: rows }).map((_, r) => (
          <div
            key={r}
            className="border border-ink-200 dark:border-dark-700 rounded-2xl p-4 bg-transparent"
          >
            {/* هدر کارت */}
            <div className="flex items-center justify-between mb-4">
              <Skeleton className="h-5 w-16" />
              <Skeleton className="h-6 w-20 rounded-full" />
            </div>

            {/* محتوا */}
            <div className="space-y-2.5 mb-4">
              <Skeleton className="h-3 w-full" />
              <Skeleton className="h-3 w-3/4" />
            </div>

            {/* ۲x۲ grid */}
            <div className="grid grid-cols-2 gap-2.5 mb-4">
              <Skeleton className="h-9 rounded-xl" />
              <Skeleton className="h-9 rounded-xl" />
            </div>

            {/* اکشن‌ها */}
            <div className="flex items-center gap-2.5 pt-4 border-t border-ink-200 dark:border-dark-700">
              <Skeleton className="h-10 flex-1 rounded-xl" />
              <Skeleton className="h-10 w-10 rounded-xl" />
              <Skeleton className="h-10 w-10 rounded-xl" />
            </div>
          </div>
        ))}
      </div>
    </LoadingRegion>
  );
}

// ============================================================
//  🃏 Skeleton کارت ساده (Profile, Settings, general)
// ============================================================
export function SkeletonCard({ lines = 3, className = '' }) {
  return (
    <div className={`${cardClass} rounded-3xl p-5 sm:p-6 ${className}`}>
      <Skeleton className="h-6 w-1/3 mb-4 sm:mb-5 rounded-xl" />
      <div className="space-y-3">
        {Array.from({ length: lines }).map((_, i) => (
          <Skeleton
            key={i}
            className={`h-4 ${i % 2 === 0 ? 'w-full' : 'w-2/3'}`}
          />
        ))}
      </div>
    </div>
  );
}

// ============================================================
//  📦 Skeleton ردیف سفارش
//  ✅ FIX: باگ sizing — `h-9 w-9 sm:h-9 sm:w-16` → `h-9 w-9 sm:w-16`
// ============================================================
export function SkeletonOrderRow({ className = '' }) {
  return (
    <div
      className={`${cardClass} rounded-2xl p-4 flex items-center gap-3.5 ${className}`}
    >
      <Skeleton className="w-12 h-12 rounded-2xl flex-shrink-0" />
      <div className="flex-1 min-w-0">
        <Skeleton className="h-4 w-3/4 mb-2.5" />
        <Skeleton className="h-3 w-1/2" />
      </div>
      <Skeleton className="hidden sm:block h-6 w-20 rounded-lg flex-shrink-0" />
      <Skeleton className="h-9 w-9 sm:w-16 rounded-xl flex-shrink-0" />
    </div>
  );
}

// ============================================================
//  🐕 Skeleton کارت سگ (MyDogs, DogDetail)
// ============================================================
export function SkeletonDogCard({ className = '' }) {
  return (
    <div className={`${cardClass} rounded-3xl overflow-hidden ${className}`}>
      {/* نوار رنگی بالای کارت */}
      <Skeleton className="h-1.5 rounded-none" />

      <div className="p-5 sm:p-6">
        {/* هدر: آواتار + نام */}
        <div className="flex items-start gap-4 mb-5">
          <Skeleton className="w-16 h-16 rounded-2xl flex-shrink-0" />
          <div className="flex-1 min-w-0">
            <Skeleton className="h-5 w-24 mb-2.5" />
            <Skeleton className="h-3 w-20 mb-2" />
            <Skeleton className="h-3 w-28" />
          </div>
        </div>

        {/* Badges */}
        <div className="flex flex-wrap gap-2 mb-4">
          <Skeleton className="h-6 w-20 rounded-full" />
          <Skeleton className="h-6 w-20 rounded-full" />
          <Skeleton className="h-6 w-16 rounded-full" />
        </div>

        {/* Alert */}
        <Skeleton className="h-9 w-full rounded-xl mb-4" />

        {/* Actions */}
        <div className="flex items-center gap-2.5 pt-5 border-t border-ink-200 dark:border-dark-700">
          <Skeleton className="h-10 flex-1 rounded-xl" />
          <Skeleton className="h-10 w-10 rounded-xl" />
          <Skeleton className="h-10 w-10 rounded-xl" />
        </div>
      </div>
    </div>
  );
}

// ============================================================
//  🎫 Skeleton ردیف تیکت (TicketsList)
// ============================================================
export function SkeletonTicketRow({ className = '' }) {
  return (
    <div className={`${cardClass} rounded-2xl p-3.5 sm:p-4 ${className}`}>
      <div className="flex items-start gap-3">
        <Skeleton className="w-10 h-10 sm:w-11 sm:h-11 rounded-full flex-shrink-0" />
        <div className="flex-1 min-w-0">
          {/* عنوان */}
          <Skeleton className="h-4 w-2/3 mb-2" />
          {/* متادیتا: آیدی + اولویت */}
          <div className="flex items-center gap-2 mb-2">
            <Skeleton className="h-3 w-12" />
            <Skeleton className="h-5 w-16 rounded-full" />
          </div>
          {/* آخرین پیام */}
          <Skeleton className="h-3 w-full mb-1" />
          <Skeleton className="h-3 w-4/5" />
        </div>
        {/* دکمه اکشن */}
        <Skeleton className="hidden sm:block h-6 w-20 rounded-full flex-shrink-0" />
      </div>
    </div>
  );
}

// ============================================================
//  🎯 Skeleton ردیف‌های فیلتر Chips (Filters section)
// ============================================================
export function SkeletonFilterChips({ count = 5, className = '' }) {
  return (
    <div className={`flex items-center gap-2 overflow-hidden ${className}`}>
      {Array.from({ length: count }).map((_, i) => (
        <Skeleton
          key={i}
          className="h-9 rounded-2xl flex-shrink-0"
          style={{ width: `${60 + (i % 3) * 20}px` }}
        />
      ))}
    </div>
  );
}

// ============================================================
//  🖼️ Skeleton گرید کارت (Dashboard stats grid)
// ============================================================
export function SkeletonGrid({ items = 4, cols = 4, className = '' }) {
  const gridCols = {
    2: 'grid-cols-1 sm:grid-cols-2',
    3: 'grid-cols-1 sm:grid-cols-2 md:grid-cols-3',
    4: 'grid-cols-2 md:grid-cols-3 lg:grid-cols-4',
    5: 'grid-cols-2 md:grid-cols-3 lg:grid-cols-5',
    6: 'grid-cols-2 md:grid-cols-3 lg:grid-cols-6',
  }[cols] || 'grid-cols-2 md:grid-cols-3 lg:grid-cols-4';

  return (
    <div className={`grid ${gridCols} gap-3 ${className}`}>
      {Array.from({ length: items }).map((_, i) => (
        <SkeletonStatCard key={i} />
      ))}
    </div>
  );
}

// ============================================================
//  📤 Export پیش‌فرض — Skeleton پایه
// ============================================================
export default Skeleton;