// ============================================================
//  Avatar gradients
// ============================================================
const AVATAR_GRADIENTS = [
  'from-brand-500 to-brand-700',
  'from-accent-500 to-accent-700',
  'from-rose-500 to-rose-700',
  'from-ink-600 to-ink-800',
  'from-brand-400 to-brand-600',
  'from-accent-400 to-accent-600',
];

const getAvatarGradient = (id) => AVATAR_GRADIENTS[(id || 0) % AVATAR_GRADIENTS.length];

const getAllergensCount = (dog) => {
  if (!dog) return 0;
  if (Array.isArray(dog.allergens) && dog.allergens.length > 0) return dog.allergens.length;

  const atype = (dog.allergy_type || '').trim().toLowerCase();
  const hasType = atype && atype !== 'none' && atype !== 'multiple';
  const details = (dog.allergy_details || '').trim();
  if (!hasType && !details) return 0;
  if (hasType && !details) return 1;

  let count = hasType ? 1 : 0;
  let d = details;
  for (const sep of [',', '،', ';', '؛']) {
    d = d.replace(sep, ',');
  }
  count += d.split(',').filter(p => p.trim()).length;
  return count;
};

