function HelpIcon({ field }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  const text = FIELD_HELP_TEXT[field];

  useEffect(() => {
    if (!open) return;
    const handler = (e) => {
      if (ref.current && !ref.current.contains(e.target)) setOpen(false);
    };
    document.addEventListener('mousedown', handler);
    document.addEventListener('touchstart', handler);
    return () => {
      document.removeEventListener('mousedown', handler);
      document.removeEventListener('touchstart', handler);
    };
  }, [open]);

  if (!text) return null;

  return (
    <span className="relative inline-flex" ref={ref}>
      <button
        type="button"
        onClick={(e) => { e.preventDefault(); e.stopPropagation(); setOpen(!open); }}
        onMouseEnter={() => setOpen(true)}
        onMouseLeave={() => setOpen(false)}
        className="inline-flex items-center justify-center w-4 h-4 rounded-full text-[10px] font-bold text-ink-400 dark:text-cream-500 hover:text-brand-600 dark:hover:text-brand-400 hover:bg-brand-50 dark:hover:bg-brand-500/10 transition-colors flex-shrink-0"
        aria-label="راهنما"
      >
        <SiteImage
          imageKey="icon_faq"
          fallback="?"
          alt="راهنما"
          className="w-3 h-3 object-contain"
        />
      </button>
      {open && (
        <div
          className="absolute top-full right-0 mt-1.5 w-56 max-w-[calc(100vw-2rem)] bg-ink-900 dark:bg-ink-950 text-cream-100 rounded-md p-2.5 z-[60] text-[11px] leading-relaxed shadow-lg border border-white/10"
          onMouseEnter={() => setOpen(true)}
          onMouseLeave={() => setOpen(false)}
        >
          {text}
        </div>
      )}
    </span>
  );
}

