// frontend/src/user/pages/TicketDetail.jsx
import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import userAxios from '../userAxios';
import { useToast } from '../components/Toast';
import { Skeleton } from '../components/Skeleton';
import { SiteImage } from '../../utils/SiteImage';

// ✅ NEW: Import helpers اعداد و تاریخ فارسی
import { toFa, toFaDateTime, toFaTime } from '../../utils/numbers';

// ============================================================
//  🎨 نگاشت وضعیت‌ها — Editorial palette
// ============================================================
const STATUS_LABELS = {
  open: {
    text: 'باز (منتظر پاسخ پشتیبانی)',
    color: 'bg-brand-50 dark:bg-brand-500/15 text-brand-700 dark:text-brand-300 border-brand-200 dark:border-brand-500/30',
    icon: '📬',
    iconKey: 'icon_ticket',
    dot: 'bg-brand-500',
    soft: 'bg-brand-100 dark:bg-brand-500/20 text-brand-700 dark:text-brand-300',
  },
  admin_reply: {
    text: 'پاسخ داده شده',
    color: 'bg-accent-50 dark:bg-accent-500/15 text-accent-700 dark:text-accent-300 border-accent-200 dark:border-accent-500/30',
    icon: '💬',
    iconKey: 'icon_chat',
    dot: 'bg-accent-500',
    soft: 'bg-accent-100 dark:bg-accent-500/20 text-accent-700 dark:text-accent-300',
  },
  user_reply: {
    text: 'پاسخ شما ثبت شد',
    color: 'bg-brand-100 dark:bg-brand-500/20 text-brand-800 dark:text-brand-200 border-brand-300 dark:border-brand-500/40',
    icon: '📩',
    iconKey: 'icon_reply',
    dot: 'bg-brand-700',
    soft: 'bg-brand-100 dark:bg-brand-500/20 text-brand-700 dark:text-brand-300',
  },
  closed: {
    text: 'بسته شده',
    color: 'bg-ink-100 dark:bg-ink-700 text-ink-700 dark:text-cream-200 border-ink-200 dark:border-dark-600',
    icon: '🔒',
    iconKey: 'icon_lock',
    dot: 'bg-ink-400',
    soft: 'bg-ink-100 dark:bg-ink-700 text-ink-700 dark:text-cream-200',
  },
};

const PRIORITY_LABELS = {
  low:    { text: 'پایین',  icon: '🟢', iconKey: 'icon_priority_low',    color: 'bg-accent-50 dark:bg-accent-500/15 text-accent-700 dark:text-accent-300 border-accent-200 dark:border-accent-500/30' },
  medium: { text: 'متوسط', icon: '🟡', iconKey: 'icon_priority_medium', color: 'bg-brand-50 dark:bg-brand-500/15 text-brand-700 dark:text-brand-300 border-brand-200 dark:border-brand-500/30' },
  high:   { text: 'بالا',   icon: '🔴', iconKey: 'icon_priority_high',   color: 'bg-rose-50 dark:bg-rose-500/15 text-rose-700 dark:text-rose-300 border-rose-200 dark:border-rose-500/30' },
};

const POLL_INTERVAL_MS = 10000;

// ============================================================
//  کامپوننت اصلی
// ============================================================
export default function TicketDetail() {
  const { ticketId } = useParams();
  const navigate = useNavigate();
  const { showToast } = useToast();

  const [ticket, setTicket] = useState(null);
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(true);
  const [replyMessage, setReplyMessage] = useState('');
  const [sending, setSending] = useState(false);
  const [lastUpdated, setLastUpdated] = useState(null);

  const isMountedRef = useRef(true);
  const lastMsgCountRef = useRef(0);
  const messagesEndRef = useRef(null);
  const chatContainerRef = useRef(null);

  // ============================================================
  //  Fetch
  // ============================================================
  const fetchDetail = useCallback(async (silent = false) => {
    if (!silent) setLoading(true);
    try {
      const res = await userAxios.get(`/api/tickets/${ticketId}`);
      const msgs = res.data.messages || [];

      // اعلان پیام جدید ادمین
      if (silent && msgs.length > lastMsgCountRef.current) {
        const newMsgs = msgs.slice(lastMsgCountRef.current);
        if (newMsgs.some(m => m.sender_type === 'admin')) {
          showToast('info', 'پیام جدیدی از پشتیبانی رسید', { duration: 4000 });
        }
      }

      setTicket(res.data.ticket);
      setMessages(msgs);
      lastMsgCountRef.current = msgs.length;
      setLastUpdated(new Date());
    } catch (err) {
      if (!silent) {
        showToast('error', err.response?.data?.detail || 'خطا در دریافت تیکت');
        navigate('/panel/tickets');
      }
    } finally {
      if (!silent) setLoading(false);
    }
  }, [ticketId, navigate, showToast]);

  // ============================================================
  //  Polling
  // ============================================================
  useEffect(() => {
    isMountedRef.current = true;
    fetchDetail();

    const id = setInterval(() => {
      if (isMountedRef.current && document.visibilityState === 'visible') {
        fetchDetail(true);
      }
    }, POLL_INTERVAL_MS);

    return () => {
      isMountedRef.current = false;
      clearInterval(id);
    };
  }, [fetchDetail]);

  // ============================================================
  //  Scroll to bottom
  // ============================================================
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' });
  }, [messages.length]);

  // ============================================================
  //  Send reply
  // ============================================================
  const handleSendReply = async (e) => {
    e.preventDefault();
    if (!replyMessage.trim() || replyMessage.trim().length < 2) {
      showToast('error', 'متن پیام نمی‌تواند خالی باشد');
      return;
    }
    setSending(true);
    try {
      await userAxios.post(`/api/tickets/${ticketId}/messages`, {
        message: replyMessage.trim(),
      });
      setReplyMessage('');
      await fetchDetail(true);
      showToast('success', 'پاسخ ارسال شد');
    } catch (err) {
      showToast('error', err.response?.data?.detail || 'خطا در ارسال');
    } finally {
      setSending(false);
    }
  };

  // ============================================================
  //  Loading
  // ============================================================
  if (loading) {
    return (
      <div className="max-w-3xl mx-auto space-y-4" dir="rtl">
        <Skeleton className="h-8 w-48 rounded-xl" />
        <Skeleton className="h-36 rounded-3xl" />
        <Skeleton className="h-96 rounded-3xl" />
      </div>
    );
  }

  if (!ticket) return null;

  const cfg = STATUS_LABELS[ticket.status] || STATUS_LABELS.open;
  const isClosed = ticket.status === 'closed';
  const priorityCfg = PRIORITY_LABELS[ticket.priority];

  return (
    <div className="max-w-3xl mx-auto space-y-4" dir="rtl">

      {/* ============================================================ */}
      {/*  Back link — ✅ آیکون از SiteImage                           */}
      {/* ============================================================ */}
      <Link
        to="/panel/tickets"
        className="inline-flex items-center gap-1.5 min-h-[44px] px-1 text-sm text-ink-500 dark:text-cream-400 hover:text-brand-600 dark:hover:text-brand-400 font-black transition touch-target group"
      >
        <span
          className="w-3.5 h-3.5 inline-flex items-center justify-center group-hover:-translate-x-1 transition-transform flex-shrink-0"
          aria-hidden="true"
        >
          <SiteImage
            imageKey="icon_arrow_back"
            fallback="→"
            alt=""
            className="w-full h-full object-contain"
          />
        </span>
        <span>بازگشت به لیست تیکت‌ها</span>
      </Link>

      {/* ============================================================ */}
      {/*  Header Card — Editorial                                     */}
      {/* ============================================================ */}
      <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft overflow-hidden">

        {/* Strip رنگی بالا */}
        <div className={`h-1.5 ${cfg.dot}`} aria-hidden="true" />

        <div className="p-5 sm:p-6">

          {/* Icon + Subject + Meta */}
          <div className="flex items-start gap-4 mb-4">
            <div className={`w-12 h-12 sm:w-14 sm:h-14 rounded-2xl flex items-center justify-center p-3 flex-shrink-0 shadow-soft ${
              isClosed
                ? 'bg-ink-100 dark:bg-ink-700 text-ink-600 dark:text-cream-300'
                : 'bg-brand-gradient text-white shadow-brand'
            }`} aria-hidden="true">
              <SiteImage
                imageKey={cfg.iconKey}
                fallback={cfg.icon}
                alt=""
                className="w-full h-full object-contain"
              />
            </div>

            <div className="flex-1 min-w-0">
              <h1 className="font-display font-black text-ink-900 dark:text-cream-100 text-base sm:text-xl leading-snug tracking-tight break-safe mb-2">
                {ticket.subject}
              </h1>

              <div className="flex items-center gap-2 text-[10px] sm:text-[11px] text-ink-500 dark:text-cream-400 flex-wrap">
                <span className="font-num font-black text-ink-700 dark:text-cream-200">
                  تیکت #{toFa(ticket.id)}
                </span>
                {ticket.created_at && (
                  <>
                    <span className="text-ink-300 dark:text-dark-600" aria-hidden="true">·</span>
                    <span className="flex items-center gap-1">
                      <span className="w-3 h-3" aria-hidden="true">
                        <SiteImage
                          imageKey="icon_clock"
                          fallback="🗓️"
                          alt=""
                          className="w-full h-full object-contain"
                        />
                      </span>
                      <span>{toFaDateTime(ticket.created_at)}</span>
                    </span>
                  </>
                )}
                {priorityCfg && (
                  <>
                    <span className="text-ink-300 dark:text-dark-600" aria-hidden="true">·</span>
                    <span className="inline-flex items-center gap-1">
                      <span className="w-3 h-3" aria-hidden="true">
                        <SiteImage
                          imageKey={priorityCfg.iconKey}
                          fallback={priorityCfg.icon}
                          alt=""
                          className="w-full h-full object-contain"
                        />
                      </span>
                      <span>اولویت {priorityCfg.text}</span>
                    </span>
                  </>
                )}
              </div>
            </div>
          </div>

          {/* Status row */}
          <div className="flex items-center justify-between gap-3 flex-wrap pt-3 border-t border-ink-200 dark:border-dark-700">
            <span className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-full text-[10px] sm:text-[11px] font-black border ${cfg.color} whitespace-nowrap`}>
              <span className={`w-1.5 h-1.5 rounded-full ${cfg.dot} ${!isClosed ? 'animate-pulse' : ''}`} aria-hidden="true" />
              <span>{cfg.text}</span>
            </span>

            {lastUpdated && (
              <div className="text-[10px] text-ink-400 dark:text-cream-500 flex items-center gap-1.5 whitespace-nowrap">
                <span className="w-1.5 h-1.5 rounded-full bg-accent-400 animate-pulse" aria-hidden="true" />
                <span>بروزرسانی خودکار هر ۱۰ ثانیه</span>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* ============================================================ */}
      {/*  Chat Container — Editorial                                  */}
      {/* ============================================================ */}
      <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft overflow-hidden flex flex-col">

        {/* Messages header */}
        <div className="px-4 sm:px-5 py-3 sm:py-4 border-b border-ink-200 dark:border-dark-700 flex items-center justify-between gap-3">
          <div className="flex items-center gap-2.5 text-xs font-black text-ink-800 dark:text-cream-100 min-w-0">
            <span className="w-4 h-4 flex-shrink-0" aria-hidden="true">
              <SiteImage
                imageKey="icon_chat"
                fallback="💬"
                alt=""
                className="w-full h-full object-contain"
              />
            </span>
            <span className="font-display">گفتگو</span>
            <span className="text-[10px] bg-paper-100 dark:bg-ink-700 text-ink-600 dark:text-cream-300 px-2 py-0.5 rounded-full font-num font-black whitespace-nowrap">
              {toFa(messages.length)} پیام
            </span>
          </div>

          {lastUpdated && (
            <div className="text-[10px] text-ink-400 dark:text-cream-500 font-num whitespace-nowrap flex-shrink-0">
              {toFaTime(lastUpdated, { hour: '2-digit', minute: '2-digit' })}
            </div>
          )}
        </div>

        {/* Messages list */}
        <div
          ref={chatContainerRef}
          className="p-4 space-y-4 max-h-[60vh] sm:max-h-[500px] overflow-y-auto bg-paper-100/40 dark:bg-ink-900/40"
        >
          {messages.length === 0 ? (
            <div className="text-center py-12">
              <div className="w-12 h-12 mx-auto mb-3 opacity-50" aria-hidden="true">
                <SiteImage
                  imageKey="icon_chat"
                  fallback="💬"
                  alt=""
                  className="w-full h-full object-contain"
                />
              </div>
              <div className="text-xs sm:text-sm text-ink-500 dark:text-cream-400 font-bold">
                هنوز پیامی ثبت نشده است
              </div>
            </div>
          ) : (
            messages.map((msg, idx) => {
              const isUser = msg.sender_type === 'user';
              const prevMsg = idx > 0 ? messages[idx - 1] : null;
              const showAvatar = !prevMsg || prevMsg.sender_type !== msg.sender_type;

              return (
                <div
                  key={msg.id}
                  className={`flex gap-2 items-end ${isUser ? 'flex-row-reverse' : 'flex-row'}`}
                >
                  {/* Avatar */}
                  <div className={`w-8 h-8 sm:w-9 sm:h-9 rounded-2xl flex items-center justify-center p-2 flex-shrink-0 shadow-soft ${
                    showAvatar ? 'opacity-100' : 'opacity-0'
                  } ${
                    isUser
                      ? 'bg-brand-gradient text-white'
                      : 'bg-gradient-to-br from-accent-500 to-accent-700 text-white'
                  }`} aria-hidden="true">
                    <SiteImage
                      imageKey={isUser ? 'icon_user' : 'icon_admin'}
                      fallback={isUser ? '👤' : '👨‍💼'}
                      alt=""
                      className="w-full h-full object-contain"
                    />
                  </div>

                  {/* Bubble */}
                  <div className="max-w-[85%] sm:max-w-[75%] group">

                    {/* Sender name + time */}
                    {showAvatar && (
                      <div className={`flex items-center gap-2 mb-1.5 px-1 flex-wrap ${
                        isUser ? 'justify-end' : 'justify-start'
                      }`}>
                        <span className={`text-[10px] font-black whitespace-nowrap ${
                          isUser
                            ? 'text-brand-600 dark:text-brand-400'
                            : 'text-accent-600 dark:text-accent-400'
                        }`}>
                          {isUser ? 'شما' : 'پشتیبانی'}
                        </span>
                        <span className="text-[10px] text-ink-400 dark:text-cream-500 whitespace-nowrap font-num">
                          {toFaDateTime(msg.created_at)}
                        </span>
                      </div>
                    )}

                    {/* Message bubble */}
                    <div className={`relative px-3.5 sm:px-4 py-2.5 rounded-3xl text-xs sm:text-sm leading-relaxed shadow-soft ${
                      isUser
                        ? 'bg-brand-gradient text-white rounded-tr-md'
                        : 'bg-paper-50 dark:bg-ink-700 text-ink-800 dark:text-cream-100 border border-ink-200 dark:border-dark-600 rounded-tl-md'
                    }`}>
                      <p className="whitespace-pre-wrap break-words break-safe">{msg.message}</p>
                    </div>
                  </div>
                </div>
              );
            })
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Reply form */}
        {!isClosed ? (
          <form
            onSubmit={handleSendReply}
            className="border-t border-ink-200 dark:border-dark-700 p-4 sm:p-5 bg-paper-50 dark:bg-ink-800 flex-shrink-0 safe-bottom"
          >
            <div className="relative">
              <textarea
                value={replyMessage}
                onChange={(e) => setReplyMessage(e.target.value)}
                rows="3"
                className="w-full px-4 py-3 pl-14 min-h-[88px] border-2 border-ink-200 dark:border-dark-600 rounded-2xl text-sm bg-paper-50 dark:bg-ink-700 text-ink-900 dark:text-cream-100 placeholder-ink-400 dark:placeholder-cream-500 focus:ring-2 focus:ring-brand-500/30 focus:border-brand-500 outline-none resize-none transition leading-relaxed"
                placeholder="پاسخ خود را اینجا بنویسید..."
                disabled={sending}
              />

              {/* Send button (float) — ✅ آیکون با کلید اختصاصی icon_send */}
              <button
                type="submit"
                disabled={sending || !replyMessage.trim()}
                className={`absolute left-2.5 bottom-2.5 w-11 h-11 rounded-2xl flex items-center justify-center transition-all shadow-brand touch-target p-2.5 ${
                  sending || !replyMessage.trim()
                    ? 'bg-paper-200 dark:bg-ink-600 text-ink-400 dark:text-cream-500 cursor-not-allowed'
                    : 'bg-brand-gradient hover:opacity-95 active:opacity-90 text-white hover:scale-105'
                }`}
                title="ارسال پاسخ"
                aria-label="ارسال پاسخ"
              >
                {sending ? (
                  <span className="inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                ) : (
                  <SiteImage
                    imageKey="icon_send"
                    fallback="📤"
                    alt=""
                    className="w-full h-full object-contain"
                  />
                )}
              </button>
            </div>

            {/* Helper row */}
            <div className="flex items-center justify-between mt-2.5 px-1 gap-2 flex-wrap">
              <div className="text-[10px] font-black">
                {replyMessage.trim().length < 2 ? (
                  <span className="text-brand-600 dark:text-brand-400 flex items-center gap-1">
                    <span className="w-3 h-3" aria-hidden="true">
                      <SiteImage
                        imageKey="icon_warning"
                        fallback="⚠️"
                        alt=""
                        className="w-full h-full object-contain"
                      />
                    </span>
                    <span>حداقل ۲ کاراکتر</span>
                  </span>
                ) : (
                  <span className="text-accent-600 dark:text-accent-400 flex items-center gap-1">
                    <span className="w-3 h-3" aria-hidden="true">
                      <SiteImage
                        imageKey="icon_check"
                        fallback="✓"
                        alt=""
                        className="w-full h-full object-contain"
                      />
                    </span>
                    <span>آماده ارسال</span>
                  </span>
                )}
              </div>
              <div className="text-[10px] text-ink-400 dark:text-cream-500 font-num">
                {toFa(replyMessage.length)} کاراکتر
              </div>
            </div>
          </form>
        ) : (
          <div className="border-t border-ink-200 dark:border-dark-700 p-5 bg-paper-100/50 dark:bg-ink-900/40 text-center flex-shrink-0 safe-bottom">
            <div className="inline-flex items-center gap-2 text-ink-600 dark:text-cream-300 text-sm font-black">
              <span className="w-5 h-5" aria-hidden="true">
                <SiteImage
                  imageKey="icon_lock"
                  fallback="🔒"
                  alt=""
                  className="w-full h-full object-contain"
                />
              </span>
              <span className="font-display">این تیکت بسته شده است</span>
            </div>
            <div className="text-[10px] sm:text-[11px] text-ink-500 dark:text-cream-400 mt-2 leading-relaxed">
              برای پیگیری موضوع جدید، لطفاً تیکت جدیدی ارسال کنید
            </div>
            <Link
              to="/panel/tickets/new"
              className="mt-4 w-full sm:w-auto inline-flex items-center justify-center gap-2 min-h-[48px] bg-brand-gradient hover:opacity-95 active:opacity-90 text-white px-5 py-3 rounded-2xl text-xs sm:text-sm font-black transition shadow-brand hover:shadow-brand-lg touch-target"
            >
              <span className="w-4 h-4" aria-hidden="true">
                <SiteImage
                  imageKey="icon_plus"
                  fallback="➕"
                  alt=""
                  className="w-full h-full object-contain"
                />
              </span>
              <span>ارسال تیکت جدید</span>
            </Link>
          </div>
        )}
      </div>

      {/* ============================================================ */}
      {/*  Help link — ✅ فلش از SiteImage                             */}
      {/* ============================================================ */}
      <div className="text-center">
        <Link
          to="/panel/faq"
          className="inline-flex items-center gap-1.5 min-h-[44px] px-3 text-xs text-ink-500 dark:text-cream-400 hover:text-brand-600 dark:hover:text-brand-400 font-black transition touch-target group"
        >
          <span className="w-3.5 h-3.5" aria-hidden="true">
            <SiteImage
              imageKey="icon_faq"
              fallback="❓"
              alt=""
              className="w-full h-full object-contain"
            />
          </span>
          <span>سوالات متداول را ببینید</span>
          <span
            className="w-3.5 h-3.5 inline-flex items-center justify-center group-hover:-translate-x-1 transition-transform flex-shrink-0"
            aria-hidden="true"
          >
            <SiteImage
              imageKey="icon_arrow_left"
              fallback="←"
              alt=""
              className="w-full h-full object-contain"
            />
          </span>
        </Link>
      </div>

    </div>
  );
}