// ============================================================
//  🛒 Batch helpers
// ============================================================
function buildBatchSizes(orders) {
  const sizes = {};
  orders.forEach((o) => {
    if (o.batch_id) {
      sizes[o.batch_id] = (sizes[o.batch_id] || 0) + 1;
    }
  });
  return sizes;
}

function isBatchOrder(order, batchSizes) {
  return Boolean(order.batch_id) && (batchSizes[order.batch_id] || 0) > 1;
}

