import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import userAxios from '../userAxios';
import { useToast } from '../components/Toast';
import { Skeleton } from '../components/Skeleton';
import EmptyState from '../components/EmptyState';
import { SiteImage } from '../../utils/SiteImage';
import { STORAGE_KEYS } from '../../constants/storageKeys';

import { toFa, toFaDecimal, toFaDate } from '../../utils/numbers';

// ============================================================
//  ثابت‌ها
// ============================================================
const ALLOWED_IMAGE_EXTS = ['image/jpeg', 'image/png', 'image/webp'];
const MAX_IMAGE_SIZE = 2 * 1024 * 1024;

const MIN_OWNER = 2;
const MAX_OWNER = 100;
const MIN_DOG_NAME = 1;
const MAX_DOG_NAME = 50;
const MAX_BREED = 50;
const MAX_CITY = 50;
const MIN_QUOTE = 10;
const MAX_QUOTE = 500;
const MAX_PENDING = 3;

// ============================================================
//  وضعیت‌های نظر
// ============================================================
const STATUS_CONFIG = {
  pending: {
    text: 'در انتظار تأیید',
    icon: '⏳',
    iconKey: 'icon_pending',
    strip: 'bg-brand-500',
    badge: 'bg-brand-50 dark:bg-brand-500/15 text-brand-700 dark:text-brand-300 border-brand-200 dark:border-brand-500/30',
  },
  approved: {
    text: 'تأیید شده',
    icon: '✅',
    iconKey: 'icon_check',
    strip: 'bg-accent-500',
    badge: 'bg-accent-50 dark:bg-accent-500/15 text-accent-700 dark:text-accent-300 border-accent-200 dark:border-accent-500/30',
  },
  rejected: {
    text: 'رد شده',
    icon: '❌',
    iconKey: 'icon_error',
    strip: 'bg-rose-500',
    badge: 'bg-rose-50 dark:bg-rose-500/15 text-rose-700 dark:text-rose-300 border-rose-200 dark:border-rose-500/30',
  },
};

// ============================================================
//  Stars
// ============================================================
function Stars({ value = 5, onChange, size = 'lg', readOnly = false }) {
  const sizes = {
    sm: 'w-5 h-5',
    md: 'w-7 h-7',
    lg: 'w-9 h-9',
  };

  return (
    <div
      className={`flex items-center gap-1 ${sizes[size] || sizes.lg}`}
      role={readOnly ? undefined : 'radiogroup'}
      aria-label="امتیاز"
    >
      {[1, 2, 3, 4, 5].map((star) => {
        const filled = star <= value;
        return (
          <button
            key={star}
            type="button"
            onClick={() => !readOnly && onChange?.(star)}
            disabled={readOnly}
            className={`transition-all duration-200 touch-target leading-none p-1 ${
              sizes[size] || sizes.lg
            } ${
              readOnly ? 'cursor-default' : 'cursor-pointer hover:scale-110 active:scale-95'
            } ${filled ? 'text-brand-500' : 'text-ink-200 dark:text-dark-600'}`}
            aria-label={`${toFa(star)} ستاره`}
            aria-checked={value === star}
            role={readOnly ? undefined : 'radio'}
          >
            <SiteImage
              imageKey="icon_star"
              fallback="★"
              alt=""
              className={`w-full h-full object-contain ${
                filled ? '' : 'opacity-40 grayscale'
              }`}
            />
          </button>
        );
      })}
    </div>
  );
}

function StarsDisplay({ value = 5, size = 'sm' }) {
  return <Stars value={value} size={size} readOnly />;
}

// ============================================================
//  Field
// ============================================================
function Field({ label, hint, required, icon, iconKey, error, children }) {
  return (
    <div>
      <label className="flex items-center gap-1.5 text-xs font-black text-ink-800 dark:text-cream-200 mb-1.5">
        {(icon || iconKey) && (
          <span className="w-4 h-4" aria-hidden="true">
            {iconKey ? (
              <SiteImage
                imageKey={iconKey}
                fallback={icon}
                alt=""
                className="w-full h-full object-contain"
              />
            ) : (
              <span className="text-sm">{icon}</span>
            )}
          </span>
        )}
        <span>{label}</span>
        {required && <span className="text-brand-500">*</span>}
      </label>
      {children}
      {error ? (
        <div className="text-[10px] text-rose-600 dark:text-rose-400 mt-1 flex items-center gap-1 break-safe font-bold">
          <span className="w-3 h-3 flex-shrink-0" aria-hidden="true">
            <SiteImage
              imageKey="icon_warning"
              fallback="⚠️"
              alt=""
              className="w-full h-full object-contain"
            />
          </span>
          <span>{error}</span>
        </div>
      ) : hint ? (
        <div className="text-[10px] text-ink-500 dark:text-cream-400 mt-1 leading-relaxed">
          {hint}
        </div>
      ) : null}
    </div>
  );
}

// ============================================================
//  ImageUploader
// ============================================================
function ImageUploader({ file, preview, onFileSelect, onRemove, disabled }) {
  const [dragOver, setDragOver] = useState(false);
  const [error, setError] = useState('');
  const fileInputRef = useRef(null);

  const validateAndSelect = (f) => {
    if (!f) return;
    setError('');

    if (!ALLOWED_IMAGE_EXTS.includes(f.type)) {
      setError('فقط فرمت‌های JPG، PNG یا WEBP مجاز هستند');
      return;
    }
    if (f.size > MAX_IMAGE_SIZE) {
      setError('حجم فایل نباید بیشتر از ۲ مگابایت باشد');
      return;
    }
    onFileSelect(f);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setDragOver(false);
    if (disabled) return;
    const f = e.dataTransfer.files?.[0];
    validateAndSelect(f);
  };

  const handleInputChange = (e) => {
    const f = e.target.files?.[0];
    validateAndSelect(f);
  };

  return (
    <div className="space-y-2.5">
      {!preview ? (
        <div
          onClick={() => !disabled && fileInputRef.current?.click()}
          onDragOver={(e) => {
            e.preventDefault();
            if (!disabled) setDragOver(true);
          }}
          onDragLeave={() => setDragOver(false)}
          onDrop={handleDrop}
          className={`relative border-2 border-dashed rounded-2xl p-6 sm:p-8 text-center cursor-pointer transition touch-target ${
            disabled
              ? 'opacity-50 cursor-not-allowed border-ink-200 dark:border-dark-600'
              : dragOver
              ? 'border-brand-500 bg-brand-50 dark:bg-brand-500/15 scale-[1.02]'
              : 'border-ink-200 dark:border-dark-600 bg-paper-100 dark:bg-ink-900/40 hover:border-brand-400 hover:bg-brand-50 dark:hover:bg-brand-500/15 active:bg-brand-100 dark:active:bg-brand-500/25'
          }`}
        >
          <input
            ref={fileInputRef}
            type="file"
            accept="image/jpeg,image/png,image/webp"
            onChange={handleInputChange}
            className="hidden"
            disabled={disabled}
          />

          <div className="w-12 h-12 mx-auto mb-3 opacity-80" aria-hidden="true">
            <SiteImage
              imageKey="icon_camera"
              fallback="📸"
              alt=""
              className="w-full h-full object-contain"
            />
          </div>
          <div className="font-display font-black text-ink-800 dark:text-cream-100 text-sm mb-1">
            عکس سگت رو آپلود کن
          </div>
          <div className="text-xs text-ink-500 dark:text-cream-400 mb-3">
            یا فایل رو اینجا بکش و رها کن
          </div>
          <div className="inline-block bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-600 rounded-full px-3 py-1 text-[10px] text-ink-500 dark:text-cream-400 font-mono">
            JPG · PNG · WEBP — حداکثر ۲ MB
          </div>
        </div>
      ) : (
        <div className="space-y-2.5">
          <div className="relative rounded-2xl overflow-hidden border-2 border-ink-200 dark:border-dark-600 group">
            <img
              src={preview}
              alt="پیش‌نمایش عکس"
              className="w-full h-48 sm:h-56 object-cover"
            />
            <button
              type="button"
              onClick={onRemove}
              disabled={disabled}
              className="absolute top-2.5 left-2.5 w-10 h-10 flex items-center justify-center bg-rose-500 hover:bg-rose-600 active:bg-rose-700 text-white rounded-2xl transition text-sm font-black shadow-editorial touch-target disabled:opacity-50"
              title="حذف عکس"
              aria-label="حذف عکس"
            >
              ✕
            </button>
          </div>

          {file && (
            <div className="bg-paper-100 dark:bg-ink-900/50 border border-ink-200 dark:border-dark-700 rounded-xl px-3 py-2 flex items-center justify-between gap-2">
              <span className="text-[10px] text-ink-700 dark:text-cream-200 font-mono truncate" dir="ltr">
                {file.name}
              </span>
              <span className="text-[10px] text-ink-400 dark:text-cream-500 flex-shrink-0 font-num">
                {toFa(Math.round(file.size / 1024))} KB
              </span>
            </div>
          )}
        </div>
      )}

      {error && (
        <div className="bg-rose-50 dark:bg-rose-500/15 border border-rose-200 dark:border-rose-500/30 text-rose-700 dark:text-rose-300 p-2.5 rounded-xl text-[11px] flex items-start gap-2 break-safe font-bold">
          <span className="w-3.5 h-3.5 flex-shrink-0 mt-0.5" aria-hidden="true">
            <SiteImage
              imageKey="icon_warning"
              fallback="⚠️"
              alt=""
              className="w-full h-full object-contain"
            />
          </span>
          <span>{error}</span>
        </div>
      )}
    </div>
  );
}

