// ============================================================
//  🌐 resolveReceiptUrl — فقط برای URLهای مطلق (تصاویر)
// ============================================================
const resolveReceiptUrl = (receiptUrl) => {
  if (!receiptUrl) return '';
  if (/^https?:\/\//i.test(receiptUrl)) return receiptUrl;
  return `${API_BASE}${receiptUrl.startsWith('/') ? '' : '/'}${receiptUrl}`;
};

// ============================================================
//  نگاشت وضعیت‌ها
// ============================================================
