import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import userAxios from '../userAxios';
import { SiteImage } from '../../utils/SiteImage';

const MAX_ITEMS = 100;

const NOTIF_CONFIG = {
  order_status: { icon: '📦', iconKey: 'icon_orders', color: 'brand', label: 'سفارش' },
  payment_verified: { icon: '✅', iconKey: 'icon_check', color: 'accent', label: 'پرداخت' },
  payment_rejected: { icon: '❌', iconKey: 'icon_error', color: 'rose', label: 'پرداخت' },
  payment_unverified: { icon: '⚠️', iconKey: 'icon_warning', color: 'brand', label: 'پرداخت' },
  ticket_reply: { icon: '💬', iconKey: 'icon_chat', color: 'ink', label: 'پشتیبانی' },
  general: { icon: '🔔', iconKey: 'icon_bell', color: 'ink', label: 'عمومی' },
};

const COLOR_CLASSES = {
  brand: {
    iconBg: 'bg-brand-100 dark:bg-brand-500/20 text-brand-700 dark:text-brand-300',
    border: 'border-brand-200 dark:border-brand-500/30',
    dot: 'bg-brand-500',
    strip: 'bg-brand-500',
  },
  accent: {
    iconBg: 'bg-accent-100 dark:bg-accent-500/20 text-accent-700 dark:text-accent-300',
    border: 'border-accent-200 dark:border-accent-500/30',
    dot: 'bg-accent-500',
    strip: 'bg-accent-500',
  },
  rose: {
    iconBg: 'bg-rose-100 dark:bg-rose-500/20 text-rose-700 dark:text-rose-300',
    border: 'border-rose-200 dark:border-rose-500/30',
    dot: 'bg-rose-500',
    strip: 'bg-rose-500',
  },
  ink: {
    iconBg: 'bg-ink-100 dark:bg-ink-700 text-ink-700 dark:text-cream-200',
    border: 'border-ink-200 dark:border-dark-600',
    dot: 'bg-ink-500',
    strip: 'bg-ink-500',
  },
};

function safeDate(iso) {
  if (!iso) return null;
  let s = String(iso);
  if (!s.includes('Z') && !/[+-]\d{2}:?\d{2}$/.test(s)) {
    s = s + 'Z';
  }
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}

function toFa(num) {
  if (num === null || num === undefined) return '';
  return String(num).replace(/\d/g, d => '۰۱۲۳۴۵۶۷۸۹'[d]);
}

function toFaTimeAgo(iso) {
  const d = safeDate(iso);
  if (!d) return '—';
  const diff = Date.now() - d.getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return 'همین الان';
  if (mins < 60) return `${toFa(mins)} دقیقه پیش`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${toFa(hours)} ساعت پیش`;
  const days = Math.floor(hours / 24);
  if (days < 7) return `${toFa(days)} روز پیش`;
  return new Intl.DateTimeFormat('fa-IR', { month: 'short', day: 'numeric' }).format(d);
}

// ============================================================
//  کامپوننت اصلی — ✅ فقط یک export default
// ============================================================
export default function Notifications() {
  const navigate = useNavigate();
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('all');
  const [markingAll, setMarkingAll] = useState(false);
  const [clearing, setClearing] = useState(false);
  const [toast, setToast] = useState(null);

  const showToast = (type, message) => {
    setToast({ type, message });
    setTimeout(() => setToast(null), 3000);
  };

  const fetchNotifications = useCallback(async () => {
    setLoading(true);
    try {
      const res = await userAxios.get('/api/notifications', {
        params: { limit: MAX_ITEMS },
      });
      setNotifications(res.data?.notifications || []);
    } catch (err) {
      showToast('error', err.response?.data?.detail || 'خطا در دریافت اعلان‌ها');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchNotifications();
  }, [fetchNotifications]);

  const filtered = useMemo(() => {
    if (activeTab === 'unread') {
      return notifications.filter((n) => !n.is_read);
    }
    return notifications;
  }, [notifications, activeTab]);

  const unreadCount = useMemo(
    () => notifications.filter((n) => !n.is_read).length,
    [notifications]
  );

  const readCount = useMemo(
    () => notifications.filter((n) => n.is_read).length,
    [notifications]
  );

  const handleClick = async (notif) => {
    if (!notif.is_read) {
      try {
        await userAxios.put(`/api/notifications/${notif.id}/read`);
        setNotifications((prev) =>
          prev.map((n) => (n.id === notif.id ? { ...n, is_read: true } : n))
        );
      } catch {
        /* silent */
      }
    }
    if (notif.link) {
      navigate(notif.link);
    }
  };

  const handleMarkAllRead = async () => {
    if (unreadCount === 0) return;
    setMarkingAll(true);
    try {
      await userAxios.put('/api/notifications/read-all');
      setNotifications((prev) => prev.map((n) => ({ ...n, is_read: true })));
      showToast('success', 'همه اعلان‌ها خوانده‌شده شدند');
    } catch {
      showToast('error', 'خطا در به‌روزرسانی');
    } finally {
      setMarkingAll(false);
    }
  };

  const handleClearRead = async () => {
    if (readCount === 0) return;
    if (!window.confirm(`آیا از حذف ${toFa(readCount)} اعلان خوانده‌شده مطمئن هستی؟`)) {
      return;
    }
    setClearing(true);
    try {
      await userAxios.delete('/api/notifications');
      setNotifications((prev) => prev.filter((n) => !n.is_read));
      showToast('success', 'اعلان‌های خوانده‌شده حذف شدند');
    } catch {
      showToast('error', 'خطا در حذف');
    } finally {
      setClearing(false);
    }
  };

  const handleDeleteOne = async (e, notifId) => {
    e.stopPropagation();
    try {
      await userAxios.delete(`/api/notifications/${notifId}`);
      setNotifications((prev) => prev.filter((n) => n.id !== notifId));
    } catch {
      showToast('error', 'خطا در حذف اعلان');
    }
  };

  return (
    <div className="max-w-3xl mx-auto space-y-4" dir="rtl">

      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-end sm:justify-between gap-3">
        <div className="min-w-0">
          <div className="flex items-center gap-3 mb-2">
            <div className="w-10 h-px bg-brand-500" aria-hidden="true" />
            <span className="text-[10px] sm:text-[11px] font-black tracking-[0.2em] uppercase text-brand-600 dark:text-brand-400">
              اعلان‌ها
            </span>
          </div>
          <h1 className="font-display font-black text-2xl sm:text-3xl text-ink-900 dark:text-cream-100 leading-tight tracking-tightest mb-1.5">
            اعلان‌های من
          </h1>
          <p className="text-xs sm:text-sm text-ink-500 dark:text-cream-400">
            {unreadCount > 0 ? (
              <><span className="font-black text-brand-600 dark:text-brand-400">{toFa(unreadCount)}</span> مورد خوانده‌نشده</>
            ) : (
              'همه اعلان‌ها خوانده شده'
            )}
          </p>
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          {unreadCount > 0 && (
            <button
              type="button"
              onClick={handleMarkAllRead}
              disabled={markingAll}
              className="min-h-[40px] px-3.5 py-2 bg-brand-50 dark:bg-brand-500/15 hover:bg-brand-100 dark:hover:bg-brand-500/25 active:bg-brand-200 text-brand-700 dark:text-brand-300 border border-brand-200 dark:border-brand-500/30 rounded-xl text-xs font-black transition flex items-center gap-1.5 touch-target disabled:opacity-50"
            >
              <span className="w-3.5 h-3.5" aria-hidden="true">
                <SiteImage
                  imageKey="icon_check"
                  fallback="✓"
                  alt=""
                  className="w-full h-full object-contain"
                />
              </span>
              <span>{markingAll ? 'در حال...' : 'همه را خوانده‌شده'}</span>
            </button>
          )}

          {readCount > 0 && (
            <button
              type="button"
              onClick={handleClearRead}
              disabled={clearing}
              className="min-h-[40px] px-3.5 py-2 bg-rose-50 dark:bg-rose-500/15 hover:bg-rose-100 dark:hover:bg-rose-500/25 active:bg-rose-200 text-rose-700 dark:text-rose-300 border border-rose-200 dark:border-rose-500/30 rounded-xl text-xs font-black transition flex items-center gap-1.5 touch-target disabled:opacity-50"
            >
              <span className="w-3.5 h-3.5" aria-hidden="true">
                <SiteImage
                  imageKey="icon_trash"
                  fallback="🗑️"
                  alt=""
                  className="w-full h-full object-contain"
                />
              </span>
              <span>{clearing ? 'در حال...' : 'پاک کردن خوانده‌شده‌ها'}</span>
            </button>
          )}
        </div>
      </div>

      {/* Tabs */}
      <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-2xl p-1 shadow-soft flex gap-1">
        <button
          type="button"
          onClick={() => setActiveTab('all')}
          className={`flex-1 min-h-[40px] px-3 py-2 rounded-xl text-xs font-black transition touch-target flex items-center justify-center gap-1.5 ${
            activeTab === 'all'
              ? 'bg-ink-900 dark:bg-cream-100 text-cream-50 dark:text-ink-900 shadow-sm'
              : 'text-ink-600 dark:text-cream-300 hover:bg-paper-100 dark:hover:bg-ink-700/50'
          }`}
        >
          <span>همه</span>
          <span className={`px-1.5 py-0.5 rounded-full text-[10px] font-black font-num ${
            activeTab === 'all' ? 'bg-white/20' : 'bg-paper-100 dark:bg-ink-700'
          }`}>
            {toFa(notifications.length)}
          </span>
        </button>

        <button
          type="button"
          onClick={() => setActiveTab('unread')}
          className={`flex-1 min-h-[40px] px-3 py-2 rounded-xl text-xs font-black transition touch-target flex items-center justify-center gap-1.5 ${
            activeTab === 'unread'
              ? 'bg-ink-900 dark:bg-cream-100 text-cream-50 dark:text-ink-900 shadow-sm'
              : 'text-ink-600 dark:text-cream-300 hover:bg-paper-100 dark:hover:bg-ink-700/50'
          }`}
        >
          <span>خوانده‌نشده</span>
          {unreadCount > 0 && (
            <span className={`px-1.5 py-0.5 rounded-full text-[10px] font-black font-num ${
              activeTab === 'unread'
                ? 'bg-rose-500 text-white'
                : 'bg-rose-100 dark:bg-rose-500/20 text-rose-700 dark:text-rose-300'
            }`}>
              {toFa(unreadCount)}
            </span>
          )}
        </button>
      </div>

      {/* List */}
      {loading ? (
        <div className="space-y-2">
          {[1, 2, 3].map((i) => (
            <div key={i} className="h-20 bg-paper-200 dark:bg-ink-700 rounded-2xl animate-pulse" />
          ))}
        </div>
      ) : filtered.length === 0 ? (
        <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl p-6 sm:p-10 lg:p-14 text-center shadow-soft">
          <div className="w-14 h-14 mb-4 mx-auto opacity-50" aria-hidden="true">
            <SiteImage
              imageKey={activeTab === 'unread' ? 'icon_check' : 'icon_bell'}
              fallback={activeTab === 'unread' ? '✅' : '🔔'}
              alt=""
              className="w-full h-full object-contain"
            />
          </div>
          <div className="font-display font-black text-ink-800 dark:text-cream-100 text-base mb-2">
            {activeTab === 'unread' ? 'همه اعلان‌ها خوانده شده' : 'هیچ اعلانی نداری'}
          </div>
          <div className="text-xs text-ink-500 dark:text-cream-400 leading-relaxed max-w-sm mx-auto mb-5">
            {activeTab === 'unread'
              ? 'اعلان خوانده‌نشده‌ای وجود ندارد'
              : 'وقتی رویدادی مثل تغییر وضعیت سفارش یا پاسخ پشتیبانی بیفته، اینجا نمایش داده می‌شه'}
          </div>
          <Link
            to="/panel"
            className="inline-flex items-center gap-2 min-h-[44px] px-5 py-2.5 bg-brand-gradient hover:opacity-95 active:opacity-90 text-white rounded-2xl text-xs font-black shadow-brand transition touch-target"
          >
            <span className="w-4 h-4" aria-hidden="true">
              <SiteImage
                imageKey="icon_house"
                fallback="🏠"
                alt=""
                className="w-full h-full object-contain"
              />
            </span>
            <span>بازگشت به داشبورد</span>
          </Link>
        </div>
      ) : (
        <div className="space-y-2">
          {filtered.map((n) => {
            const cfg = NOTIF_CONFIG[n.type] || NOTIF_CONFIG.general;
            const cls = COLOR_CLASSES[cfg.color] || COLOR_CLASSES.ink;

            return (
              <div
                key={n.id}
                onClick={() => handleClick(n)}
                role="button"
                tabIndex={0}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    handleClick(n);
                  }
                }}
                className={`group relative bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-2xl shadow-soft hover:shadow-lifted hover:-translate-y-0.5 transition-all cursor-pointer overflow-hidden touch-target ${
                  !n.is_read ? 'ring-2 ring-brand-200 dark:ring-brand-500/30' : ''
                }`}
              >
                <div className={`absolute right-0 top-0 bottom-0 w-1 ${cls.strip} ${n.is_read ? 'opacity-40' : ''}`} aria-hidden="true" />

                <div className="p-3.5 sm:p-4 pr-5 flex items-start gap-3">
                  <div
                    className={`w-10 h-10 rounded-xl flex items-center justify-center p-2 flex-shrink-0 border ${cls.border} ${cls.iconBg}`}
                    aria-hidden="true"
                  >
                    <SiteImage
                      imageKey={cfg.iconKey}
                      fallback={cfg.icon}
                      alt=""
                      className="w-full h-full object-contain"
                    />
                  </div>

                  <div className="flex-1 min-w-0">
                    <div className="flex items-start gap-2 mb-1">
                      <span className={`text-sm font-black leading-tight flex-1 min-w-0 break-safe ${
                        n.is_read
                          ? 'text-ink-700 dark:text-cream-300'
                          : 'text-ink-900 dark:text-cream-100'
                      }`}>
                        {n.title}
                      </span>
                      {!n.is_read && (
                        <span className={`w-2 h-2 rounded-full flex-shrink-0 mt-1.5 ${cls.dot} animate-pulse`} aria-label="خوانده‌نشده" />
                      )}
                    </div>

                    {n.message && (
                      <div className={`text-xs leading-relaxed line-clamp-3 mb-1.5 ${
                        n.is_read
                          ? 'text-ink-500 dark:text-cream-400'
                          : 'text-ink-700 dark:text-cream-200'
                      }`}>
                        {n.message}
                      </div>
                    )}

                    <div className="flex items-center gap-2 text-[10px] text-ink-400 dark:text-cream-500">
                      <span className="inline-flex items-center gap-1">
                        <span className={`w-1.5 h-1.5 rounded-full ${cls.dot} opacity-60`} aria-hidden="true" />
                        <span className="font-black">{cfg.label}</span>
                      </span>
                      <span aria-hidden="true">·</span>
                      <span>{toFaTimeAgo(n.created_at)}</span>
                    </div>
                  </div>

                  {n.is_read && (
                    <button
                      type="button"
                      onClick={(e) => handleDeleteOne(e, n.id)}
                      className="w-8 h-8 flex items-center justify-center text-ink-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-500/15 rounded-lg transition opacity-0 group-hover:opacity-100 focus:opacity-100 flex-shrink-0 touch-target"
                      title="حذف"
                      aria-label="حذف اعلان"
                    >
                      ✕
                    </button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Toast */}
      {toast && (
        <div
          className={`fixed bottom-24 sm:bottom-28 left-1/2 -translate-x-1/2 z-[60] px-4 sm:px-5 py-3 rounded-2xl shadow-editorial flex items-center gap-3 text-sm font-black transition-all backdrop-blur-sm border animate-slide-up w-[calc(100%-2rem)] sm:w-auto sm:max-w-md safe-bottom ${
            toast.type === 'success'
              ? 'bg-accent-600 border-accent-700 text-white'
              : toast.type === 'error'
              ? 'bg-rose-600 border-rose-700 text-white'
              : 'bg-brand-600 border-brand-700 text-white'
          }`}
        >
          <span className="w-5 h-5 flex-shrink-0" aria-hidden="true">
            <SiteImage
              imageKey={
                toast.type === 'success' ? 'icon_check' :
                toast.type === 'error' ? 'icon_warning' :
                'icon_info'
              }
              fallback={
                toast.type === 'success' ? '✅' :
                toast.type === 'error' ? '⚠️' :
                'ℹ️'
              }
              alt=""
              className="w-full h-full object-contain brightness-0 invert"
            />
          </span>
          <span className="break-safe flex-1">{toast.message}</span>
        </div>
      )}
    </div>
  );
}
