// frontend/src/user/components/HelpTooltip.jsx
import React, {
  useState,
  useEffect,
  useRef,
  useCallback,
  useId,
} from 'react';
import { createPortal } from 'react-dom';
// ✅ NEW: SiteImage برای آیکون‌های قابل تنظیم از پنل ادمین
import { SiteImage } from '../../utils/SiteImage';

// ============================================================
//  ⚙️ Constants
// ============================================================
const TOOLTIP_WIDTH = 304;         // px — عرض دسکتاپ
const TOOLTIP_OFFSET = 10;          // فاصله از دکمه
const EDGE_PADDING = 12;            // فاصله از لبه viewport
const MOBILE_BREAKPOINT = 640;      // px — زیر این، bottom-sheet
const CLOSE_DELAY_MS = 200;         // تاخیر بستن برای ورود به tooltip
const DEFAULT_TOOLTIP_HEIGHT = 200; // تخمین اولیه

// ============================================================
//  🔤 Helper: تمیز کردن id (useId ممکنه `:` داشته باشه)
// ============================================================
const sanitizeId = (raw) =>
  String(raw || '').replace(/[^a-zA-Z0-9_-]/g, '');

// ============================================================
//  📐 Button sizes
// ============================================================
const BUTTON_SIZES = {
  sm: {
    wrapper: 'w-4 h-4 sm:w-5 sm:h-5',
    text: 'text-[9px] sm:text-[10px]',
  },
  md: {
    wrapper: 'w-5 h-5',
    text: 'text-[10px]',
  },
  lg: {
    wrapper: 'w-6 h-6',
    text: 'text-xs',
  },
};

// ============================================================
//  🎨 Button classes — بر اساس حالت
// ============================================================
const getButtonClasses = ({ open, isDark, size }) => {
  const sz = BUTTON_SIZES[size] || BUTTON_SIZES.md;

  const colorClasses = open
    ? isDark
      ? 'bg-brand-400 text-ink-900 shadow-brand scale-110'
      : 'bg-brand-500 text-white shadow-brand scale-110'
    : isDark
    ? 'bg-white/15 text-white/90 hover:bg-white/25 backdrop-blur-md border border-white/20'
    : 'bg-brand-100 dark:bg-brand-500/20 text-brand-600 dark:text-brand-300 hover:bg-brand-200 dark:hover:bg-brand-500/30';

  return `${sz.wrapper} ${sz.text} rounded-full flex items-center justify-center font-black transition-all flex-shrink-0 touch-target ${colorClasses}`;
};

// ============================================================
//  🎨 Tooltip card classes — هماهنگ با پالت سایت
// ============================================================
const getTooltipCardClasses = (isDark) => {
  return isDark
    ? 'bg-ink-950 text-cream-100 border border-dark-700 shadow-editorial'
    : 'bg-paper-50 text-ink-900 border border-ink-200 shadow-editorial';
};

const getTooltipArrowClasses = (isDark, placement) => {
  const base = isDark ? 'bg-ink-950 border-dark-700' : 'bg-paper-50 border-ink-200';
  const edge =
    placement === 'top'
      ? 'border-r border-b'
      : 'border-l border-t';
  return `${base} ${edge}`;
};

// ============================================================
//  📐 Positioning — Flip + clamp
// ============================================================
function computePosition(btnRect, align, tooltipHeightEstimate) {
  const viewportWidth = window.innerWidth;
  const viewportHeight = window.innerHeight;

  // ─── Horizontal ───
  let left;
  if (align === 'left') {
    left = btnRect.left;
  } else if (align === 'center') {
    left = btnRect.left + btnRect.width / 2 - TOOLTIP_WIDTH / 2;
  } else {
    // 'right' (default)
    left = btnRect.right - TOOLTIP_WIDTH;
  }

  if (left + TOOLTIP_WIDTH > viewportWidth - EDGE_PADDING) {
    left = viewportWidth - TOOLTIP_WIDTH - EDGE_PADDING;
  }
  if (left < EDGE_PADDING) {
    left = EDGE_PADDING;
  }

  // ─── Vertical: Flip ───
  const spaceBelow = viewportHeight - btnRect.bottom;
  const spaceAbove = btnRect.top;

  const shouldFlip =
    spaceBelow < tooltipHeightEstimate + TOOLTIP_OFFSET &&
    spaceAbove > spaceBelow;

  const top = shouldFlip
    ? btnRect.top - TOOLTIP_OFFSET - tooltipHeightEstimate
    : btnRect.bottom + TOOLTIP_OFFSET;

  const clampedTop = Math.max(
    EDGE_PADDING,
    Math.min(top, viewportHeight - tooltipHeightEstimate - EDGE_PADDING)
  );

  // ─── Arrow position ───
  const btnCenterX = btnRect.left + btnRect.width / 2;
  const arrowLeft = Math.max(
    16,
    Math.min(btnCenterX - left, TOOLTIP_WIDTH - 16)
  );

  return {
    top: clampedTop,
    left,
    arrowLeft,
    placement: shouldFlip ? 'top' : 'bottom',
  };
}

// ============================================================
//  🎯 کامپوننت اصلی
// ============================================================
export default function HelpTooltip({
  title,
  desc,
  extra,
  align = 'right',
  isDark = false,
  glass,                    // alias برای isDark
  buttonSize = 'md',
}) {
  const dark = isDark || glass === true;

  const [open, setOpen] = useState(false);
  const [coords, setCoords] = useState({
    top: 0,
    left: 0,
    arrowLeft: 0,
    placement: 'bottom',
  });
  const [isMobile, setIsMobile] = useState(false);

  const btnRef = useRef(null);
  const tooltipRef = useRef(null);
  const closeTimeoutRef = useRef(null);
  const isMountedRef = useRef(true);

  const rawId = useId();
  const tooltipId = `help-tooltip-${sanitizeId(rawId)}`;

  // ============================================================
  //  Mount tracking
  // ============================================================
  useEffect(() => {
    isMountedRef.current = true;
    return () => {
      isMountedRef.current = false;
      if (closeTimeoutRef.current) clearTimeout(closeTimeoutRef.current);
    };
  }, []);

  // ============================================================
  //  Detect mobile (resize)
  // ============================================================
  useEffect(() => {
    if (typeof window === 'undefined') return;

    const check = () => setIsMobile(window.innerWidth < MOBILE_BREAKPOINT);
    check();
    window.addEventListener('resize', check);
    return () => window.removeEventListener('resize', check);
  }, []);

  // ============================================================
  //  Update position — با cardRef واقعی
  // ============================================================
  const updatePosition = useCallback(() => {
    if (!btnRef.current || isMobile) return;

    const btnRect = btnRef.current.getBoundingClientRect();
    const tooltipHeight =
      tooltipRef.current?.offsetHeight || DEFAULT_TOOLTIP_HEIGHT;

    const next = computePosition(btnRect, align, tooltipHeight);
    setCoords(next);
  }, [align, isMobile]);

  // ============================================================
  //  Position update on open / scroll / resize
  // ============================================================
  useEffect(() => {
    if (!open || isMobile) return;

    const raf = requestAnimationFrame(() => updatePosition());

    const handleScroll = () => updatePosition();
    const handleResize = () => updatePosition();

    window.addEventListener('scroll', handleScroll, { capture: true, passive: true });
    window.addEventListener('resize', handleResize);

    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener('scroll', handleScroll, true);
      window.removeEventListener('resize', handleResize);
    };
  }, [open, isMobile, updatePosition]);

  // ============================================================
  //  Click outside → close
  // ============================================================
  useEffect(() => {
    if (!open) return;

    const handler = (e) => {
      if (
        btnRef.current && !btnRef.current.contains(e.target) &&
        tooltipRef.current && !tooltipRef.current.contains(e.target)
      ) {
        setOpen(false);
      }
    };

    const t = setTimeout(() => {
      document.addEventListener('mousedown', handler);
      document.addEventListener('touchstart', handler);
    }, 0);

    return () => {
      clearTimeout(t);
      document.removeEventListener('mousedown', handler);
      document.removeEventListener('touchstart', handler);
    };
  }, [open]);

  // ============================================================
  //  Escape key → close + return focus
  // ============================================================
  useEffect(() => {
    if (!open) return;

    const handler = (e) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        setOpen(false);
        btnRef.current?.focus();
      }
    };

    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [open]);

  // ============================================================
  //  Prevent body scroll — mobile sheet
  // ============================================================
  useEffect(() => {
    if (!open || !isMobile) return;

    const originalOverflow = document.body.style.overflow;
    const originalPaddingRight = document.body.style.paddingRight;
    const scrollbarWidth = window.innerWidth - document.documentElement.clientWidth;

    document.body.style.overflow = 'hidden';
    if (scrollbarWidth > 0) {
      document.body.style.paddingRight = `${scrollbarWidth}px`;
    }

    return () => {
      document.body.style.overflow = originalOverflow || '';
      document.body.style.paddingRight = originalPaddingRight || '';
    };
  }, [open, isMobile]);

  // ============================================================
  //  Focus trap در mobile sheet
  // ============================================================
  useEffect(() => {
    if (!open || !isMobile) return;

    const sheet = tooltipRef.current;
    if (!sheet) return;

    const getFocusables = () =>
      Array.from(
        sheet.querySelectorAll(
          'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
        )
      ).filter((el) => !el.hasAttribute('disabled'));

    // Focus first element
    const focusables = getFocusables();
    if (focusables.length > 0) {
      focusables[0].focus();
    }

    const handleTab = (e) => {
      if (e.key !== 'Tab') return;
      const items = getFocusables();
      if (items.length === 0) return;

      const first = items[0];
      const last = items[items.length - 1];
      const active = document.activeElement;

      if (e.shiftKey && active === first) {
        e.preventDefault();
        last.focus();
      } else if (!e.shiftKey && active === last) {
        e.preventDefault();
        first.focus();
      }
    };

    document.addEventListener('keydown', handleTab);
    return () => document.removeEventListener('keydown', handleTab);
  }, [open, isMobile]);

  // ============================================================
  //  🎯 Handlers — Desktop hover with delay
  // ============================================================
  const cancelClose = useCallback(() => {
    if (closeTimeoutRef.current) {
      clearTimeout(closeTimeoutRef.current);
      closeTimeoutRef.current = null;
    }
  }, []);

  const scheduleClose = useCallback(() => {
    if (isMobile) return;
    cancelClose();
    closeTimeoutRef.current = setTimeout(() => {
      if (!isMountedRef.current) return;
      const isOverButton = btnRef.current?.matches(':hover');
      const isOverTooltip = tooltipRef.current?.matches(':hover');
      if (!isOverButton && !isOverTooltip) {
        setOpen(false);
      }
    }, CLOSE_DELAY_MS);
  }, [isMobile, cancelClose]);

  const handleToggle = (e) => {
    e.preventDefault();
    e.stopPropagation();
    cancelClose();
    setOpen((v) => !v);
  };

  const handleMouseEnter = () => {
    if (isMobile) return;
    cancelClose();
    setOpen(true);
  };

  const handleMouseLeave = () => {
    if (isMobile) return;
    scheduleClose();
  };

  const handleClose = () => {
    cancelClose();
    setOpen(false);
    // ✅ FIX: بازگشت focus به button
    setTimeout(() => {
      btnRef.current?.focus();
    }, 0);
  };

  // ============================================================
  //  Early return
  // ============================================================
  if (!title) return null;

  // ============================================================
  //  Desktop Tooltip
  // ============================================================
  const renderDesktopTooltip = () => (
    <div
      ref={tooltipRef}
      id={tooltipId}
      role="tooltip"
      className={`fixed w-[304px] max-w-[calc(100vw-1.5rem)] rounded-2xl p-3.5 z-[90] animate-tooltip-in ${getTooltipCardClasses(dark)}`}
      style={{
        top: `${coords.top}px`,
        left: `${coords.left}px`,
      }}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      dir="rtl"
    >
      {/* Arrow */}
      <span
        className={`absolute w-2 h-2 rotate-45 ${getTooltipArrowClasses(dark, coords.placement)}`}
        style={{ left: `${coords.arrowLeft}px` }}
        aria-hidden="true"
      />

      {/* Header — ✅ آیکون از SiteImage */}
      <div className="flex items-start gap-2 mb-2">
        <span
          className="w-4 h-4 flex-shrink-0 inline-block mt-0.5"
          aria-hidden="true"
        >
          <SiteImage
            imageKey="help_tooltip_lightbulb_icon"
            fallback="💡"
            alt=""
            className="w-full h-full object-contain"
            showPlaceholder={true}
            placeholderContent={<span>💡</span>}
          />
        </span>
        <div className="font-display font-black text-xs leading-tight flex-1 min-w-0">
          {title}
        </div>
      </div>

      {/* Body */}
      <div className="text-[11px] leading-relaxed opacity-90 break-safe">
        {desc}
      </div>

      {/* Extra — ✅ آیکون از SiteImage */}
      {extra && (
        <div
          className={`mt-3 pt-3 border-t text-[10px] leading-relaxed opacity-85 flex items-start gap-1.5 break-safe ${
            dark ? 'border-white/10' : 'border-ink-200'
          }`}
        >
          <span className="w-3.5 h-3.5 flex-shrink-0 inline-block mt-0.5">
            <SiteImage
              imageKey="help_tooltip_sparkles_icon"
              fallback="✨"
              alt=""
              className="w-full h-full object-contain"
              showPlaceholder={true}
              placeholderContent={<span>✨</span>}
            />
          </span>
          <span>{extra}</span>
        </div>
      )}
    </div>
  );

  // ============================================================
  //  Mobile Bottom Sheet
  // ============================================================
  const renderMobileSheet = () => (
    <div
      className="fixed inset-0 z-[95] flex items-end justify-center animate-fadeIn"
      onClick={handleClose}
      role="dialog"
      aria-modal="true"
      aria-labelledby={`${tooltipId}-title`}
    >
      {/* Backdrop */}
      <div
        className="absolute inset-0 bg-ink-950/70 backdrop-blur-sm"
        aria-hidden="true"
      />

      {/* Sheet */}
      <div
        ref={tooltipRef}
        className={`relative w-full max-w-md rounded-t-3xl shadow-editorial animate-slide-up ${getTooltipCardClasses(dark)}`}
        onClick={(e) => e.stopPropagation()}
        dir="rtl"
      >
        {/* Drag handle */}
        <div
          className={`w-10 h-1 rounded-full mx-auto mt-3 mb-4 ${
            dark ? 'bg-white/25' : 'bg-ink-300'
          }`}
          aria-hidden="true"
        />

        {/* Header — ✅ آیکون از SiteImage */}
        <div className="flex items-start gap-3 mb-3 px-5">
          <div
            className="w-9 h-9 rounded-2xl bg-brand-gradient flex items-center justify-center p-2 flex-shrink-0 shadow-brand"
            aria-hidden="true"
          >
            <SiteImage
              imageKey="help_tooltip_lightbulb_icon"
              fallback="💡"
              alt=""
              className="w-full h-full object-contain"
              showPlaceholder={true}
              placeholderContent={<span>💡</span>}
            />
          </div>
          <div className="flex-1 min-w-0 pt-0.5">
            <div
              id={`${tooltipId}-title`}
              className="font-display font-black text-sm leading-tight break-safe"
            >
              {title}
            </div>
          </div>
          <button
            type="button"
            onClick={handleClose}
            className={`w-8 h-8 flex items-center justify-center rounded-xl transition flex-shrink-0 touch-target p-1.5 ${
              dark
                ? 'text-cream-300 hover:text-white hover:bg-white/10 active:bg-white/15'
                : 'text-ink-400 hover:text-ink-900 hover:bg-ink-100 active:bg-ink-200'
            }`}
            aria-label="بستن راهنما"
          >
            {/* ✅ آیکون از SiteImage */}
            <SiteImage
              imageKey="help_tooltip_close_icon"
              fallback="✕"
              alt=""
              className="w-full h-full object-contain"
              showPlaceholder={true}
              placeholderContent={<span>✕</span>}
            />
          </button>
        </div>

        {/* Body */}
        <div className="text-xs leading-relaxed opacity-90 break-safe mb-3 px-5">
          {desc}
        </div>

        {/* Extra — ✅ آیکون از SiteImage */}
        {extra && (
          <div
            className={`pt-3 border-t text-[11px] leading-relaxed opacity-85 flex items-start gap-2 break-safe px-5 pb-7 ${
              dark
                ? 'border-white/10 bg-white/5'
                : 'border-ink-200 bg-paper-100'
            }`}
            style={{
              paddingBottom: 'calc(1.75rem + env(safe-area-inset-bottom, 0px))',
            }}
          >
            <span className="w-3.5 h-3.5 flex-shrink-0 inline-block mt-1">
              <SiteImage
                imageKey="help_tooltip_sparkles_icon"
                fallback="✨"
                alt=""
                className="w-full h-full object-contain"
                showPlaceholder={true}
                placeholderContent={<span>✨</span>}
              />
            </span>
            <span>{extra}</span>
          </div>
        )}
      </div>
    </div>
  );

  // ============================================================
  //  Main Render
  // ============================================================
  return (
    <>
      <button
        ref={btnRef}
        type="button"
        onClick={handleToggle}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        className={getButtonClasses({ open, isDark: dark, size: buttonSize })}
        aria-label={`راهنمای ${title}`}
        aria-expanded={open}
        aria-haspopup={isMobile ? 'dialog' : undefined}
        aria-describedby={open ? tooltipId : undefined}
        title="راهنما"
      >
        {/* ✅ آیکون سوال از SiteImage */}
        <SiteImage
          imageKey="help_tooltip_question_icon"
          fallback="؟"
          alt=""
          className="w-full h-full object-contain p-0.5"
          showPlaceholder={true}
          placeholderContent={<span>؟</span>}
        />
      </button>

      {open &&
        createPortal(
          isMobile ? renderMobileSheet() : renderDesktopTooltip(),
          document.body
        )}
    </>
  );
}