// frontend/src/user/pages/Profile.jsx
// ============================================================
//  🌈 Warm & Friendly Profile (Headspace/BarkBox style)
//
//  ✅ حفظ تمام functionality از نسخه قبلی
//  ✅ اضافه‌شدن حس گرم و پت‌فرندلی:
//     - Header گرم با گرادیان برند + 🐾 متحرک
//     - Hero card با حس گرافیکی گرم‌تر
//     - Avatar uploader با ring برند + glow
//     - بخش‌بندی با آیکون‌های گرم + backgrounds دوستانه
//     - استفاده از utility classes: friendly-card, hover-lift, friendly-shadow, glow-soft
//     - انیمیشن‌های ملایم: animate-float-soft, animate-pulse-soft
//     - پنل «منطقهٔ خطر» با استایل واضح اما نه ترسناک
//  ✅ SiteImage: تمام آیکون‌های تزئینی از پنل ادمین قابل تغییرند
//  ✅ FIX (API): حذف localhost hardcoded → مسیرهای نسبی + API_BASE
// ============================================================

import React, { useEffect, useState, useMemo, useCallback, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import userAxios from '../userAxios';
import { toast } from '../components/Toast';
import { Skeleton } from '../components/Skeleton';
import { SiteImage } from '../../utils/SiteImage';
import { API_BASE } from '../../config/api';

// ✅ NEW: Import helpers اعداد فارسی
import { toFa, toFaDate } from '../../utils/numbers';

// ============================================================
//  Helpers
// ============================================================
const daysSince = (iso) => {
  if (!iso) return 0;
  return Math.max(0, Math.floor((Date.now() - new Date(iso).getTime()) / (1000 * 60 * 60 * 24)));
};

const ALLOWED_AVATAR_TYPES = ['image/jpeg', 'image/png', 'image/webp', 'image/jpg'];
const MAX_AVATAR_SIZE = 2 * 1024 * 1024; // 2 MB

// ============================================================
//  🎨 کلاس‌های مشترک
// ============================================================
const inputCls = "w-full px-3.5 py-3 min-h-[52px] border-2 border-ink-200 dark:border-dark-600 rounded-2xl text-sm bg-paper-50 dark:bg-ink-700 text-ink-900 dark:text-cream-100 placeholder-ink-400 dark:placeholder-cream-400 focus:ring-2 focus:ring-brand-500/30 focus:border-brand-500 outline-none transition font-medium";

// ============================================================
//  🌈 AvatarUploader — گرم و دوستانه با ring و glow
// ============================================================
function AvatarUploader({ userData, onAvatarChange, username }) {
  const [uploading, setUploading] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [imgError, setImgError] = useState(false);
  const [dragOver, setDragOver] = useState(false);
  const fileInputRef = useRef(null);

  const avatarUrl = userData?.avatar_url;
  const initial = (userData?.full_name || username || '?').charAt(0).toUpperCase();
  const fullUrl = avatarUrl?.startsWith('http')
    ? avatarUrl
    : avatarUrl
    ? `${API_BASE}${avatarUrl}`
    : '';

  const handleFileSelect = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!ALLOWED_AVATAR_TYPES.includes(file.type)) {
      toast.error('فقط فرمت‌های JPG، PNG، WEBP مجاز هستند');
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }
    if (file.size > MAX_AVATAR_SIZE) {
      toast.error('حجم فایل نباید بیشتر از ۲ مگابایت باشد');
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    setUploading(true);
    setImgError(false);

    try {
      const formData = new FormData();
      formData.append('file', file);

      const res = await userAxios.post(
        '/api/auth/avatar',
        formData,
        { headers: { 'Content-Type': 'multipart/form-data' } }
      );

      const newAvatarUrl = res.data.avatar_url;

      const updatedUser = { ...userData, avatar_url: newAvatarUrl };
      localStorage.setItem('userData', JSON.stringify(updatedUser));

      onAvatarChange?.(newAvatarUrl);
      toast.success('عکس پروفایل با موفقیت آپلود شد 🎉');

      if (fileInputRef.current) fileInputRef.current.value = '';
    } catch (err) {
      const detail = err.response?.data?.detail;
      toast.error(typeof detail === 'string' ? detail : 'خطا در آپلود عکس');
    } finally {
      setUploading(false);
    }
  };

  const handleRemove = async () => {
    if (!avatarUrl) return;
    if (!window.confirm('عکس پروفایل حذف شود؟')) return;

    setDeleting(true);
    try {
      await userAxios.delete('/api/auth/avatar');

      const updatedUser = { ...userData, avatar_url: null };
      localStorage.setItem('userData', JSON.stringify(updatedUser));

      onAvatarChange?.(null);
      toast.success('عکس پروفایل حذف شد');
    } catch (err) {
      const detail = err.response?.data?.detail;
      toast.error(typeof detail === 'string' ? detail : 'خطا در حذف عکس');
    } finally {
      setDeleting(false);
    }
  };

  const busy = uploading || deleting;

  return (
    <div className="flex flex-col sm:flex-row items-center sm:items-start gap-4 sm:gap-5">

      {/* 🌈 Avatar Display — با ring گرم و glow */}
      <div className="relative flex-shrink-0 group">
        {/* Glow effect behind avatar */}
        <div className="absolute -inset-2 bg-brand-gradient rounded-3xl blur-lg opacity-20 group-hover:opacity-40 transition-opacity" aria-hidden="true" />

        <div className="relative">
          {fullUrl && !imgError ? (
            <div
              className={`w-24 h-24 sm:w-28 sm:h-28 rounded-3xl overflow-hidden shadow-brand-lg ring-4 ring-brand-200/50 dark:ring-brand-500/30 transition-transform group-hover:scale-105 ${dragOver ? 'ring-accent-400 dark:ring-accent-500/50 scale-105' : ''}`}
              onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
              onDragLeave={() => setDragOver(false)}
              onDrop={(e) => {
                e.preventDefault();
                setDragOver(false);
                if (e.dataTransfer.files?.[0] && fileInputRef.current) {
                  const dt = new DataTransfer();
                  dt.items.add(e.dataTransfer.files[0]);
                  fileInputRef.current.files = dt.files;
                  handleFileSelect({ target: fileInputRef.current });
                }
              }}
            >
              <img
                src={fullUrl}
                alt={userData?.full_name || username}
                className="w-full h-full object-cover"
                onError={() => setImgError(true)}
              />
            </div>
          ) : (
            <div
              className={`w-24 h-24 sm:w-28 sm:h-28 rounded-3xl bg-brand-gradient flex items-center justify-center text-4xl sm:text-5xl font-black text-white shadow-brand-lg transition-transform group-hover:scale-105 ${dragOver ? 'ring-4 ring-accent-400 dark:ring-accent-500/50 scale-105' : ''}`}
              onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
              onDragLeave={() => setDragOver(false)}
              onDrop={(e) => {
                e.preventDefault();
                setDragOver(false);
                if (e.dataTransfer.files?.[0] && fileInputRef.current) {
                  const dt = new DataTransfer();
                  dt.items.add(e.dataTransfer.files[0]);
                  fileInputRef.current.files = dt.files;
                  handleFileSelect({ target: fileInputRef.current });
                }
              }}
            >
              {initial}
            </div>
          )}

          {/* Uploading Overlay */}
          {uploading && (
            <div className="absolute inset-0 rounded-3xl bg-ink-900/60 backdrop-blur-sm flex items-center justify-center">
              <span className="inline-block w-8 h-8 border-4 border-white border-t-transparent rounded-full animate-spin" />
            </div>
          )}

          {/* Active Badge — گرم‌تر */}
          {!uploading && (
            <span
              className="absolute -bottom-1 -left-1 w-7 h-7 rounded-full bg-accent-400 border-2 border-paper-50 dark:border-ink-800 shadow-sm animate-pulse-soft flex items-center justify-center p-1.5"
              title="فعال"
              aria-label="کاربر فعال"
            >
              <SiteImage
                imageKey="icon_paw"
                fallback="🐾"
                alt=""
                className="w-full h-full object-contain"
              />
            </span>
          )}
        </div>
      </div>

      {/* Upload Actions — گرم‌تر */}
      <div className="flex-1 min-w-0 flex flex-col items-center sm:items-start gap-3 w-full sm:w-auto">
        <div className="text-center sm:text-right">
          <h3 className="font-display font-black text-ink-900 dark:text-cream-100 text-sm mb-1 flex items-center gap-1.5">
            <SiteImage
              imageKey="icon_camera"
              fallback="📸"
              alt=""
              className="w-4 h-4 object-contain"
            />
            <span>عکس پروفایل</span>
          </h3>
          <p className="text-[10px] text-ink-500 dark:text-cream-400 leading-relaxed">
            JPG، PNG یا WEBP — حداکثر ۲ مگابایت
            <br />
            <span className="text-brand-600 dark:text-brand-400 font-bold">یا فایل را اینجا بکشید</span>
          </p>
        </div>

        <div className="flex flex-col sm:flex-row gap-2 w-full sm:w-auto">
          <input
            ref={fileInputRef}
            type="file"
            accept="image/jpeg,image/png,image/webp"
            onChange={handleFileSelect}
            className="hidden"
            disabled={busy}
          />

          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            disabled={busy}
            className="w-full sm:w-auto min-h-[44px] px-4 py-2.5 bg-brand-gradient hover:opacity-95 active:opacity-90 text-white rounded-2xl text-xs font-black transition shadow-brand hover:shadow-brand-lg flex items-center justify-center gap-2 touch-target disabled:opacity-50"
          >
            <SiteImage
              imageKey={avatarUrl ? 'icon_edit' : 'icon_camera'}
              fallback={avatarUrl ? '🔄' : '📸'}
              alt=""
              className="w-4 h-4 object-contain"
            />
            <span>{avatarUrl ? 'تغییر عکس' : 'آپلود عکس'}</span>
          </button>

          {avatarUrl && (
            <button
              type="button"
              onClick={handleRemove}
              disabled={busy}
              className="w-full sm:w-auto min-h-[44px] px-4 py-2.5 bg-rose-50 dark:bg-rose-500/15 hover:bg-rose-100 dark:hover:bg-rose-500/25 active:bg-rose-200 text-rose-700 dark:text-rose-300 border border-rose-200 dark:border-rose-500/30 rounded-2xl text-xs font-black transition flex items-center justify-center gap-2 touch-target disabled:opacity-50"
            >
              <SiteImage
                imageKey="icon_trash"
                fallback="🗑️"
                alt=""
                className="w-4 h-4 object-contain"
              />
              <span>حذف عکس</span>
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

// ============================================================
//  🌈 SectionHeader — گرم با آیکون بزرگ و background دوستانه
// ============================================================
function SectionHeader({ icon, iconKey, title, subtitle, iconBg = 'brand' }) {
  const bgs = {
    brand:  'bg-brand-100 dark:bg-brand-500/20 text-brand-700 dark:text-brand-300',
    accent: 'bg-accent-100 dark:bg-accent-500/20 text-accent-700 dark:text-accent-300',
    ink:    'bg-ink-100 dark:bg-ink-700 text-ink-700 dark:text-cream-200',
    rose:   'bg-rose-100 dark:bg-rose-500/20 text-rose-700 dark:text-rose-300',
  };
  const bg = bgs[iconBg] || bgs.brand;

  return (
    <div className="px-5 py-4 border-b border-ink-200 dark:border-dark-700 flex items-center gap-3">
      <div className={`w-11 h-11 rounded-2xl ${bg} flex items-center justify-center p-2 flex-shrink-0 shadow-soft`}>
        {iconKey ? (
          <SiteImage
            imageKey={iconKey}
            fallback={icon}
            alt=""
            className="w-full h-full object-contain"
          />
        ) : (
          <span className="text-xl">{icon}</span>
        )}
      </div>
      <div className="min-w-0 flex-1">
        <h2 className="font-display font-black text-ink-900 dark:text-cream-100 text-sm flex items-center gap-2">
          <span className="w-1 h-4 bg-brand-500 rounded-full" aria-hidden="true" />
          {title}
        </h2>
        {subtitle && (
          <p className="text-[10px] text-ink-500 dark:text-cream-400 mt-1 leading-relaxed font-bold mr-3">
            {subtitle}
          </p>
        )}
      </div>
    </div>
  );
}

// ============================================================
//  کامپوننت اصلی
// ============================================================
export default function Profile() {
  const navigate = useNavigate();

  const [form, setForm] = useState({
    full_name: '',
    phone: '',
    email: '',
    password: '',
  });
  const [username, setUsername] = useState('');
  const [createdAt, setCreatedAt] = useState(null);
  const [userData, setUserData] = useState(() => {
    try {
      return JSON.parse(localStorage.getItem('userData') || '{}');
    } catch {
      return {};
    }
  });
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [confirmDeleteText, setConfirmDeleteText] = useState('');
  const [showDeleteModal, setShowDeleteModal] = useState(false);

  // ============================================================
  //  بارگذاری اولیه
  // ============================================================
  const loadProfile = useCallback(async () => {
    try {
      const res = await userAxios.get('/api/auth/me');
      setUsername(res.data.username || '');
      setCreatedAt(res.data.created_at || null);
      setForm({
        full_name: res.data.full_name || '',
        phone: res.data.phone || '',
        email: res.data.email || '',
        password: '',
      });

      const fresh = {
        id: res.data.id,
        username: res.data.username,
        full_name: res.data.full_name,
        phone: res.data.phone,
        email: res.data.email,
        address: res.data.address,
        avatar_url: res.data.avatar_url || null,
      };
      setUserData(fresh);
      localStorage.setItem('userData', JSON.stringify(fresh));
    } catch (err) {
      const detail = err.response?.data?.detail;
      toast.error(typeof detail === 'string' ? detail : 'خطا در دریافت اطلاعات');
    }
  }, []);

  useEffect(() => {
    loadProfile().finally(() => setLoading(false));
  }, [loadProfile]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm(prev => ({ ...prev, [name]: value }));
  };

  // ============================================================
  //  Save
  // ============================================================
  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!form.phone.trim()) {
      toast.error('شمارهٔ موبایل الزامی است');
      return;
    }

    if (form.password && form.password.length < 4) {
      toast.error('رمز عبور باید حداقل ۴ کاراکتر باشد');
      return;
    }

    setSaving(true);

    try {
      const payload = {
        full_name: form.full_name.trim(),
        phone: form.phone.trim(),
        email: form.email.trim(),
      };
      if (form.password) {
        payload.password = form.password;
      }

      const res = await userAxios.put('/api/auth/profile', payload);
      const updatedUser = res.data?.user || {};

      const newUserData = {
        ...userData,
        ...updatedUser,
        avatar_url: updatedUser.avatar_url ?? userData.avatar_url ?? null,
      };

      localStorage.setItem('userData', JSON.stringify(newUserData));
      setUserData(newUserData);

      setForm({
        full_name: updatedUser.full_name || '',
        phone: updatedUser.phone || '',
        email: updatedUser.email || '',
        password: '',
      });

      toast.success('پروفایل با موفقیت ذخیره شد ✨');
      window.dispatchEvent(new Event('userDataUpdated'));

    } catch (err) {
      console.error('خطا در ذخیره پروفایل:', err);
      const detail = err.response?.data?.detail;
      toast.error(typeof detail === 'string' ? detail : 'خطا در ذخیره پروفایل');
    } finally {
      setSaving(false);
    }
  };

  // ============================================================
  //  Copy phone
  // ============================================================
  const copyPhone = async () => {
    if (!form.phone) return;
    try {
      await navigator.clipboard.writeText(form.phone);
      toast.success('شمارهٔ موبایل کپی شد');
    } catch {
      toast.error('کپی ناموفق بود');
    }
  };

  // ============================================================
  //  Delete account
  // ============================================================
  const handleDeleteAccount = async () => {
    if (confirmDeleteText.trim() !== username) {
      toast.error('نام کاربری مطابقت ندارد');
      return;
    }
    setDeleting(true);
    try {
      await userAxios.delete('/api/auth/account');

      localStorage.removeItem('userToken');
      localStorage.removeItem('userData');
      sessionStorage.removeItem('pendingOrder');
      sessionStorage.removeItem('quickCalcForm');
      sessionStorage.removeItem('quickCalcResult');

      toast.success('اکانت با موفقیت حذف شد');

      setTimeout(() => {
        window.location.href = '/register';
      }, 800);
    } catch (err) {
      const detail = err.response?.data?.detail;
      toast.error(typeof detail === 'string' ? detail : 'خطا در حذف اکانت');
    } finally {
      setDeleting(false);
    }
  };

  // ============================================================
  //  Avatar change callback
  // ============================================================
  const handleAvatarChange = (newUrl) => {
    setUserData(prev => ({ ...prev, avatar_url: newUrl }));
    window.dispatchEvent(new Event('userDataUpdated'));
  };

  const membershipDays = useMemo(() => daysSince(createdAt), [createdAt]);
  const displayName = form.full_name || username;

  // ============================================================
  //  Loading
  // ============================================================
  if (loading) {
    return (
      <div className="max-w-3xl mx-auto space-y-4" dir="rtl">
        <Skeleton className="h-12 w-48 rounded-xl" />
        <Skeleton className="h-52 rounded-3xl" />
        <Skeleton className="h-64 rounded-3xl" />
        <Skeleton className="h-40 rounded-3xl" />
      </div>
    );
  }

  return (
    <div className="max-w-3xl mx-auto space-y-4" dir="rtl">

      {/* ============================================================ */}
      {/*  🌈 Header — گرم با گرادیان برند + 🐾 متحرک                  */}
      {/* ============================================================ */}
      <div className="relative">
        {/* Decorative paw */}
        <div className="absolute -top-2 -right-2 w-8 h-8 opacity-10 animate-float-soft" aria-hidden="true">
          <SiteImage
            imageKey="icon_paw"
            fallback="🐾"
            alt=""
            className="w-full h-full object-contain"
          />
        </div>

        <div className="flex items-center gap-3 mb-2">
          <div className="w-10 h-px bg-brand-500" aria-hidden="true" />
          <span className="text-[10px] sm:text-[11px] font-black tracking-[0.2em] uppercase text-brand-600 dark:text-brand-400">
            پروفایل کاربری
          </span>
        </div>
        <h1 className="font-display font-black text-2xl sm:text-3xl md:text-4xl text-ink-900 dark:text-cream-100 leading-tight tracking-tightest mb-1.5 flex items-center gap-2">
          <span>حساب من</span>
          <span className="w-7 h-7 sm:w-8 sm:h-8 animate-float-soft" aria-hidden="true">
            <SiteImage
              imageKey="icon_paw"
              fallback="🐾"
              alt=""
              className="w-full h-full object-contain"
            />
          </span>
        </h1>
        <p className="text-xs sm:text-sm text-ink-500 dark:text-cream-400">
          مدیریت اطلاعات شخصی و امنیت حساب
        </p>
      </div>

      {/* ============================================================ */}
      {/*  🌈 Hero Card — گرم با گرادیان و glow                         */}
      {/* ============================================================ */}
      <div className="friendly-card relative bg-gradient-to-br from-paper-50 via-brand-50/30 to-paper-50 dark:from-ink-800 dark:via-ink-800 dark:to-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft overflow-hidden noise-overlay">

        {/* Overline تزئینی بالا */}
        <div className="absolute top-0 right-1/2 translate-x-1/2 w-20 h-0.5 bg-brand-500" aria-hidden="true" />

        {/* Decorative paws در پس‌زمینه */}
        <div className="absolute -top-6 -left-6 w-16 h-16 opacity-5" aria-hidden="true">
          <SiteImage
            imageKey="icon_paw"
            fallback="🐾"
            alt=""
            className="w-full h-full object-contain"
          />
        </div>
        <div className="absolute -bottom-8 -right-8 w-20 h-20 opacity-5" aria-hidden="true">
          <SiteImage
            imageKey="icon_paw"
            fallback="🐾"
            alt=""
            className="w-full h-full object-contain"
          />
        </div>

        <div className="relative p-5 sm:p-6">

          {/* Avatar Uploader */}
          <AvatarUploader
            userData={userData}
            onAvatarChange={handleAvatarChange}
            username={username}
          />

          {/* Divider */}
          <div className="my-5 border-t border-ink-200 dark:border-dark-700" />

          {/* Info Row */}
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
            <div className="min-w-0 text-center sm:text-right">
              <h2 className="font-display font-black text-lg sm:text-xl text-ink-900 dark:text-cream-100 leading-tight truncate mb-1">
                {displayName}
              </h2>
              <div className="text-xs text-brand-600 dark:text-brand-400 font-mono break-safe flex items-center justify-center sm:justify-start gap-1" dir="ltr">
                <span aria-hidden="true">@</span>
                <span className="truncate">{username}</span>
              </div>
            </div>

            {/* Copy phone — گرم‌تر */}
            {form.phone && (
              <button
                type="button"
                onClick={copyPhone}
                className="w-full sm:w-auto min-h-[40px] flex items-center justify-center gap-2 bg-paper-100 dark:bg-ink-700 hover:bg-brand-50 dark:hover:bg-brand-500/15 hover:border-brand-300 dark:hover:border-brand-500/40 border border-ink-200 dark:border-dark-600 px-3.5 py-2 rounded-2xl text-xs font-black text-ink-800 dark:text-cream-100 transition touch-target flex-shrink-0"
                title="کپی شمارهٔ موبایل"
              >
                <SiteImage
                  imageKey="icon_clipboard"
                  fallback="📋"
                  alt=""
                  className="w-4 h-4 object-contain"
                />
                <span>کپی موبایل</span>
              </button>
            )}
          </div>

          {/* Badges — گرم‌تر */}
          <div className="flex items-center gap-2 flex-wrap justify-center sm:justify-start mt-4">
            {membershipDays > 0 && (
              <span className="bg-brand-50 dark:bg-brand-500/15 text-brand-700 dark:text-brand-300 border border-brand-200 dark:border-brand-500/30 px-3 py-1.5 rounded-full text-[10px] sm:text-[11px] font-black inline-flex items-center gap-1.5 shadow-soft">
                <SiteImage
                  imageKey="icon_clock"
                  fallback="📅"
                  alt=""
                  className="w-3.5 h-3.5 object-contain"
                />
                <span className="font-num">{toFa(membershipDays)} روز عضویت</span>
              </span>
            )}

            {createdAt && (
              <span className="bg-accent-50 dark:bg-accent-500/15 text-accent-700 dark:text-accent-300 border border-accent-200 dark:border-accent-500/30 px-3 py-1.5 rounded-full text-[10px] sm:text-[11px] font-bold inline-flex items-center gap-1.5 shadow-soft">
                <SiteImage
                  imageKey="icon_sparkles"
                  fallback="🎉"
                  alt=""
                  className="w-3.5 h-3.5 object-contain"
                />
                <span>از {toFaDate(createdAt, { year: 'numeric', month: 'long', day: 'numeric' })}</span>
              </span>
            )}
          </div>
        </div>
      </div>

      {/* ============================================================ */}
      {/*  🌈 Personal Info Form — با friendly-card                    */}
      {/* ============================================================ */}
      <form onSubmit={handleSubmit} className="friendly-card bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft overflow-hidden">

        <SectionHeader
          icon="✏️"
          iconKey="icon_edit"
          title="اطلاعات شخصی"
          subtitle="اطلاعات تماس خود را به‌روز نگه دار"
          iconBg="brand"
        />

        <div className="p-5 space-y-4">

          {/* Username (readonly) */}
          <div>
            <label className="block text-xs font-black text-ink-800 dark:text-cream-200 mb-1.5">
              نام کاربری
              <span className="text-ink-400 dark:text-cream-500 font-normal mr-1.5">(غیرقابل تغییر)</span>
            </label>
            <div className="relative">
              <input
                value={username}
                disabled
                className="w-full px-4 py-3 pr-11 min-h-[52px] bg-paper-100 dark:bg-ink-900/50 border-2 border-ink-200 dark:border-dark-600 rounded-2xl text-sm text-ink-500 dark:text-cream-400 font-mono cursor-not-allowed break-safe"
                dir="ltr"
                readOnly
              />
              <span className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-ink-400 dark:text-cream-500" aria-hidden="true">
                <SiteImage
                  imageKey="icon_lock"
                  fallback="🔒"
                  alt=""
                  className="w-full h-full object-contain"
                />
              </span>
            </div>
          </div>

          {/* Full name */}
          <div>
            <label className="block text-xs font-black text-ink-800 dark:text-cream-200 mb-1.5">
              نام کامل
            </label>
            <input
              name="full_name"
              value={form.full_name}
              onChange={handleChange}
              placeholder="نام و نام خانوادگی"
              autoComplete="name"
              className={inputCls}
            />
            <div className="text-[10px] text-ink-500 dark:text-cream-400 mt-1.5 leading-relaxed flex items-center gap-1">
              <SiteImage
                imageKey="icon_lightbulb"
                fallback="💡"
                alt=""
                className="w-3 h-3 object-contain flex-shrink-0"
              />
              <span>این نام در لیبل ارسال و کارت دستورالعمل چاپ می‌شود</span>
            </div>
          </div>

          {/* Phone + Email */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-black text-ink-800 dark:text-cream-200 mb-1.5">
                موبایل <span className="text-brand-500">*</span>
              </label>
              <input
                name="phone"
                type="tel"
                inputMode="tel"
                autoComplete="tel"
                value={form.phone}
                onChange={handleChange}
                placeholder="09121234567"
                dir="ltr"
                required
                className={`${inputCls} font-num text-left`}
              />
              <div className="text-[10px] text-ink-500 dark:text-cream-400 mt-1.5 leading-relaxed flex items-center gap-1">
                <SiteImage
                  imageKey="icon_phone"
                  fallback="📱"
                  alt=""
                  className="w-3 h-3 object-contain flex-shrink-0"
                />
                <span>برای هماهنگی ارسال سفارش</span>
              </div>
            </div>

            <div>
              <label className="block text-xs font-black text-ink-800 dark:text-cream-200 mb-1.5">
                ایمیل
              </label>
              <input
                name="email"
                type="email"
                autoComplete="email"
                value={form.email}
                onChange={handleChange}
                placeholder="example@mail.com"
                dir="ltr"
                className={`${inputCls} font-mono text-left`}
              />
              <div className="text-[10px] text-ink-500 dark:text-cream-400 mt-1.5 leading-relaxed flex items-center gap-1">
                <SiteImage
                  imageKey="icon_email"
                  fallback="✉️"
                  alt=""
                  className="w-3 h-3 object-contain flex-shrink-0"
                />
                <span>اختیاری</span>
              </div>
            </div>
          </div>

          {/* Address note — گرم‌تر */}
          <div className="bg-gradient-to-r from-brand-50/80 to-accent-50/40 dark:from-brand-500/10 dark:to-accent-500/5 border border-brand-200 dark:border-brand-500/30 rounded-2xl p-3.5 flex items-start gap-3">
            <div className="w-9 h-9 rounded-xl bg-brand-100 dark:bg-brand-500/20 flex items-center justify-center p-2 flex-shrink-0">
              <SiteImage
                imageKey="icon_location"
                fallback="📍"
                alt=""
                className="w-full h-full object-contain"
              />
            </div>
            <div className="flex-1 min-w-0">
              <div className="text-[11px] font-black text-brand-800 dark:text-brand-200 mb-0.5">
                آدرس تحویل
              </div>
              <div className="text-[10px] text-brand-700 dark:text-brand-300 leading-relaxed">
                آدرس دقیق تحویل رو موقع ثبت هر سفارش روی نقشه انتخاب می‌کنی. 🗺️
              </div>
            </div>
          </div>
        </div>

        {/* Footer با دکمهٔ ذخیره — گرم‌تر */}
        <div className="border-t border-ink-200 dark:border-dark-700 bg-gradient-to-r from-paper-100/50 to-brand-50/30 dark:from-ink-900/30 dark:to-brand-500/5 px-5 py-4 flex justify-end">
          <button
            type="submit"
            disabled={saving}
            className="w-full sm:w-auto min-h-[48px] px-6 py-3 bg-brand-gradient hover:opacity-95 active:opacity-90 text-white rounded-2xl text-sm font-black transition disabled:opacity-50 flex items-center justify-center gap-2 shadow-brand hover:shadow-brand-lg touch-target"
          >
            {saving ? (
              <>
                <span className="inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                <span>در حال ذخیره...</span>
              </>
            ) : (
              <>
                <SiteImage
                  imageKey="icon_save"
                  fallback="💾"
                  alt=""
                  className="w-4 h-4 object-contain"
                />
                <span>ذخیرهٔ تغییرات</span>
              </>
            )}
          </button>
        </div>
      </form>

      {/* ============================================================ */}
      {/*  🌈 Security Card — با friendly-card                          */}
      {/* ============================================================ */}
      <div className="friendly-card bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft overflow-hidden">

        <SectionHeader
          icon="🔐"
          iconKey="icon_lock"
          title="امنیت حساب"
          subtitle="رمز عبور خود را به‌صورت دوره‌ای تغییر بده"
          iconBg="ink"
        />

        <div className="p-5">
          <label className="block text-xs font-black text-ink-800 dark:text-cream-200 mb-1.5">
            رمز عبور جدید
            <span className="text-ink-400 dark:text-cream-500 font-normal mr-1.5">(اختیاری)</span>
          </label>
          <div className="relative">
            <input
              name="password"
              type={showPassword ? 'text' : 'password'}
              autoComplete="new-password"
              value={form.password}
              onChange={handleChange}
              placeholder="خالی بگذار تا تغییر نکند"
              dir="ltr"
              className={`${inputCls} pl-12 font-mono text-left`}
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute left-2 top-1/2 -translate-y-1/2 w-10 h-10 flex items-center justify-center text-ink-400 dark:text-cream-400 hover:text-brand-600 dark:hover:text-brand-400 hover:bg-brand-50 dark:hover:bg-brand-500/15 active:bg-brand-100 rounded-xl transition p-2 touch-target"
              title={showPassword ? 'پنهان کردن' : 'نمایش'}
              aria-label={showPassword ? 'پنهان کردن رمز' : 'نمایش رمز'}
              tabIndex={-1}
            >
              <SiteImage
                imageKey="icon_eye"
                fallback={showPassword ? '🙈' : '👁️'}
                alt=""
                className="w-full h-full object-contain"
              />
            </button>
          </div>
          <div className="text-[10px] text-ink-500 dark:text-cream-400 mt-1.5 leading-relaxed flex items-center gap-1">
            <SiteImage
              imageKey="icon_shield"
              fallback="🛡️"
              alt=""
              className="w-3 h-3 object-contain flex-shrink-0"
            />
            <span>حداقل ۴ کاراکتر — در صورت خالی بودن، رمز فعلی حفظ می‌شود</span>
          </div>
        </div>
      </div>

      {/* ============================================================ */}
      {/*  🌈 Danger Zone — واضح اما نه ترسناک                          */}
      {/* ============================================================ */}
      <div className="relative bg-gradient-to-br from-rose-50 to-rose-100/30 dark:from-rose-500/10 dark:to-rose-500/5 border-2 border-rose-200 dark:border-rose-500/30 rounded-3xl overflow-hidden friendly-card">

        <div className="p-5 sm:p-6 flex items-start gap-4">
          <div className="w-12 h-12 rounded-2xl bg-rose-100 dark:bg-rose-500/20 flex items-center justify-center p-3 flex-shrink-0 shadow-soft">
            <SiteImage
              imageKey="icon_warning"
              fallback="⚠️"
              alt=""
              className="w-full h-full object-contain"
            />
          </div>
          <div className="flex-1 min-w-0">
            <h2 className="font-display font-black text-rose-700 dark:text-rose-300 text-sm sm:text-base mb-2 flex items-center gap-2">
              <span className="w-1 h-4 bg-rose-500 rounded-full" aria-hidden="true" />
              منطقهٔ خطر
            </h2>
            <p className="text-xs text-rose-600 dark:text-rose-400 mb-4 leading-relaxed break-safe">
              با حذف اکانت، دسترسی تو قطع می‌شود. سفارش‌های قبلی در سیستم ادمین باقی می‌مونن.
              این عمل <strong className="font-black">قابل بازگشت نیست</strong>.
            </p>

            <button
              type="button"
              onClick={() => {
                setConfirmDeleteText('');
                setShowDeleteModal(true);
              }}
              className="w-full sm:w-auto min-h-[48px] bg-paper-50 dark:bg-ink-800 hover:bg-rose-100 dark:hover:bg-rose-500/20 active:bg-rose-200 text-rose-700 dark:text-rose-300 border-2 border-rose-300 dark:border-rose-500/40 px-5 py-3 rounded-2xl text-sm font-black transition flex items-center justify-center gap-2 shadow-soft touch-target"
            >
              <SiteImage
                imageKey="icon_trash"
                fallback="🗑️"
                alt=""
                className="w-4 h-4 object-contain"
              />
              <span>حذف دائمی اکانت</span>
            </button>
          </div>
        </div>
      </div>

      {/* ============================================================ */}
      {/*  🌈 Delete Confirmation Modal — گرم‌تر                         */}
      {/* ============================================================ */}
      {showDeleteModal && (
        <div className="fixed inset-0 bg-ink-900/70 backdrop-blur-sm flex items-end sm:items-center justify-center z-[60] p-0 sm:p-4">
          <div className="bg-paper-50 dark:bg-ink-800 rounded-t-3xl sm:rounded-3xl shadow-editorial w-full sm:max-w-md max-h-[92vh] overflow-hidden flex flex-col safe-bottom border border-ink-200 dark:border-dark-700 animate-slide-down">

            <div className="sm:hidden w-12 h-1.5 bg-ink-300 dark:bg-dark-600 rounded-full mx-auto mt-2 flex-shrink-0" />

            {/* Header — گرم‌تر */}
            <div className="p-5 border-b border-ink-200 dark:border-dark-700 flex items-center gap-3 flex-shrink-0">
              <div className="w-12 h-12 rounded-3xl bg-rose-100 dark:bg-rose-500/20 flex items-center justify-center p-3 flex-shrink-0 shadow-soft">
                <SiteImage
                  imageKey="icon_warning"
                  fallback="⚠️"
                  alt=""
                  className="w-full h-full object-contain"
                />
              </div>
              <div className="flex-1 min-w-0">
                <h3 className="font-display font-black text-ink-900 dark:text-cream-100 text-base flex items-center gap-2">
                  <span className="w-1 h-4 bg-rose-500 rounded-full" aria-hidden="true" />
                  حذف اکانت
                </h3>
                <p className="text-[11px] text-ink-500 dark:text-cream-400 mt-0.5">
                  این عمل قابل بازگشت نیست
                </p>
              </div>
              <button
                onClick={() => setShowDeleteModal(false)}
                disabled={deleting}
                className="w-10 h-10 flex items-center justify-center rounded-xl text-ink-400 hover:text-rose-600 hover:bg-rose-50 dark:hover:bg-rose-500/15 active:bg-rose-100 transition flex-shrink-0 touch-target"
                title="بستن"
                aria-label="بستن"
              >
                ✕
              </button>
            </div>

            <div className="p-5 space-y-4 overflow-y-auto flex-1">
              <div className="text-sm text-ink-700 dark:text-cream-200 leading-relaxed">
                برای تأیید حذف، لطفاً نام کاربری خود را تایپ کن:
              </div>

              <div className="bg-gradient-to-r from-paper-100 to-brand-50/30 dark:from-ink-900/50 dark:to-brand-500/5 border-2 border-ink-200 dark:border-dark-600 rounded-2xl px-4 py-3.5 text-center">
                <span className="font-mono text-sm font-black text-ink-800 dark:text-cream-100 break-safe" dir="ltr">
                  {username}
                </span>
              </div>

              <input
                type="text"
                value={confirmDeleteText}
                onChange={(e) => setConfirmDeleteText(e.target.value)}
                placeholder="نام کاربری..."
                dir="ltr"
                autoFocus
                autoComplete="off"
                className="w-full px-4 py-3.5 min-h-[52px] border-2 border-rose-300 dark:border-rose-500/40 rounded-2xl text-sm bg-paper-50 dark:bg-ink-700 text-ink-900 dark:text-cream-100 font-mono text-center placeholder-ink-400 dark:placeholder-cream-400 focus:ring-2 focus:ring-rose-500/30 focus:border-rose-500 outline-none transition"
              />
            </div>

            <div className="p-4 border-t border-ink-200 dark:border-dark-700 flex flex-col-reverse sm:flex-row gap-2.5 bg-paper-100/50 dark:bg-ink-900/40 flex-shrink-0">
              <button
                onClick={() => setShowDeleteModal(false)}
                disabled={deleting}
                className="w-full sm:flex-1 min-h-[48px] px-4 py-3 bg-paper-50 dark:bg-ink-700 border border-ink-200 dark:border-dark-600 text-ink-700 dark:text-cream-200 rounded-2xl font-black text-sm hover:bg-paper-100 dark:hover:bg-ink-600 active:bg-paper-200 transition touch-target"
              >
                انصراف
              </button>
              <button
                onClick={handleDeleteAccount}
                disabled={deleting || confirmDeleteText.trim() !== username}
                className="w-full sm:flex-1 min-h-[48px] px-4 py-3 bg-rose-500 hover:bg-rose-600 active:bg-rose-700 text-white rounded-2xl font-black text-sm transition disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 shadow-sm touch-target"
              >
                {deleting ? (
                  <>
                    <span className="inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                    <span>در حال حذف...</span>
                  </>
                ) : (
                  <>
                    <SiteImage
                      imageKey="icon_trash"
                      fallback="🗑️"
                      alt=""
                      className="w-4 h-4 object-contain"
                    />
                    <span>حذف دائمی</span>
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      )}

    </div>
  );
}