// frontend/src/user/pages/TicketsList.jsx
import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { Link } from 'react-router-dom';
import userAxios from '../userAxios';
import { useToast } from '../components/Toast';
import { SkeletonTable } from '../components/Skeleton';
import { EmptyTickets } from '../components/EmptyState';
import { SiteImage } from '../../utils/SiteImage';

// ✅ NEW: Import helpers اعداد فارسی
import { toFa, toFaDate, toFaTime } from '../../utils/numbers';

// ============================================================
//  🎨 نگاشت وضعیت‌ها — Editorial palette
// ============================================================
const STATUS_LABELS = {
  open: {
    text: 'باز',
    color: 'bg-brand-50 dark:bg-brand-500/15 text-brand-700 dark:text-brand-300 border-brand-200 dark:border-brand-500/30',
    icon: '📬',
    iconKey: 'icon_ticket',
    strip: 'bg-brand-500',
  },
  admin_reply: {
    text: 'پاسخ ادمین',
    color: 'bg-accent-50 dark:bg-accent-500/15 text-accent-700 dark:text-accent-300 border-accent-200 dark:border-accent-500/30',
    icon: '💬',
    iconKey: 'icon_chat',
    strip: 'bg-accent-500',
  },
  user_reply: {
    text: 'پاسخ شما ثبت شد',
    color: 'bg-brand-100 dark:bg-brand-500/20 text-brand-800 dark:text-brand-200 border-brand-300 dark:border-brand-500/40',
    icon: '📩',
    iconKey: 'icon_reply',
    strip: 'bg-brand-700',
  },
  closed: {
    text: 'بسته شده',
    color: 'bg-ink-100 dark:bg-ink-700 text-ink-700 dark:text-cream-200 border-ink-200 dark:border-dark-600',
    icon: '🔒',
    iconKey: 'icon_lock',
    strip: 'bg-ink-400',
  },
};

const PRIORITY_LABELS = {
  low: {
    text: 'پایین',
    icon: '🟢',
    iconKey: 'icon_priority_low',
    color: 'bg-accent-50 dark:bg-accent-500/15 text-accent-700 dark:text-accent-300 border-accent-200 dark:border-accent-500/30',
  },
  medium: {
    text: 'متوسط',
    icon: '🟡',
    iconKey: 'icon_priority_medium',
    color: 'bg-brand-50 dark:bg-brand-500/15 text-brand-700 dark:text-brand-300 border-brand-200 dark:border-brand-500/30',
  },
  high: {
    text: 'بالا',
    icon: '🔴',
    iconKey: 'icon_priority_high',
    color: 'bg-rose-50 dark:bg-rose-500/15 text-rose-700 dark:text-rose-300 border-rose-200 dark:border-rose-500/30',
  },
};

const FILTER_CHIPS = [
  { key: '',            label: 'همه',          icon: '📋', iconKey: 'icon_clipboard' },
  { key: 'open',        label: 'باز',          icon: '📬', iconKey: 'icon_ticket' },
  { key: 'user_reply',  label: 'منتظر پاسخ',   icon: '📩', iconKey: 'icon_reply' },
  { key: 'admin_reply', label: 'پاسخ ادمین',   icon: '💬', iconKey: 'icon_chat' },
  { key: 'closed',      label: 'بسته شده',     icon: '🔒', iconKey: 'icon_lock' },
];

const POLL_INTERVAL_MS = 10000;

// ============================================================
//  StatCard — Editorial
//  ✅ FIX: tabular-nums → font-num
//  ✅ iconKey برای SiteImage
// ============================================================
function StatCard({ icon, iconKey, value, label, accent = 'brand' }) {
  const accents = {
    brand:  { badge: 'bg-brand-100 dark:bg-brand-500/20 text-brand-700 dark:text-brand-300', num: 'text-brand-600 dark:text-brand-400' },
    accent: { badge: 'bg-accent-100 dark:bg-accent-500/20 text-accent-700 dark:text-accent-300', num: 'text-accent-600 dark:text-accent-400' },
    rose:   { badge: 'bg-rose-100 dark:bg-rose-500/20 text-rose-700 dark:text-rose-300', num: 'text-rose-600 dark:text-rose-400' },
    ink:    { badge: 'bg-ink-100 dark:bg-ink-700 text-ink-700 dark:text-cream-200', num: 'text-ink-800 dark:text-cream-100' },
  };
  const a = accents[accent] || accents.brand;

  return (
    <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl p-4 sm:p-5 shadow-soft hover:shadow-lifted transition-all">
      <div className="flex items-center justify-between mb-2.5">
        <span className={`w-10 h-10 rounded-2xl flex items-center justify-center p-2.5 ${a.badge}`} aria-hidden="true">
          {iconKey ? (
            <SiteImage
              imageKey={iconKey}
              fallback={icon}
              alt=""
              className="w-full h-full object-contain"
            />
          ) : (
            <span className="text-lg">{icon}</span>
          )}
        </span>
      </div>
      <div className={`font-display font-black text-2xl sm:text-3xl font-num leading-none mb-2 ${a.num}`}>
        {value}
      </div>
      <div className="text-xs font-black text-ink-700 dark:text-cream-200 leading-tight">
        {label}
      </div>
    </div>
  );
}

// ============================================================
//  TicketCard — Editorial
// ============================================================
function TicketCard({ ticket }) {
  const cfg = STATUS_LABELS[ticket.status] || STATUS_LABELS.open;
  const pCfg = PRIORITY_LABELS[ticket.priority] || PRIORITY_LABELS.medium;
  const hasUnread = ticket.unread_count > 0;

  return (
    <Link
      to={`/panel/tickets/${ticket.id}`}
      className={`block bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft hover:shadow-lifted hover:-translate-y-0.5 active:bg-paper-100 dark:active:bg-ink-700/60 transition-all overflow-hidden group relative touch-target ${
        hasUnread ? 'ring-2 ring-brand-200 dark:ring-brand-500/40' : ''
      }`}
    >
      <div className="flex">

        {/* Strip رنگی کناری */}
        <div className={`w-1.5 ${cfg.strip} flex-shrink-0`} aria-hidden="true" />

        <div className="flex-1 p-4 sm:p-5 min-w-0">
          <div className="flex items-start gap-3 sm:gap-4">

            {/* Icon وضعیت */}
            <div className={`w-11 h-11 sm:w-12 sm:h-12 rounded-2xl flex items-center justify-center p-2.5 flex-shrink-0 border ${cfg.color} group-hover:scale-105 transition-transform`} aria-hidden="true">
              <SiteImage
                imageKey={cfg.iconKey}
                fallback={cfg.icon}
                alt=""
                className="w-full h-full object-contain"
              />
            </div>

            {/* Body */}
            <div className="flex-1 min-w-0">

              {/* Header: ID + Subject + Unread */}
              <div className="flex items-start gap-2 mb-2 flex-wrap">
                {/* ✅ FIX: font-mono tabular-nums → font-num + toFa */}
                <span className="font-num text-[10px] sm:text-[11px] text-ink-400 dark:text-cream-500 flex-shrink-0">
                  #{toFa(ticket.id)}
                </span>
                <h3 className="font-display font-black text-ink-900 dark:text-cream-100 text-sm sm:text-base leading-snug flex-1 min-w-0 truncate">
                  {ticket.subject}
                </h3>
                {hasUnread && (
                  <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-rose-500 text-white text-[10px] font-black animate-pulse flex-shrink-0 shadow-sm whitespace-nowrap">
                    <span className="w-1.5 h-1.5 rounded-full bg-white" aria-hidden="true" />
                    <span className="font-num">{toFa(ticket.unread_count)} جدید</span>
                  </span>
                )}
              </div>

              {/* Badges */}
              <div className="flex items-center gap-1.5 flex-wrap mb-2.5">
                <span className={`inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-black border ${cfg.color} whitespace-nowrap`}>
                  <span className="w-3 h-3" aria-hidden="true">
                    <SiteImage
                      imageKey={cfg.iconKey}
                      fallback={cfg.icon}
                      alt=""
                      className="w-full h-full object-contain"
                    />
                  </span>
                  <span>{cfg.text}</span>
                </span>
                <span className={`inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-black border ${pCfg.color} whitespace-nowrap`}>
                  <span className="w-3 h-3" aria-hidden="true">
                    <SiteImage
                      imageKey={pCfg.iconKey}
                      fallback={pCfg.icon}
                      alt=""
                      className="w-full h-full object-contain"
                    />
                  </span>
                  <span>اولویت {pCfg.text}</span>
                </span>
              </div>

              {/* Last message */}
              {ticket.last_message && (
                <div className={`text-[11px] sm:text-xs truncate leading-relaxed mb-2.5 flex items-center gap-1 ${
                  hasUnread
                    ? 'text-ink-800 dark:text-cream-100 font-bold'
                    : 'text-ink-500 dark:text-cream-400'
                }`}>
                  <span className="w-3 h-3 flex-shrink-0 opacity-60" aria-hidden="true">
                    <SiteImage
                      imageKey="icon_chat"
                      fallback="💬"
                      alt=""
                      className="w-full h-full object-contain"
                    />
                  </span>
                  <span className="truncate">{ticket.last_message}</span>
                </div>
              )}

              {/* Footer */}
              <div className="flex items-center gap-3 text-[10px] text-ink-400 dark:text-cream-500 flex-wrap">
                <span className="flex items-center gap-1">
                  <span className="w-3 h-3" aria-hidden="true">
                    <SiteImage
                      imageKey="icon_clock"
                      fallback="🗓️"
                      alt=""
                      className="w-full h-full object-contain"
                    />
                  </span>
                  {/* ✅ FIX: font-mono tabular-nums → font-num + toFaDate */}
                  <span className="font-num">
                    {toFaDate(ticket.updated_at || ticket.created_at, { year: 'numeric', month: 'short', day: 'numeric' })}
                  </span>
                </span>
                {(ticket.updated_at || ticket.created_at) && (
                  // ✅ FIX: font-mono tabular-nums → font-num + toFaTime
                  <span className="flex items-center gap-1 font-num">
                    <span className="w-3 h-3" aria-hidden="true">
                      <SiteImage
                        imageKey="icon_clock"
                        fallback="🕐"
                        alt=""
                        className="w-full h-full object-contain"
                      />
                    </span>
                    <span>{toFaTime(ticket.updated_at || ticket.created_at, { hour: '2-digit', minute: '2-digit' })}</span>
                  </span>
                )}
              </div>
            </div>

            {/* Arrow — فقط دسکتاپ */}
            <SiteImage imageKey="icon_arrow_left" fallback="←" alt="" className="hidden sm:inline text-ink-300 dark:text-dark-600 text-xl flex-shrink-0 self-center group-hover:text-brand-500 group-hover:-translate-x-1 transition" />
          </div>
        </div>
      </div>
    </Link>
  );
}

// ============================================================
//  کامپوننت اصلی
// ============================================================
export default function TicketsList() {
  const { showToast } = useToast();
  const [tickets, setTickets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [lastUpdated, setLastUpdated] = useState(null);
  const [statusFilter, setStatusFilter] = useState('');
  const [searchInput, setSearchInput] = useState('');
  const [searchTerm, setSearchTerm] = useState('');

  const isMountedRef = useRef(true);
  const lastTotalUnreadRef = useRef(0);

  // ============================================================
  //  Fetch
  // ============================================================
  const fetchTickets = useCallback(async (silent = false) => {
    if (!silent) setLoading(true);
    try {
      const res = await userAxios.get('/api/tickets');
      const list = res.data || [];
      setTickets(list);
      setLastUpdated(new Date());

      // اعلان اگه پیام جدید اومد
      const totalUnread = list.reduce((s, t) => s + (t.unread_count || 0), 0);
      if (silent && totalUnread > lastTotalUnreadRef.current) {
        const diff = totalUnread - lastTotalUnreadRef.current;
        // ✅ FIX: {diff} → {toFa(diff)}
        showToast('info', `${toFa(diff)} پیام جدید از پشتیبانی رسید!`, { duration: 5000 });
      }
      lastTotalUnreadRef.current = totalUnread;
    } catch (err) {
      if (!silent) showToast('error', err.response?.data?.detail || 'خطا در دریافت تیکت‌ها');
    } finally {
      if (!silent) setLoading(false);
    }
  }, [showToast]);

  // ============================================================
  //  Initial + Polling
  // ============================================================
  useEffect(() => {
    isMountedRef.current = true;
    fetchTickets();

    const id = setInterval(() => {
      if (isMountedRef.current && document.visibilityState === 'visible') {
        fetchTickets(true);
      }
    }, POLL_INTERVAL_MS);

    const onVisibility = () => {
      if (document.visibilityState === 'visible') fetchTickets(true);
    };
    document.addEventListener('visibilitychange', onVisibility);

    return () => {
      isMountedRef.current = false;
      clearInterval(id);
      document.removeEventListener('visibilitychange', onVisibility);
    };
  }, [fetchTickets]);

  // ============================================================
  //  Debounce search
  // ============================================================
  useEffect(() => {
    const t = setTimeout(() => setSearchTerm(searchInput), 300);
    return () => clearTimeout(t);
  }, [searchInput]);

  // ============================================================
  //  Stats
  // ============================================================
  const stats = useMemo(() => {
    const acc = { total: tickets.length, unread: 0 };
    tickets.forEach(t => {
      acc[t.status] = (acc[t.status] || 0) + 1;
      acc.unread += (t.unread_count || 0);
    });
    return acc;
  }, [tickets]);

  // ============================================================
  //  Filtered
  // ============================================================
  const filtered = useMemo(() => {
    let list = tickets;

    if (statusFilter) {
      list = list.filter(t => t.status === statusFilter);
    }

    if (searchTerm.trim()) {
      const q = searchTerm.trim().toLowerCase();
      list = list.filter(t =>
        (t.subject || '').toLowerCase().includes(q) ||
        (t.last_message || '').toLowerCase().includes(q) ||
        String(t.id).includes(q)
      );
    }

    return list;
  }, [tickets, statusFilter, searchTerm]);

  const hasActiveFilters = statusFilter || searchInput.trim();

  const clearFilters = () => {
    setStatusFilter('');
    setSearchInput('');
    setSearchTerm('');
  };

  // ============================================================
  //  رندر
  // ============================================================
  return (
    <div className="max-w-5xl mx-auto space-y-5" dir="rtl">

      {/* ============================================================ */}
      {/*  Header Editorial                                             */}
      {/* ============================================================ */}
      <div className="flex flex-col sm:flex-row sm:items-end sm:justify-between gap-4">
        <div className="min-w-0">
          <div className="flex items-center gap-3 mb-3">
            <div className="w-10 h-px bg-brand-500" aria-hidden="true" />
            <span className="text-[10px] sm:text-[11px] font-black tracking-[0.2em] uppercase text-brand-600 dark:text-brand-400">
              پشتیبانی
            </span>
          </div>

          <h1 className="font-display font-black text-2xl sm:text-3xl md:text-4xl text-ink-900 dark:text-cream-100 leading-tight tracking-tightest flex items-center gap-3 flex-wrap mb-2">
            <span>تیکت‌های پشتیبانی</span>
            {stats.unread > 0 && (
              <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] sm:text-[11px] font-black bg-rose-50 dark:bg-rose-500/15 text-rose-700 dark:text-rose-300 border border-rose-200 dark:border-rose-500/30 whitespace-nowrap">
                <span className="w-1.5 h-1.5 rounded-full bg-rose-500 animate-pulse" aria-hidden="true" />
                {/* ✅ FIX: font-mono tabular-nums → font-num + toFa */}
                <span className="font-num">{toFa(stats.unread)}</span>
                <span>پیام جدید</span>
              </span>
            )}
          </h1>

          <p className="text-xs sm:text-sm text-ink-500 dark:text-cream-400 flex items-center gap-2 flex-wrap">
            {lastUpdated ? (
              <>
                <span className="w-1.5 h-1.5 rounded-full bg-accent-400 animate-pulse" aria-hidden="true" />
                <span className="whitespace-nowrap">
                  بروزرسانی خودکار —{' '}
                  {/* ✅ FIX: font-mono tabular-nums + toLocaleTimeString → font-num + toFaTime */}
                  <span className="font-num">
                    {toFaTime(lastUpdated, { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </span>
              </>
            ) : (
              'در حال بارگذاری...'
            )}
          </p>
        </div>

        <Link
          to="/panel/tickets/new"
          className="group inline-flex items-center justify-center gap-2 min-h-[48px] px-5 py-3 bg-brand-gradient hover:opacity-95 active:opacity-90 text-white rounded-2xl text-sm font-black shadow-brand hover:shadow-brand-lg transition-all hover:-translate-y-0.5 active:translate-y-0 w-full sm:w-auto flex-shrink-0 touch-target"
        >
          <span className="w-4 h-4 group-hover:rotate-90 transition-transform duration-300" aria-hidden="true">
            <SiteImage
              imageKey="icon_plus"
              fallback="➕"
              alt=""
              className="w-full h-full object-contain"
            />
          </span>
          <span>ارسال تیکت جدید</span>
        </Link>
      </div>

      {/* ============================================================ */}
      {/*  Stats Cards — Editorial                                     */}
      {/* ============================================================ */}
      {tickets.length > 0 && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          {/* ✅ FIX: fmt → toFa */}
          <StatCard
            icon="📋"
            iconKey="icon_clipboard"
            value={toFa(stats.total || 0)}
            label="کل تیکت‌ها"
            accent="ink"
          />
          <StatCard
            icon="📬"
            iconKey="icon_ticket"
            value={toFa((stats.open || 0) + (stats.user_reply || 0))}
            label="منتظر پاسخ"
            accent={(stats.open || 0) + (stats.user_reply || 0) > 0 ? 'rose' : 'brand'}
          />
          <StatCard
            icon="💬"
            iconKey="icon_chat"
            value={toFa(stats.admin_reply || 0)}
            label="پاسخ ادمین"
            accent="accent"
          />
          <StatCard
            icon="🔒"
            iconKey="icon_lock"
            value={toFa(stats.closed || 0)}
            label="بسته شده"
            accent="ink"
          />
        </div>
      )}

      {/* ============================================================ */}
      {/*  Filters — Editorial                                         */}
      {/* ============================================================ */}
      {tickets.length > 0 && (
        <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl p-4 sm:p-5 shadow-soft space-y-4">

          {/* Status chips */}
          <div className="overflow-x-auto scrollbar-hide -mx-4 px-4 sm:mx-0 sm:px-0">
            <div className="flex items-center gap-2 min-w-max sm:min-w-0 sm:flex-wrap">
              {FILTER_CHIPS.map(chip => {
                const isActive = statusFilter === chip.key;
                const count = chip.key === ''
                  ? stats.total
                  : chip.key === 'open'
                  ? (stats.open || 0) + (stats.user_reply || 0)
                  : (stats[chip.key] || 0);

                return (
                  <button
                    key={chip.key || 'all'}
                    onClick={() => setStatusFilter(chip.key)}
                    className={`min-h-[40px] px-3.5 py-2 rounded-xl border text-xs font-black transition flex items-center gap-1.5 flex-shrink-0 touch-target active:scale-[0.98] ${
                      isActive
                        ? 'bg-ink-900 dark:bg-cream-100 text-cream-50 dark:text-ink-900 border-ink-900 dark:border-cream-100 shadow-soft'
                        : 'bg-paper-100 dark:bg-ink-700/50 text-ink-700 dark:text-cream-200 border-ink-200 dark:border-dark-600 hover:bg-paper-200 dark:hover:bg-ink-700 active:bg-paper-300'
                    }`}
                  >
                    <span className="w-3.5 h-3.5" aria-hidden="true">
                      <SiteImage
                        imageKey={chip.iconKey}
                        fallback={chip.icon}
                        alt=""
                        className="w-full h-full object-contain"
                      />
                    </span>
                    <span>{chip.label}</span>
                    {count > 0 && (
                      // ✅ FIX: font-mono tabular-nums → font-num + toFa
                      <span className={`text-[10px] font-black px-1.5 py-0.5 rounded-full font-num ${
                        isActive
                          ? 'bg-cream-50/20 dark:bg-ink-900/15'
                          : 'bg-paper-50 dark:bg-ink-800'
                      }`}>
                        {toFa(count)}
                      </span>
                    )}
                  </button>
                );
              })}
            </div>
          </div>

          {/* Search */}
          <div className="pt-4 border-t border-ink-200 dark:border-dark-700">
            <div className="relative">
              <input
                type="text"
                value={searchInput}
                onChange={(e) => setSearchInput(e.target.value)}
                placeholder="جستجو در موضوع، متن پیام یا شماره تیکت..."
                className="w-full px-4 py-3 pr-11 pl-12 min-h-[48px] border-2 border-ink-200 dark:border-dark-600 rounded-2xl text-sm bg-paper-50 dark:bg-ink-700 text-ink-900 dark:text-cream-100 placeholder-ink-400 dark:placeholder-cream-500 focus:ring-2 focus:ring-brand-500/30 focus:border-brand-500 outline-none transition"
              />
              <span className="absolute right-3.5 top-1/2 -translate-y-1/2 w-4 h-4 pointer-events-none" aria-hidden="true">
                <SiteImage
                  imageKey="icon_search"
                  fallback="🔍"
                  alt=""
                  className="w-full h-full object-contain opacity-60"
                />
              </span>
              {searchInput && (
                <button
                  onClick={() => setSearchInput('')}
                  className="absolute left-2 top-1/2 -translate-y-1/2 w-9 h-9 flex items-center justify-center text-ink-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-500/15 active:bg-rose-100 rounded-xl transition touch-target"
                  title="پاک کردن"
                  aria-label="پاک کردن جستجو"
                >
                  ✕
                </button>
              )}
            </div>

            {hasActiveFilters && (
              <div className="mt-3 flex items-center justify-between gap-2 flex-wrap">
                <div className="text-[11px] text-ink-500 dark:text-cream-400 break-safe">
                  {/* ✅ FIX: font-mono tabular-nums → font-num + toFa */}
                  نمایش <span className="font-black text-ink-800 dark:text-cream-100 font-num">{toFa(filtered.length)}</span> از{' '}
                  <span className="font-num">{toFa(tickets.length)}</span> تیکت
                </div>
                <button
                  onClick={clearFilters}
                  className="min-h-[40px] px-3.5 py-1.5 bg-rose-50 dark:bg-rose-500/15 hover:bg-rose-100 dark:hover:bg-rose-500/25 active:bg-rose-200 border border-rose-200 dark:border-rose-500/30 text-rose-700 dark:text-rose-300 rounded-xl text-[11px] font-black transition flex items-center gap-1 touch-target"
                >
                  <SiteImage imageKey="icon_close" fallback="✕" alt="" className="leading-none inline-flex" />
                  <span>پاک کردن فیلترها</span>
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* ============================================================ */}
      {/*  Content                                                      */}
      {/* ============================================================ */}
      {loading ? (
        <SkeletonTable rows={5} cols={5} />
      ) : tickets.length === 0 ? (
        <EmptyTickets
          onAddTicket={() => window.location.href = '/panel/tickets/new'}
          size="lg"
        />
      ) : filtered.length === 0 ? (
        <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl p-6 sm:p-10 lg:p-14 text-center shadow-soft">
          <div className="w-14 h-14 mb-4 mx-auto opacity-50" aria-hidden="true">
            <SiteImage
              imageKey="icon_search"
              fallback="🔍"
              alt=""
              className="w-full h-full object-contain"
            />
          </div>
          <div className="font-display font-black text-ink-800 dark:text-cream-100 mb-2 text-base">
            نتیجه‌ای یافت نشد
          </div>
          <div className="text-xs text-ink-500 dark:text-cream-400 mb-5 leading-relaxed px-2 break-safe max-w-md mx-auto">
            با این فیلترها تیکتی پیدا نشد
          </div>
          <button
            onClick={clearFilters}
            className="w-full sm:w-auto min-h-[48px] inline-flex items-center justify-center gap-2 bg-brand-gradient hover:opacity-95 active:opacity-90 text-white px-5 py-3 rounded-2xl text-sm font-black transition shadow-brand touch-target"
          >
            <SiteImage imageKey="icon_close" fallback="✕" alt="" className="leading-none inline-flex" />
            <span>پاک کردن فیلترها</span>
          </button>
        </div>
      ) : (
        <div className="space-y-3">
          {filtered.map(t => (
            <TicketCard key={t.id} ticket={t} />
          ))}
        </div>
      )}

    </div>
  );
}
