const ORDER_FORM_PATH = '/#order-form-section';

// ============================================================
//  🟢 UserAvatar
// ============================================================
const UserAvatar = memo(function UserAvatar({
  userData,
  size = 'md',
  className = '',
  showRing = false,
}) {
  const [imgError, setImgError] = useState(false);

  const sizeClasses = {
    xs: 'w-7 h-7 text-xs',
    sm: 'w-9 h-9 text-sm',
    md: 'w-10 h-10 text-base',
    lg: 'w-12 h-12 text-lg',
  };
  const sz = sizeClasses[size] || sizeClasses.md;
  const avatarUrl = userData?.avatar_url;
  const initial = (userData?.full_name || userData?.username || '?')
    .charAt(0)
    .toUpperCase();

  if (avatarUrl && !imgError) {
    const fullUrl = resolveAssetUrl(avatarUrl);
    return (
      <div
        className={`${sz} ${className} rounded-full overflow-hidden flex-shrink-0 shadow-sm ${
          showRing
            ? 'ring-2 ring-white dark:ring-[#1C1612] ring-offset-2 ring-offset-[#C87941] dark:ring-offset-[#D99B4D]'
            : 'border border-[#E8DFD3] dark:border-[#2E241B]'
        }`}
      >
        <img
          src={fullUrl}
          alt="آواتار"
          className="w-full h-full object-cover"
          onError={() => setImgError(true)}
        />
      </div>
    );
  }

  return (
    <div
      className={`${sz} ${className} rounded-full bg-gradient-to-br from-[#C87941] to-[#B56A36] dark:from-[#D99B4D] dark:to-[#E8B35C] flex items-center justify-center text-white dark:text-[#17120E] font-bold flex-shrink-0 shadow-sm`}
    >
      {initial}
    </div>
  );
});

// ============================================================
//  🟢 SidebarItem — Modern Style
// ============================================================
const SidebarItem = memo(function SidebarItem({
  item,
  active,
  expanded = true,
  onClick,
}) {
  return (
    <Link
      to={item.path}
      onClick={onClick}
      className={`group relative w-full text-right transition-all duration-300 flex items-center gap-3 ${
        expanded
          ? 'px-3 py-2.5 min-h-[44px] rounded-xl mb-1'
          : 'px-0 py-2.5 min-h-[44px] rounded-xl justify-center mb-1'
      } ${
        active
          ? 'bg-[#C87941]/10 dark:bg-[#D99B4D]/15 text-[#C87941] dark:text-[#D99B4D] font-bold'
          : 'text-[#5C4A38] dark:text-[#A89580] hover:bg-[#F4EDE0] dark:hover:bg-[#1F1812] hover:text-[#1A1208] dark:hover:text-[#FDFCFA] font-medium'
      }`}
      title={!expanded ? item.label : undefined}
    >
      {active && expanded && (
        <span className="absolute right-0 top-1/2 -translate-y-1/2 w-1 h-6 bg-[#C87941] dark:bg-[#D99B4D] rounded-l-full" />
      )}

      <span
        className={`text-base flex items-center justify-center w-5 h-5 transition-transform ${
          active ? 'scale-110' : 'group-hover:scale-105'
        }`}
      >
        {item.imageKey ? (
          <SiteImage
            imageKey={item.imageKey}
            fallback={item.icon}
            alt=""
            className="w-5 h-5 flex items-center justify-center object-contain"
          />
        ) : (
          item.icon
        )}
      </span>

      {expanded && (
        <>
          <span className="flex-1 text-sm truncate">{item.label}</span>
          {item.badge > 0 && (
            <span
              className={`text-[10px] font-bold min-w-[18px] h-[18px] px-1.5 rounded-full flex items-center justify-center font-num transition-transform ${
                active
                  ? 'bg-[#C87941] text-white'
                  : 'bg-[#C87941]/10 text-[#C87941] dark:bg-[#D99B4D]/20 dark:text-[#D99B4D]'
              }`}
            >
              {item.badge > 99 ? '۹۹+' : toFa(item.badge)}
            </span>
          )}
        </>
      )}

      {!expanded && item.badge > 0 && (
        <span className="absolute top-1.5 left-1.5 min-w-[14px] h-[14px] px-1 rounded-full bg-[#C87941] dark:bg-[#D99B4D] text-white dark:text-[#17120E] text-[9px] font-bold flex items-center justify-center border-2 border-[#FBF9F5] dark:border-[#15110D]">
          {item.badge > 9 ? '۹' : toFa(item.badge)}
        </span>
      )}
    </Link>
  );
});

