import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { Link } from 'react-router-dom';
import userAxios from '../userAxios';
import { Skeleton } from '../components/Skeleton';
import { useToast } from '../components/Toast';

import { SiteImage } from '../../utils/SiteImage';
import { useCart } from '../hooks/useCart';
import { STORAGE_KEYS } from '../../constants/storageKeys';

import {
  toFa,
  toFaShort,
  toFaDate,
  toFaTimeAgo,
  toFaDateFull,
} from '../../utils/numbers';

const ORDER_FORM_PATH = '/#order-form-section';

// ============================================================
//  🎨 نگاشت وضعیت‌ها (رنگ‌های سمنتیک برای وضوح)
// ============================================================
const STATUS_LABELS = {
  pending:    { text: 'در انتظار پرداخت',  color: 'bg-amber-50 text-amber-700 border-amber-200 dark:bg-amber-500/10 dark:text-amber-400 dark:border-amber-500/20',   icon: '⏳', imageKey: 'icon_pending', strip: 'bg-amber-500' },
  paid:       { text: 'پرداخت شده',        color: 'bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-500/10 dark:text-emerald-400 dark:border-emerald-500/20', icon: '💳', imageKey: 'icon_payment', strip: 'bg-emerald-500' },
  processing: { text: 'در حال آماده‌سازی', color: 'bg-blue-50 text-blue-700 border-blue-200 dark:bg-blue-500/10 dark:text-blue-400 dark:border-blue-500/20', icon: '🔨', imageKey: 'icon_processing', strip: 'bg-blue-500' },
  shipped:    { text: 'ارسال شده',         color: 'bg-indigo-50 text-indigo-700 border-indigo-200 dark:bg-indigo-500/10 dark:text-indigo-400 dark:border-indigo-500/20', icon: '🚚', imageKey: 'icon_shipped', strip: 'bg-indigo-500' },
  delivered:  { text: 'تحویل شده',         color: 'bg-teal-50 text-teal-700 border-teal-200 dark:bg-teal-500/10 dark:text-teal-400 dark:border-teal-500/20', icon: '✅', imageKey: 'icon_delivered', strip: 'bg-teal-500' },
  cancelled:  { text: 'لغو شده',           color: 'bg-rose-50 text-rose-700 border-rose-200 dark:bg-rose-500/10 dark:text-rose-400 dark:border-rose-500/20', icon: '❌', imageKey: 'icon_cancelled', strip: 'bg-rose-500' },
};

const PAYMENT_STATUS_LABELS = {
  pending:          { text: 'در انتظار آپلود فیش', color: 'bg-[#F9F4EC] text-[#5C4A38] border-[#E8DFD3] dark:bg-[#1F1812] dark:text-[#A89580] dark:border-[#2A2218]', icon: '📎', imageKey: 'icon_receipt' },
  receipt_uploaded: { text: 'منتظر تأیید ادمین',   color: 'bg-blue-50 text-blue-700 border-blue-200 dark:bg-blue-500/10 dark:text-blue-400 dark:border-blue-500/20', icon: '⏳', imageKey: 'icon_pending' },
  verified:         { text: 'تأیید شده',           color: 'bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-500/10 dark:text-emerald-400 dark:border-emerald-500/20', icon: '✅', imageKey: 'icon_check' },
  rejected:         { text: 'رد شده',              color: 'bg-rose-50 text-rose-700 border-rose-200 dark:bg-rose-500/10 dark:text-rose-400 dark:border-rose-500/20', icon: '❌', imageKey: 'icon_error' },
};

const ORDER_STEPS = [
  { key: 'pending',    label: 'ثبت' },
  { key: 'paid',       label: 'پرداخت' },
  { key: 'processing', label: 'آماده' },
  { key: 'shipped',    label: 'ارسال' },
  { key: 'delivered',  label: 'تحویل' },
];

// 🌾 پالت گرم آواتار سگ‌ها
const AVATAR_COLORS = [
  'from-[#D99B4D] to-[#B56A36]',  // آجری-هویجی
  'from-[#E8B35C] to-[#C87941]',  // هویجی
  'from-[#A89478] to-[#5C4A38]',  // قهوه‌ای گرم
  'from-[#7BA383] to-[#5A7D62]',  // زیتونی
  'from-[#D99B4D] to-[#A89478]',  // میکس گرم
];

const getAvatarGradient = (id) => AVATAR_COLORS[(id || 0) % AVATAR_COLORS.length];
const getStepIndex = (status) => {
  const idx = ORDER_STEPS.findIndex(s => s.key === status);
  return idx >= 0 ? idx : 0;
};

// ============================================================
//  MiniStepper — Warm & Compact
// ============================================================
function MiniStepper({ status }) {
  const currentStep = getStepIndex(status);
  const isCancelled = status === 'cancelled';

  if (isCancelled) {
    return (
      <div className="mt-3 py-2 px-3 rounded-xl bg-rose-50 dark:bg-rose-500/10 border border-rose-100 dark:border-rose-500/20 text-center">
        <span className="text-xs font-bold text-rose-600 dark:text-rose-400 inline-flex items-center gap-1.5">
          <SiteImage imageKey="icon_cancelled" fallback="❌" alt="" className="w-4 h-4 object-contain" />
          <span>این سفارش لغو شده است</span>
        </span>
      </div>
    );
  }

  return (
    <div className="mt-4 mb-1 flex items-center gap-1.5">
      {ORDER_STEPS.map((step, idx) => {
        const isDone = idx < currentStep;
        const isActive = idx === currentStep;
        const isLast = idx === ORDER_STEPS.length - 1;

        return (
          <React.Fragment key={step.key}>
            <div className="flex flex-col items-center gap-1 min-w-0 flex-1 relative">
              <div
                className={`w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-bold border-2 transition-all z-10 ${
                  isDone
                    ? 'border-[#C87941] bg-[#C87941] text-white dark:border-[#D99B4D] dark:bg-[#D99B4D] dark:text-[#17120E]'
                    : isActive
                    ? 'border-[#C87941] text-[#C87941] bg-[#FFFCF7] dark:border-[#D99B4D] dark:text-[#D99B4D] dark:bg-[#1C1612]'
                    : 'border-[#E8DFD3] dark:border-[#2A2218] text-[#A89478] dark:text-[#6B5A48] bg-[#FFFCF7] dark:bg-[#1C1612]'
                }`}
              >
                {isDone ? <SiteImage imageKey="icon_check" fallback="✓" alt="" className="w-3 h-3 object-contain" /> : idx + 1}
              </div>
              <span className={`text-[10px] whitespace-nowrap ${
                isDone || isActive ? 'font-bold text-[#1A1208] dark:text-[#FDFCFA]' : 'font-medium text-[#A89478] dark:text-[#6B5A48]'
              }`}>
                {step.label}
              </span>
            </div>
            {!isLast && (
              <div className={`flex-1 h-[2px] mb-4 rounded-full ${
                idx < currentStep ? 'bg-[#C87941] dark:bg-[#D99B4D]' : 'bg-[#F4EDE0] dark:bg-[#2A2218]'
              }`} />
            )}
          </React.Fragment>
        );
      })}
    </div>
  );
}

// ============================================================
//  StatPill — Compact & Warm
// ============================================================
function StatPill({ icon, imageKey, value, label, to, accent = 'default' }) {
  const accents = {
    default:  'text-[#1A1208] dark:text-[#FDFCFA]',
    brand:    'text-[#C87941] dark:text-[#D99B4D]',
    accent:   'text-emerald-600 dark:text-emerald-400',
    rose:     'text-rose-600 dark:text-rose-400',
    warning:  'text-amber-600 dark:text-amber-400',
  };

  return (
    <Link
      to={to}
      className="group flex flex-col items-center justify-center p-3 rounded-2xl bg-[#FFFCF7] dark:bg-[#1C1612] border border-[#EFE6D8] dark:border-[#2A2218] shadow-sm hover:shadow-md hover:-translate-y-0.5 transition-all duration-300 min-w-0"
    >
      <div className="w-8 h-8 rounded-full bg-[#F9F4EC] dark:bg-[#1F1812] flex items-center justify-center mb-1.5 group-hover:scale-110 transition-transform">
        {imageKey ? (
          <SiteImage imageKey={imageKey} fallback={icon} alt="" className="w-4 h-4 object-contain" />
        ) : (
          <span className="text-base" aria-hidden="true">{icon}</span>
        )}
      </div>
      <div className={`font-display font-bold text-lg font-num mb-0.5 leading-none ${accents[accent]}`}>
        {value}
      </div>
      <div className="text-[11px] font-medium text-[#A89478] dark:text-[#6B5A48] truncate w-full text-center">
        {label}
      </div>
    </Link>
  );
}

// ============================================================
//  🛒 CartBanner — Warm & Compact
// ============================================================
function CartBanner({ cart }) {
  if (!cart || cart.totalCount === 0) return null;

  return (
    <Link
      to="/cart"
      className="group block bg-[#FFFCF7] dark:bg-[#1C1612] rounded-2xl p-3 border border-[#EFE6D8] dark:border-[#2A2218] shadow-sm hover:shadow-md transition-all duration-300 overflow-hidden relative"
    >
      <div className="absolute top-0 right-0 w-1.5 h-full bg-[#C87941] dark:bg-[#D99B4D] rounded-r-2xl" aria-hidden="true" />
      <div className="flex items-center gap-3 relative">
        <div className="w-10 h-10 rounded-xl bg-[#FFF4EB] dark:bg-[#1F1812] flex items-center justify-center flex-shrink-0 group-hover:scale-105 transition-transform">
          <SiteImage imageKey="icon_cart" fallback="🛒" alt="سبد خرید" className="w-5 h-5 object-contain text-[#C87941] dark:text-[#D99B4D]" />
        </div>
        <div className="flex-1 min-w-0">
          <div className="font-display font-bold text-[#1A1208] dark:text-[#FDFCFA] text-sm truncate mb-0.5">
            {toFa(cart.totalCount)} سفارش در سبد خرید شما
          </div>
          <div className="text-xs text-[#7A6852] dark:text-[#A89580] font-num">
            مبلغ تقریبی: <span className="font-bold text-[#C87941] dark:text-[#D99B4D]">{toFa(cart.totalAmount)}</span> تومان
          </div>
        </div>
        <div className="flex-shrink-0 w-7 h-7 rounded-full bg-[#F9F4EC] dark:bg-[#1F1812] flex items-center justify-center group-hover:bg-[#FFF4EB] dark:group-hover:bg-[#C87941]/20 transition-colors">
          <SiteImage imageKey="icon_arrow_left" fallback="←" alt="" className="w-3.5 h-3.5 object-contain text-[#A89478] dark:text-[#6B5A48] group-hover:text-[#C87941] dark:group-hover:text-[#D99B4D]" />
        </div>
      </div>
    </Link>
  );
}

// ============================================================
//  🌈 GettingStartedCard — Warm Welcome
// ============================================================
