// ============================================================
//  SectionHeader — Warm & Compact
// ============================================================
function SectionHeader({ title, subtitle, to, linkLabel }) {
  return (
    <div className="px-4 py-3 border-b border-[#EFE6D8] dark:border-[#2A2218] flex items-center justify-between gap-2">
      <div className="min-w-0 flex-1">
        <h2 className="font-display font-bold text-[#1A1208] dark:text-[#FDFCFA] text-sm sm:text-base leading-tight truncate">
          {title}
        </h2>
        {subtitle && (
          <p className="text-xs text-[#A89478] dark:text-[#6B5A48] mt-0.5 truncate">
            {subtitle}
          </p>
        )}
      </div>
      {to && linkLabel && (
        <Link
          to={to}
          className="text-xs text-[#C87941] dark:text-[#D99B4D] hover:text-[#B56A36] dark:hover:text-[#E8B35C] font-bold transition flex items-center gap-1 group flex-shrink-0"
        >
          <span className="hidden sm:inline">{linkLabel}</span>
          <SiteImage
            imageKey="icon_arrow_left"
            fallback="←"
            alt=""
            className="w-3.5 h-3.5 object-contain group-hover:-translate-x-1 transition-transform"
          />
        </Link>
      )}
    </div>
  );
}

// ============================================================
//  کامپوننت اصلی
// ============================================================
export default function Dashboard() {
  const userData = useMemo(() => {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEYS.USER_DATA) || '{}');
    } catch {
      return {};
    }
  }, []);

  const cart = useCart();

  const { showToast } = useToast();
  const showToastRef = useRef(showToast);
  useEffect(() => {
    showToastRef.current = showToast;
  }, [showToast]);

  const [loading, setLoading] = useState(true);
  const [data, setData] = useState({
    stats: { total_orders: 0, total_dogs: 0, open_tickets: 0, pending_payments: 0 },
    last_order: null,
    dogs: [],
    recent_orders: [],
  });

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const res = await userAxios.get('/api/dashboard-summary');
      setData(res.data || {
        stats: { total_orders: 0, total_dogs: 0, open_tickets: 0, pending_payments: 0 },
        last_order: null,
        dogs: [],
        recent_orders: [],
      });
    } catch (err) {
      showToastRef.current(
        'error',
        err.response?.data?.detail || 'خطا در بارگذاری داشبورد'
      );
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const { stats, last_order, dogs, recent_orders } = data;

  const { greeting, today } = useMemo(() => {
    const currentHour = new Date().getHours();
    return {
      greeting: currentHour < 12 ? 'صبح بخیر' : currentHour < 18 ? 'وقت بخیر' : 'شب بخیر',
      today: toFaDateFull(new Date()),
    };
  }, []);

  const hasAnyActivity = useMemo(() => {
    return (
      last_order ||
      (Array.isArray(dogs) && dogs.length > 0) ||
      (Array.isArray(recent_orders) && recent_orders.length > 0) ||
      (stats.total_orders > 0)
    );
  }, [last_order, dogs, recent_orders, stats.total_orders]);

  if (loading) {
    return (
      <div className="space-y-3" dir="rtl">
        <Skeleton className="h-10 rounded-xl" />
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
          {[1, 2, 3, 4].map(i => (
            <Skeleton key={i} className="h-24 rounded-2xl" />
          ))}
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-3">
          <Skeleton className="h-56 rounded-2xl" />
          <Skeleton className="h-56 rounded-2xl" />
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-3 sm:space-y-5" dir="rtl">

      {/* 🌈 Greeting & Date */}
      <div className="flex items-center justify-between gap-3 flex-wrap px-1">
        <h1 className="font-display font-bold text-base sm:text-xl text-[#1A1208] dark:text-[#FDFCFA] tracking-tight flex items-center gap-2">
          <span>{greeting}، {(userData.full_name || userData.username || 'دوست').split(' ')[0]} 👋</span>
        </h1>
        <div className="text-xs text-[#7A6852] dark:text-[#A89580] flex items-center gap-1.5 bg-[#FFFCF7] dark:bg-[#1C1612] px-3 py-1 rounded-full border border-[#EFE6D8] dark:border-[#2A2218] shadow-sm">
          <SiteImage imageKey="icon_calendar" fallback="📅" alt="تاریخ" className="w-3.5 h-3.5 object-contain opacity-70" />
          <span>{today}</span>
        </div>
      </div>

      <CartBanner cart={cart} />

      {/* ⚠️ Pending Payment Alert — Warm Callout */}
      {stats.pending_payments > 0 && (
        <Link
          to="/panel/orders"
          className="group block bg-amber-50 dark:bg-amber-500/10 border border-amber-200 dark:border-amber-500/20 rounded-2xl p-3 hover:bg-amber-100/50 dark:hover:bg-amber-500/20 transition-all relative overflow-hidden"
        >
          <div className="flex items-center gap-3 relative">
            <div className="w-9 h-9 rounded-full bg-amber-100 dark:bg-amber-500/20 flex items-center justify-center flex-shrink-0 text-amber-600 dark:text-amber-400">
              <SiteImage imageKey="icon_warning" fallback="⚠️" className="w-4.5 h-4.5 object-contain" />
            </div>
            <div className="flex-1 min-w-0">
              <div className="font-bold text-amber-900 dark:text-amber-200 text-sm truncate">
                {stats.pending_payments === 1
                  ? 'یک پرداخت در انتظار اقدام است'
                  : <><span className="font-num">{toFa(stats.pending_payments)}</span> پرداخت در انتظار اقدام</>
                }
              </div>
              <div className="text-xs text-amber-700 dark:text-amber-400/80 truncate mt-0.5">
                برای جلوگیری از تأخیر، فیش واریزی خود را آپلود کنید.
              </div>
            </div>
            <span className="text-amber-600 dark:text-amber-400 flex-shrink-0 group-hover:-translate-x-1 transition-transform" aria-hidden="true">
              <SiteImage imageKey="icon_arrow_left" fallback="←" className="w-4 h-4 object-contain" />
            </span>
          </div>
        </Link>
      )}

      {/* Stats Inline Row */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
        <StatPill
          icon="📦"
          imageKey="icon_orders"
          value={toFa(stats.total_orders)}
          label="سفارش‌ها"
          to="/panel/orders"
          accent="default"
        />
        <StatPill
          icon="🐕"
          imageKey="icon_dog"
          value={toFa(stats.total_dogs)}
          label="سگ‌های من"
          to="/panel/dogs"
          accent="default"
        />
        <StatPill
          icon="⏳"
          imageKey="icon_pending"
          value={toFa(stats.pending_payments)}
          label="در انتظار"
          to="/panel/orders"
          accent={stats.pending_payments > 0 ? 'warning' : 'default'}
        />
        <StatPill
          icon="🎧"
          imageKey="icon_ticket"
          value={toFa(stats.open_tickets)}
          label="پشتیبانی"
          to="/panel/tickets"
          accent={stats.open_tickets > 0 ? 'rose' : 'default'}
        />
      </div>

      {/* Main Content */}
      {!hasAnyActivity ? (
        <GettingStartedCard hasDogs={false} />
      ) : (
        <div className="space-y-3 sm:space-y-5">

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-3 sm:gap-4">

            {/* ===== آخرین سفارش ===== */}
            {last_order ? (
              <div className="bg-[#FFFCF7] dark:bg-[#1C1612] border border-[#EFE6D8] dark:border-[#2A2218] rounded-2xl shadow-sm overflow-hidden flex flex-col">
                <SectionHeader
                  title="آخرین سفارش"
                  subtitle={`#${toFa(last_order.id)} · برای ${last_order.dog_name}`}
                  to={`/panel/orders/${last_order.id}`}
                  linkLabel="جزئیات کامل"
                />

                <div className="p-4 flex-1 flex flex-col">
                  <div className="flex items-start justify-between gap-3 mb-3">
                    <div className="flex items-center gap-2 flex-wrap">
                      {(() => {
                        const cfg = STATUS_LABELS[last_order.status] || STATUS_LABELS.pending;
                        return (
                          <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-bold border ${cfg.color}`}>
                            {cfg.icon} {cfg.text}
                          </span>
                        );
                      })()}
                    </div>

                    <div className="text-left flex-shrink-0 bg-[#F9F4EC] dark:bg-[#1F1812] py-1.5 px-2.5 rounded-xl">
                      <div className="font-display font-bold text-base text-[#1A1208] dark:text-[#FDFCFA] font-num leading-tight">
                        {toFaShort(last_order.total_price)}
                      </div>
                      <div className="text-[10px] text-[#A89478] dark:text-[#6B5A48] font-medium">تومان</div>
                    </div>
                  </div>

                  <div className="flex-1">
                    <MiniStepper status={last_order.status} />
                  </div>

                  <div className="mt-3 flex items-center justify-between text-[11px] text-[#7A6852] dark:text-[#A89580] border-t border-[#F4EDE0] dark:border-[#2A2218] pt-2.5">
                    <span className="flex items-center gap-1 font-medium">
                      <SiteImage imageKey="icon_calendar" fallback="📅" alt="" className="w-3.5 h-3.5 object-contain opacity-60" />
                      {toFaDate(last_order.created_at, { year: 'numeric', month: 'long', day: 'numeric' })}
                    </span>
                    <span className="flex items-center gap-1 font-medium">
                      <SiteImage imageKey="icon_clock" fallback="⏱️" alt="" className="w-3.5 h-3.5 object-contain opacity-60" />
                      {toFaTimeAgo(last_order.created_at)}
                    </span>
                  </div>
                </div>
              </div>
            ) : (
              <div className="bg-[#FFFCF7] dark:bg-[#1C1612] border border-dashed border-[#E8DFD3] dark:border-[#2A2218] rounded-2xl p-5 flex flex-col items-center justify-center text-center shadow-sm">
                <div className="w-14 h-14 rounded-full bg-[#F9F4EC] dark:bg-[#1F1812] flex items-center justify-center mb-2.5">
                  <SiteImage imageKey="icon_orders" fallback="📦" className="w-7 h-7 object-contain opacity-40" />
                </div>
                <div className="text-sm font-bold text-[#1A1208] dark:text-[#FDFCFA] mb-1">
                  هنوز سفارشی ثبت نکرده‌اید
                </div>
                <div className="text-xs text-[#7A6852] dark:text-[#A89580] mb-3">
                  اولین سفارش خود را ثبت کنید تا اینجا نمایش داده شود.
                </div>
                <Link
                  to={ORDER_FORM_PATH}
                  className="inline-flex items-center gap-1.5 min-h-[36px] px-3.5 py-1.5 bg-[#FFF4EB] dark:bg-[#C87941]/10 text-[#C87941] dark:text-[#D99B4D] rounded-xl text-xs font-bold transition hover:bg-[#FFE8D6] dark:hover:bg-[#C87941]/20"
                >
                  <SiteImage imageKey="icon_plus" fallback="➕" alt="" className="w-3.5 h-3.5 object-contain" />
                  <span>ثبت سفارش جدید</span>
                </Link>
              </div>
            )}

            {/* ===== سگ‌های من ===== */}
            <div className="bg-[#FFFCF7] dark:bg-[#1C1612] border border-[#EFE6D8] dark:border-[#2A2218] rounded-2xl shadow-sm overflow-hidden flex flex-col">
              <SectionHeader
                title="سگ‌های من"
                subtitle={dogs.length > 0 ? `${toFa(dogs.length)} سگ ثبت‌شده` : 'لیست خالی است'}
                to="/panel/dogs"
                linkLabel="مدیریت سگ‌ها"
              />

              <div className="p-3 flex-1">
                {dogs.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-5 text-center">
                    <div className="w-14 h-14 rounded-full bg-[#F9F4EC] dark:bg-[#1F1812] flex items-center justify-center mb-2.5">
                      <SiteImage imageKey="icon_dog" fallback="🐕" className="w-7 h-7 object-contain opacity-40" />
                    </div>
                    <div className="text-sm font-bold text-[#1A1208] dark:text-[#FDFCFA] mb-1">
                      هنوز سگی اضافه نکرده‌اید
                    </div>
                    <div className="text-xs text-[#7A6852] dark:text-[#A89580] mb-3">
                      برای ثبت سفارش سریع‌تر، سگ خود را اضافه کنید.
                    </div>
                    <Link
                      to="/panel/dogs"
                      className="inline-flex items-center gap-1.5 min-h-[36px] px-3.5 py-1.5 bg-[#F9F4EC] dark:bg-[#1F1812] border border-[#E8DFD3] dark:border-[#2A2218] text-[#5C4A38] dark:text-[#A89580] rounded-xl text-xs font-bold transition hover:bg-[#F4EDE0] dark:hover:bg-[#241C15]"
                    >
                      <SiteImage imageKey="icon_plus" fallback="➕" alt="" className="w-3.5 h-3.5 object-contain" />
                      <span>افزودن سگ</span>
                    </Link>
                  </div>
                ) : (
                  <div className="grid grid-cols-2 gap-2.5">
                    {dogs.slice(0, 4).map(dog => (
                      <Link
                        key={dog.id}
                        to={`/panel/dogs/${dog.id}`}
                        className="group flex flex-col items-center justify-center p-2.5 rounded-xl bg-[#F9F4EC] dark:bg-white/[0.02] border border-transparent hover:border-[#E8DFD3] dark:hover:border-[#2A2218] hover:bg-[#FFFCF7] dark:hover:bg-[#1F1812] transition-all duration-300"
                      >
                        <div className="relative mb-1.5">
                          <div className={`w-12 h-12 bg-gradient-to-br ${getAvatarGradient(dog.id)} rounded-full flex items-center justify-center text-white font-display font-bold text-lg shadow-sm group-hover:scale-105 transition-transform`}>
                            {dog.name.charAt(0).toUpperCase()}
                          </div>
                          <div className="absolute bottom-0 right-0 w-3.5 h-3.5 rounded-full border-2 border-[#F9F4EC] dark:border-[#1C1612] bg-emerald-500"></div>
                        </div>
                        <div className="text-sm font-bold text-[#1A1208] dark:text-[#FDFCFA] truncate w-full text-center mb-1">
                          {dog.name}
                        </div>
                        <div className="flex items-center justify-center gap-1.5 text-[10px] text-[#7A6852] dark:text-[#A89580] font-num bg-[#FFFCF7] dark:bg-[#1C1612] px-1.5 py-0.5 rounded-lg w-full shadow-sm border border-[#EFE6D8] dark:border-[#2A2218]">
                          <span>⚖️ {toFa(dog.weight_kg)}</span>
                          <span className="w-px h-2.5 bg-[#E8DFD3] dark:bg-[#2A2218]"></span>
                          <span>🎂 {toFa(dog.age_months)}</span>
                        </div>
                      </Link>
                    ))}

                    {dogs.length > 4 && (
                      <Link
                        to="/panel/dogs"
                        className="flex flex-col items-center justify-center p-2.5 rounded-xl border-2 border-dashed border-[#E8DFD3] dark:border-[#2A2218] hover:border-[#C87941]/40 dark:hover:border-[#D99B4D]/40 transition text-xs font-bold text-[#A89478] dark:text-[#6B5A48] min-h-[92px]"
                      >
                        <span className="text-xl mb-1 opacity-50">+</span>
                        <span>{toFa(dogs.length - 4)} سگ دیگر</span>
                      </Link>
                    )}
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* Recent Orders List */}
          {recent_orders.length > 0 && (
            <div className="bg-[#FFFCF7] dark:bg-[#1C1612] border border-[#EFE6D8] dark:border-[#2A2218] rounded-2xl shadow-sm overflow-hidden">
              <SectionHeader
                title="آخرین سفارش‌ها"
                subtitle={`${toFa(recent_orders.length)} سفارش اخیر`}
                to="/panel/orders"
                linkLabel="مشاهده همه"
              />

              <div className="p-1.5">
                <div className="flex flex-col gap-0.5">
                  {recent_orders.map(order => {
                    const cfg = STATUS_LABELS[order.status] || STATUS_LABELS.pending;
                    return (
                      <Link
                        key={order.id}
                        to={`/panel/orders/${order.id}`}
                        className="flex items-center gap-3 p-2.5 rounded-xl hover:bg-[#F4EDE0] dark:hover:bg-[#1F1812] transition-colors group border border-transparent"
                      >
                        <div className={`w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0 text-base ${cfg.color}`}>
                          {cfg.imageKey ? (
                            <SiteImage imageKey={cfg.imageKey} fallback={cfg.icon} alt="" className="w-4 h-4 object-contain" />
                          ) : (
                            <span aria-hidden="true">{cfg.icon}</span>
                          )}
                        </div>

                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 mb-0.5">
                            <span className="text-sm font-bold text-[#1A1208] dark:text-[#FDFCFA] font-num">
                              #{toFa(order.id)}
                            </span>
                            <span className="text-xs text-[#7A6852] dark:text-[#A89580]">
                              برای {order.dog_name}
                            </span>
                          </div>
                          <div className="flex items-center gap-2 text-[11px] text-[#A89478] dark:text-[#6B5A48]">
                            <span>{toFaTimeAgo(order.created_at)}</span>
                          </div>
                        </div>

                        <div className="text-left flex-shrink-0">
                          <div className="font-bold text-sm text-[#1A1208] dark:text-[#FDFCFA] font-num">
                            {toFaShort(order.total_price)} <span className="text-[10px] font-normal opacity-70">تومان</span>
                          </div>
                        </div>

                        <SiteImage imageKey="icon_arrow_left" fallback="←" alt="" className="w-3.5 h-3.5 object-contain text-[#D8C4A8] dark:text-[#3A2E20] group-hover:text-[#C87941] dark:group-hover:text-[#D99B4D] group-hover:-translate-x-1 transition-all flex-shrink-0 hidden sm:inline" />
                      </Link>
                    );
                  })}
                </div>
              </div>
            </div>
          )}
        </div>
      )}

    </div>
  );
}