// frontend/src/user/components/EmptyState.jsx
// ✅ v2.1: اصلاح semantic باگ در EmptySearch (icon_error → icon_close)
import React, { useId } from 'react';
import { SiteImage } from '../../utils/SiteImage';

// ============================================================
//  📐 SIZE_CONFIG — تنظیمات هر سایز
// ============================================================
const SIZE_CONFIG = {
  sm: {
    wrapper: 'p-6 sm:p-8',
    iconBox: 'w-14 h-14 text-2xl mb-4 rounded-2xl',
    title: 'text-base sm:text-lg',
    desc: 'text-xs sm:text-sm mt-2',
    gap: 'mt-5 sm:mt-6',
    btn: 'px-4 py-2 text-xs min-h-[40px]',
    btnFull: 'w-full sm:w-auto',
    useNoise: false,
  },
  md: {
    wrapper: 'p-8 sm:p-12',
    iconBox: 'w-20 h-20 text-4xl mb-5 rounded-3xl',
    title: 'text-lg sm:text-xl',
    desc: 'text-sm mt-2.5',
    gap: 'mt-6 sm:mt-7',
    btn: 'px-5 py-2.5 text-sm min-h-[44px]',
    btnFull: 'w-full sm:w-auto',
    useNoise: true,
  },
  lg: {
    wrapper: 'p-10 sm:p-16',
    iconBox: 'w-24 h-24 text-5xl mb-6 rounded-3xl',
    title: 'text-xl sm:text-2xl',
    desc: 'text-sm sm:text-base mt-3',
    gap: 'mt-7 sm:mt-8',
    btn: 'px-6 py-3 text-sm min-h-[48px]',
    btnFull: 'w-full sm:w-auto',
    useNoise: true,
  },
};

// ============================================================
//  🎨 BUTTON_VARIANTS — پالت Editorial
// ============================================================
const BUTTON_VARIANTS = {
  primary:
    'bg-brand-gradient hover:opacity-95 active:opacity-90 text-white shadow-brand hover:shadow-brand-lg',
  secondary:
    'bg-paper-100 dark:bg-ink-800 hover:bg-paper-200 dark:hover:bg-ink-700 active:bg-paper-300 text-ink-800 dark:text-cream-100 border border-ink-200 dark:border-dark-700',
  ghost:
    'bg-transparent hover:bg-paper-200 dark:hover:bg-ink-800 active:bg-paper-300 text-ink-700 dark:text-cream-200',
  danger:
    'bg-rose-500 hover:bg-rose-600 active:bg-rose-700 text-white shadow-soft hover:shadow-lifted',
};

// ============================================================
//  🔘 EmptyAction — دکمه با استایل Editorial
// ============================================================
function EmptyAction({
  label,
  onClick,
  variant = 'primary',
  icon,
  iconKey,
  size = 'md',
}) {
  const cfg = SIZE_CONFIG[size] || SIZE_CONFIG.md;
  const variantClass = BUTTON_VARIANTS[variant] || BUTTON_VARIANTS.primary;

  return (
    <button
      type="button"
      onClick={onClick}
      className={`${cfg.btn} ${cfg.btnFull} ${variantClass} rounded-2xl font-black transition-all duration-300 flex items-center justify-center gap-2 touch-target hover:-translate-y-0.5 active:translate-y-0`}
    >
      {iconKey ? (
        <SiteImage
          imageKey={iconKey}
          fallback={icon}
          alt=""
          className="w-4 h-4 object-contain flex-shrink-0"
        />
      ) : (
        icon && (
          <span className="text-base flex-shrink-0" aria-hidden="true">
            {icon}
          </span>
        )
      )}
      <span className="truncate">{label}</span>
    </button>
  );
}

// ============================================================
//  📭 EmptyState اصلی
//  ✅ role="region" + aria-labelledby برای دسترسی‌پذیری
//  ✅ useId برای شناسهٔ یکتا
//  ✅ noise-overlay فقط در سایزهای md/lg (کارایی)
//  ✅ imageKey برای عکس قابل تغییر از پنل ادمین
//  ✅ overflow-hidden و absolute در کادر عکس برای جلوگیری از بزرگ شدن بی‌نهایت
// ============================================================
export default function EmptyState({
  icon = '📭',
  imageKey,
  title,
  description,
  actions = [],
  size = 'md',
  className = '',
}) {
  const cfg = SIZE_CONFIG[size] || SIZE_CONFIG.md;
  const titleId = useId();
  const hasTitle = Boolean(title);

  return (
    <div
      role="region"
      aria-labelledby={hasTitle ? titleId : undefined}
      className={`
        relative bg-paper-50 dark:bg-ink-800/60
        rounded-3xl border border-ink-200 dark:border-dark-700
        shadow-soft text-center overflow-hidden
        ${cfg.useNoise ? 'noise-overlay' : ''}
        ${cfg.wrapper}
        ${className}
      `}
      dir="rtl"
    >
      {/* Overline تزئینی بالا */}
      <div
        className="absolute top-0 right-1/2 translate-x-1/2 w-16 h-0.5 bg-brand-500"
        aria-hidden="true"
      />

      {/* آیکون در badge */}
      <div
        className={`relative mx-auto bg-paper-100 dark:bg-ink-900 flex items-center justify-center shadow-soft overflow-hidden flex-shrink-0 ${cfg.iconBox}`}
        aria-hidden="true"
      >
        {imageKey ? (
          <SiteImage
            imageKey={imageKey}
            fallback={icon}
            alt=""
            className="absolute inset-0 w-full h-full object-contain p-2"
          />
        ) : (
          <span className="leading-none select-none">{icon}</span>
        )}
      </div>

      {/* عنوان */}
      {title && (
        <h3
          id={titleId}
          className={`font-display font-black text-ink-900 dark:text-cream-100 tracking-tight break-safe ${cfg.title}`}
        >
          {title}
        </h3>
      )}

      {/* توضیحات */}
      {description && (
        <p
          className={`text-ink-500 dark:text-cream-400 ${cfg.desc} max-w-md mx-auto leading-relaxed px-2 break-safe`}
        >
          {description}
        </p>
      )}

      {/* دکمه‌ها */}
      {actions.length > 0 && (
        <div
          className={`flex flex-col sm:flex-row flex-wrap items-stretch sm:items-center justify-center gap-2.5 ${cfg.gap} max-w-xs sm:max-w-none mx-auto`}
        >
          {actions.map((action, idx) => (
            <EmptyAction key={idx} {...action} size={size} />
          ))}
        </div>
      )}
    </div>
  );
}

// ============================================================
//  🎁 Empty States آماده — کپی‌پیست
// ============================================================

// ===== ۱. جستجو بدون نتیجه =====
export function EmptySearch({ searchTerm, onClear, size = 'md', className = '' }) {
  const MAX_TERM_LEN = 40;
  const safeTerm =
    searchTerm && searchTerm.length > MAX_TERM_LEN
      ? searchTerm.slice(0, MAX_TERM_LEN) + '…'
      : searchTerm;

  return (
    <EmptyState
      icon="🔍"
      imageKey="empty_state_search"
      title="نتیجه‌ای یافت نشد"
      description={
        safeTerm
          ? `عبارت «${safeTerm}» در هیچ موردی پیدا نشد.`
          : 'با این فیلترها نتیجه‌ای پیدا نشد.'
      }
      actions={
        onClear
          ? [
              {
                label: 'پاک کردن فیلترها',
                onClick: onClear,
                variant: 'secondary',
                icon: '✕',
                iconKey: 'icon_close',
              },
            ]
          : []
      }
      size={size}
      className={className}
    />
  );
}

// ===== ۲. سفارش‌ها =====
export function EmptyOrders({ onGoToNewOrder, size = 'md', className = '' }) {
  const actions = [];
  if (onGoToNewOrder) {
    actions.push({
      label: 'ثبت سفارش جدید',
      onClick: onGoToNewOrder,
      variant: 'primary',
      icon: '➕',
      iconKey: 'icon_plus',
    });
  }

  return (
    <EmptyState
      icon="📦"
      imageKey="empty_state_orders"
      title="هنوز سفارشی ثبت نکردی"
      description="با ثبت اولین سفارش، اینجا نمایش داده می‌شه."
      actions={actions}
      size={size}
      className={className}
    />
  );
}

