function SegmentedControl({ name, value, onChange, options, columns = 2, disabled = false }) {
  return (
    <div className={`grid gap-1.5 ${columns === 1 ? 'grid-cols-1' : columns === 2 ? 'grid-cols-2' : columns === 3 ? 'grid-cols-3' : 'grid-cols-1'}`}>
      {options.map(opt => {
        const isActive = value === opt.value;
        return (
          <button
            key={opt.value}
            type="button"
            onClick={() => onChange({ target: { name, value: opt.value, type: 'select' } })}
            disabled={disabled}
            className={`min-h-[40px] px-3 py-2 rounded-md border text-xs font-medium transition-colors text-right ${
              isActive
                ? 'bg-brand-50 dark:bg-brand-500/10 border-brand-500 dark:border-brand-500/40 text-brand-700 dark:text-brand-300'
                : 'bg-paper-50 dark:bg-ink-800 border-ink-200 dark:border-dark-600 text-ink-700 dark:text-cream-200 hover:border-ink-300 dark:hover:border-dark-500 hover:bg-paper-100 dark:hover:bg-ink-700'
            } ${disabled ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}`}
          >
            <div className="flex items-center justify-between gap-2">
              <span className="truncate">{opt.label}</span>
              {isActive && (
                <svg className="w-3.5 h-3.5 flex-shrink-0 text-brand-600 dark:text-brand-400" viewBox="0 0 20 20" fill="currentColor" aria-hidden="true">
                  <path fillRule="evenodd" d="M16.704 4.153a.75.75 0 01.143 1.052l-8 10.5a.75.75 0 01-1.127.075l-4.5-4.5a.75.75 0 011.06-1.06l3.894 3.893 7.48-9.817a.75.75 0 011.05-.143z" clipRule="evenodd" />
                </svg>
              )}
            </div>
            {opt.desc && !isActive && (
              <div className="text-[10px] font-normal text-ink-400 dark:text-cream-500 mt-0.5 truncate">
                {opt.desc}
              </div>
            )}
          </button>
        );
      })}
    </div>
  );
}

// ============================================================
//  Wizard steps
// ============================================================
const WIZARD_STEPS = [
  { id: 1, label: 'اطلاعات پایه' },
  { id: 2, label: 'وضعیت سلامت' },
  { id: 3, label: 'سبک زندگی' },
  { id: 4, label: 'آلرژی‌ها' },
];

function StepIndicator({ currentStep }) {
  return (
    <div className="flex items-center justify-between gap-1">
      {WIZARD_STEPS.map((step, idx) => {
        const isDone = step.id < currentStep;
        const isActive = step.id === currentStep;
        const isLast = idx === WIZARD_STEPS.length - 1;

        return (
          <React.Fragment key={step.id}>
            <div className="flex flex-col items-center gap-1 min-w-0 flex-1">
              <div
                className={`w-6 h-6 rounded-full flex items-center justify-center text-[10px] font-bold border transition-colors flex-shrink-0 ${
                  isDone
                    ? 'bg-accent-500 border-accent-500 text-white'
                    : isActive
                    ? 'bg-ink-900 dark:bg-cream-100 border-ink-900 dark:border-cream-100 text-cream-50 dark:text-ink-900'
                    : 'bg-transparent border-ink-300 dark:border-dark-500 text-ink-400 dark:text-cream-500'
                }`}
                aria-hidden="true"
              >
                {isDone ? (
                  <svg className="w-3 h-3" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M16.704 4.153a.75.75 0 01.143 1.052l-8 10.5a.75.75 0 01-1.127.075l-4.5-4.5a.75.75 0 011.06-1.06l3.894 3.893 7.48-9.817a.75.75 0 011.05-.143z" clipRule="evenodd" />
                  </svg>
                ) : toFa(step.id)}
              </div>
              <span className={`text-[9px] font-medium whitespace-nowrap truncate ${
                isDone || isActive ? 'text-ink-700 dark:text-cream-200' : 'text-ink-400 dark:text-cream-500'
              }`}>
                {step.label}
              </span>
            </div>
            {!isLast && (
              <div className={`flex-1 h-px mb-3.5 mx-1 ${step.id < currentStep ? 'bg-accent-500' : 'bg-ink-200 dark:bg-dark-600'}`} />
            )}
          </React.Fragment>
        );
      })}
    </div>
  );
}

// ============================================================
//  DogAvatarUploader
// ============================================================
function DogAvatarUploader({ dog, onAvatarChange }) {
  const { showToast } = useToast();
  const [uploading, setUploading] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [imgError, setImgError] = useState(false);
  const [dragOver, setDragOver] = useState(false);
  const fileInputRef = useRef(null);

  const avatarUrl = dog?.avatar_url;
  const initial = (dog?.name || '?').charAt(0).toUpperCase();
  const gradient = getAvatarGradient(dog?.id);
  const fullUrl = resolveAssetUrl(avatarUrl);

  useEffect(() => {
    setImgError(false);
  }, [avatarUrl]);

  const validateAndUpload = async (file) => {
    if (!file) return;

    const allowedTypes = ['image/jpeg', 'image/png', 'image/webp', 'image/jpg'];
    if (!allowedTypes.includes(file.type)) {
      showToast('error', 'فقط فرمت‌های JPG، PNG، WEBP مجاز هستند');
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    const MAX_SIZE = 2 * 1024 * 1024;
    if (file.size > MAX_SIZE) {
      const sizeMB = toFaDecimal(file.size / (1024 * 1024), 1);
      showToast('error', `حجم فایل ${sizeMB} مگابایت است. حداکثر مجاز: ۲ مگابایت`);
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    setUploading(true);
    setImgError(false);

    try {
      const formData = new FormData();
      formData.append('file', file);

      const res = await userAxios.post(
        `/api/dogs/${dog.id}/avatar`,
        formData,
        { headers: { 'Content-Type': 'multipart/form-data' } }
      );

      const newUrl = res.data.avatar_url;
      onAvatarChange?.(newUrl);
      showToast('success', 'عکس پروفایل آپلود شد');
      if (fileInputRef.current) fileInputRef.current.value = '';
    } catch (err) {
      const detail = err.response?.data?.detail;
      showToast('error', typeof detail === 'string' ? detail : 'خطا در آپلود عکس');
    } finally {
      setUploading(false);
    }
  };

  const handleFileSelect = (e) => {
    const file = e.target.files?.[0];
    validateAndUpload(file);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setDragOver(false);
    if (uploading || deleting) return;
    const file = e.dataTransfer.files?.[0];
    validateAndUpload(file);
  };

  const handleRemove = async () => {
    if (!avatarUrl) return;
    if (!window.confirm('عکس پروفایل این سگ حذف شود؟')) return;

    setDeleting(true);
    try {
      await userAxios.delete(`/api/dogs/${dog.id}/avatar`);
      onAvatarChange?.(null);
      showToast('success', 'عکس پروفایل حذف شد');
    } catch (err) {
      const detail = err.response?.data?.detail;
      showToast('error', typeof detail === 'string' ? detail : 'خطا در حذف عکس');
    } finally {
      setDeleting(false);
    }
  };

  const busy = uploading || deleting;

  return (
    <div className="flex flex-col items-start gap-2 flex-shrink-0">
      <div
        onClick={() => !busy && fileInputRef.current?.click()}
        onDragOver={(e) => {
          e.preventDefault();
          if (!busy) setDragOver(true);
        }}
        onDragLeave={() => setDragOver(false)}
        onDrop={handleDrop}
        className={`relative w-20 h-20 sm:w-24 sm:h-24 rounded-lg overflow-hidden cursor-pointer transition-all ${
          dragOver
            ? 'ring-2 ring-brand-500 scale-105'
            : 'ring-2 ring-paper-100 dark:ring-ink-700 shadow-sm hover:ring-brand-200 dark:hover:ring-brand-500/30'
        } ${busy ? 'cursor-wait' : ''}`}
        title={avatarUrl ? 'برای تغییر عکس کلیک یا فایل را رها کن' : 'برای آپلود عکس کلیک یا فایل را رها کن'}
      >
        {fullUrl && !imgError ? (
          <img
            src={fullUrl}
            alt={dog.name}
            className="w-full h-full object-cover"
            onError={() => setImgError(true)}
          />
        ) : (
          <div className={`w-full h-full bg-gradient-to-br ${gradient} flex items-center justify-center text-white font-bold text-3xl`}>
            {initial}
          </div>
        )}

        {!busy && (
          <div className="absolute inset-0 bg-ink-900/0 hover:bg-ink-900/50 transition flex items-center justify-center opacity-0 hover:opacity-100">
            <svg className="w-5 h-5 text-white" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
              <path d="M23 19a2 2 0 01-2 2H3a2 2 0 01-2-2V8a2 2 0 012-2h4l2-3h6l2 3h4a2 2 0 012 2z" />
              <circle cx="12" cy="13" r="4" />
            </svg>
          </div>
        )}

        {(uploading || deleting) && (
          <div className="absolute inset-0 bg-ink-900/60 backdrop-blur-sm flex items-center justify-center">
            <span className="inline-block w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin" />
          </div>
        )}
      </div>

      <div className="flex items-center gap-1.5">
        <button
          type="button"
          onClick={(e) => {
            e.stopPropagation();
            fileInputRef.current?.click();
          }}
          disabled={busy}
          className="min-h-[40px] px-3 py-2 text-xs font-medium text-ink-600 dark:text-cream-300 hover:text-brand-600 dark:hover:text-brand-400 hover:bg-brand-50 dark:hover:bg-brand-500/10 rounded-md transition disabled:opacity-50"
        >
          {avatarUrl ? 'تغییر عکس' : 'افزودن عکس'}
        </button>

        {avatarUrl && (
          <>
            <span className="text-ink-200 dark:text-dark-600" aria-hidden="true">·</span>
            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation();
                handleRemove();
              }}
              disabled={busy}
              className="min-h-[40px] px-3 py-2 text-xs font-medium text-rose-600 dark:text-rose-400 hover:bg-rose-50 dark:hover:bg-rose-500/10 rounded-md transition disabled:opacity-50"
            >
              حذف
            </button>
          </>
        )}
      </div>

      <p className="text-[10px] text-ink-400 dark:text-cream-500 leading-tight">
        JPG, PNG یا WEBP · حداکثر ۲MB
      </p>

      <input
        ref={fileInputRef}
        type="file"
        accept="image/jpeg,image/png,image/webp"
        onChange={handleFileSelect}
        className="hidden"
        disabled={busy}
      />
    </div>
  );
}

